const MASK = (1n << 48n) - 1n;
export class JavaRandom {
  private seed: bigint;
  constructor(seed: number | bigint) { this.seed = (BigInt(seed) ^ 0x5deece66dn) & MASK; }
  private next(bits: number): number { this.seed = (this.seed * 0x5deece66dn + 0xbn) & MASK; return Number(this.seed >> BigInt(48 - bits)); }
  nextDouble(): number { return (this.next(26) * 2 ** 27 + this.next(27)) * 2 ** -53; }
}

