// Cyrus MOTION CORE: the game-neutral MotionSpec v1 (docs: /root/agent-notes/cyrus-designs/v4-motion/MOTION-PLAN.md,
// docs/DOCUMENTATION.md "Cyrus motion core"). One data model for creature gaits, gun cock/fire/reload, hinged doors,
// explosions, fire, smoke, splashes and (expressible now, built later on a vehicle-capable game) wheels, doors, seats
// and a character entering a seat. Per-game details live ONLY in adapters (./adapter.ts, lib/cyrus/designer/motion for
// Minecraft). Pure, client-safe (zod + plain TS), no GPU, no game code, no Nxeon imports.
//
//   Units: 1 = one block = one metre. Rotations: degrees, Euler applied Z * Y * X about the node pivot.
//   Time: integer ticks at 20 Hz (keys may sit on fractional ticks; exporters resample).
//
// The schema holds generous STRUCTURAL limits (MOTION_LIMITS); the per-game limits (caps) are validation issues
// (./validate.ts), so an over-budget draft still opens in the studio and says exactly what a game would refuse.
import { z } from "zod";
import { EASES } from "./math";

export const MOTION_SPEC_VERSION = 1 as const;
export const MOTION_SPEC_MIME = "application/vnd.cyrus.motion+json";
export const TICK_RATE = 20;

/** Hard structural limits (inclusive) of any MotionSpec, whatever the game. */
export const MOTION_LIMITS = {
  nodes: 64, depth: 8, clips: 32, tracksPerClip: 96, keysPerTrack: 128, durationTicks: 6000, machines: 8, states: 32, transitions: 64,
  vars: 8, actions: 8, guards: 4, emitters: 4, colors: 4, tags: 12, coord: 64, specBytes: 128 * 1024,
} as const;

export const NODE_KINDS = ["bone", "part", "socket", "hinge", "wheel", "seat", "emitter"] as const;
export type NodeKind = (typeof NODE_KINDS)[number];
export const TRACK_KINDS = ["transform", "particle", "sound", "material", "event"] as const;
export type TrackKind = (typeof TRACK_KINDS)[number];
export const CHANNELS = ["pos", "rot", "scale"] as const;
export type Channel = (typeof CHANNELS)[number];
export const LOOPS = ["once", "loop", "hold", "pingpong"] as const;
export type LoopMode = (typeof LOOPS)[number];
export const MATERIAL_CHANNELS = ["emissive", "opacity", "tint", "frame", "brightness"] as const;
export type MaterialChannel = (typeof MATERIAL_CHANNELS)[number];
export const AXES = ["x", "y", "z"] as const;
export type Axis = (typeof AXES)[number];
/** Particle sprite families every adapter maps to its own particles (Minecraft: data-free vanilla particles). */
export const SPRITES = ["spark", "flame", "smoke", "glow", "droplet", "bubble", "debris", "dust", "flash"] as const;
export type Sprite = (typeof SPRITES)[number];
export const EMITTER_SHAPES = ["point", "sphere", "cone", "disc"] as const;
export const SOURCES = ["preset", "generator", "ai", "human"] as const;

export const NAME_RE = /^[a-z][a-z0-9_]{0,23}$/;
export const ID_RE = /^[a-z][a-z0-9_]{1,31}$/;
/** The external character an `attach` event can seat (a player / ped, not a rig node). */
export const ACTOR = "$actor";
/** `sound:<catalog id>` (Sound Library) or a namespaced key (`minecraft:block.wooden_door.open`, `nx_abcd1234:gun.fire`). */
export const SOUND_REF_RE = /^(sound:[a-z0-9][a-z0-9_.-]{1,79}|[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*)$/;
const HEX = /^#[0-9a-f]{6}$/;

const Name = z.string().regex(NAME_RE, "1-24 chars: lowercase letters, digits, _; starts with a letter");
const Id = z.string().regex(ID_RE, "2-32 chars: lowercase letters, digits, _; starts with a letter");
const coord = z.number().min(-MOTION_LIMITS.coord).max(MOTION_LIMITS.coord);
const V3 = z.tuple([coord, coord, coord]);
const Ang = z.tuple([z.number().min(-720).max(720), z.number().min(-720).max(720), z.number().min(-720).max(720)]);
const Scl = z.tuple([z.number().min(0).max(16), z.number().min(0).max(16), z.number().min(0).max(16)]);
const Hex = z.string().regex(HEX, "a colour like #ff8800 (lowercase)");
const Tick = z.number().min(0).max(MOTION_LIMITS.durationTicks);
const Ticks = z.number().int().min(0).max(MOTION_LIMITS.durationTicks);

// ------------------------------------------------------------------------------------------------------- rig
export const RigNodeSchema = z.strictObject({
  name: Name,
  /** parent node name; null = the root (exactly one) */
  parent: Name.nullable(),
  kind: z.enum(NODE_KINDS),
  /** rest-pose pivot in rig space (blocks) */
  pivot: V3,
  rest: z.strictObject({ pos: V3.optional(), rot: Ang.optional(), scale: Scl.optional() }).optional(),
  /** hinge: rotates only about `axis`, within [min, max] degrees (doors, lids, triggers, hammers) */
  hinge: z.strictObject({ axis: z.enum(AXES), min: z.number().min(-360).max(360), max: z.number().min(-360).max(360) }).optional(),
  /** wheel: spins freely about `axle`; front wheels may steer (yaw) within +-steer.max */
  wheel: z.strictObject({ axle: z.enum(AXES), radius: z.number().min(0.05).max(4), steer: z.strictObject({ max: z.number().min(0).max(60) }).optional() }).optional(),
  /** seat: a socket an actor can attach to; facing = yaw of the seated actor */
  seat: z.strictObject({ facing: z.number().min(-180).max(180).optional() }).optional(),
  /** preview-only proxy box (the simulator draws it); real geometry comes from Model Studio or a game binding */
  proxy: z.strictObject({ size: Scl, offset: V3.optional(), color: Hex }).optional(),
});
export type RigNode = z.infer<typeof RigNodeSchema>;

// ---------------------------------------------------------------------------------------------------- tracks
export const KeySchema = z.strictObject({ t: Tick, v: z.tuple([z.number().min(-720).max(720), z.number().min(-720).max(720), z.number().min(-720).max(720)]), ease: z.enum(EASES).optional() });
export type Key = z.infer<typeof KeySchema>;
/** Parametric wave: value = offset + amp * sin(2 pi (cycles * t / length + phase)); the gait primitive (= RigSpec waves). */
export const WaveSchema = z.strictObject({ amp: Ang, offset: Ang.optional(), cycles: z.number().int().min(1).max(16), phase: z.number().min(0).max(1) });
export type Wave = z.infer<typeof WaveSchema>;

export const TransformTrackSchema = z.strictObject({
  kind: z.literal("transform"), node: Name, channel: z.enum(CHANNELS),
  keys: z.array(KeySchema).min(1).max(MOTION_LIMITS.keysPerTrack).optional(),
  wave: WaveSchema.optional(),
});
export const EmitterSchema = z.strictObject({
  sprite: z.enum(SPRITES),
  shape: z.enum(EMITTER_SHAPES).optional(),
  /** sphere / disc radius, blocks */
  radius: z.number().min(0).max(8).optional(),
  /** cone half-angle, degrees, around `dir` */
  cone: z.number().min(0).max(180).optional(),
  /** emission direction in the node's local frame (default +y) */
  dir: z.tuple([z.number().min(-1).max(1), z.number().min(-1).max(1), z.number().min(-1).max(1)]).optional(),
  /** particles at the track start */
  burst: z.number().int().min(0).max(512).optional(),
  /** particles per tick while the track runs (fractions accumulate deterministically) */
  rate: z.number().min(0).max(64).optional(),
  /** lifetime range, ticks */
  life: z.tuple([z.number().int().min(1).max(200), z.number().int().min(1).max(200)]),
  /** initial speed range, blocks per second */
  speed: z.tuple([z.number().min(0).max(40), z.number().min(0).max(40)]),
  /** blocks per second squared, positive = down; negative rises (smoke) */
  gravity: z.number().min(-20).max(40).optional(),
  /** size at birth and at death (blocks) */
  size: z.tuple([z.number().min(0).max(4), z.number().min(0).max(4)]).optional(),
  /** colour ramp over life (1-4 stops) */
  colors: z.array(Hex).min(1).max(MOTION_LIMITS.colors).optional(),
});
export type Emitter = z.infer<typeof EmitterSchema>;
export const ParticleTrackSchema = z.strictObject({
  kind: z.literal("particle"), node: Name, at: Tick,
  /** ticks of continuous emission (0 = burst only) */
  duration: Ticks.optional(),
  /** the catalog preset it came from (`effect:muzzle_flash`), provenance only: the emitters are inline */
  effect: z.string().regex(/^effect:[a-z][a-z0-9_]{1,40}$/).optional(),
  emitters: z.array(EmitterSchema).min(1).max(MOTION_LIMITS.emitters),
  seed: z.number().int().min(0).max(0x7fffffff).optional(),
});
export const SoundTrackSchema = z.strictObject({
  kind: z.literal("sound"), at: Tick, sound: z.string().max(100).regex(SOUND_REF_RE, "sound:<catalog id> or a namespaced key like minecraft:block.wooden_door.open"),
  gain: z.number().min(0).max(2).optional(), pitch: z.number().min(0.5).max(2).optional(), node: Name.optional(),
});
export const MaterialKeySchema = z.strictObject({ t: Tick, v: z.union([z.number().min(0).max(255), Hex]), ease: z.enum(["step", "linear"]).optional() });
export const MaterialTrackSchema = z.strictObject({ kind: z.literal("material"), node: Name, channel: z.enum(MATERIAL_CHANNELS), keys: z.array(MaterialKeySchema).min(1).max(MOTION_LIMITS.keysPerTrack) });
export const EventTrackSchema = z.strictObject({
  kind: z.literal("event"), at: Tick, name: Id,
  /** reparent: `child` (a node or "$actor") onto `socket` (a socket / seat node) */
  attach: z.strictObject({ child: z.string().max(24), socket: Name }).optional(),
  detach: z.strictObject({ child: z.string().max(24) }).optional(),
});
export const TrackSchema = z.discriminatedUnion("kind", [TransformTrackSchema, ParticleTrackSchema, SoundTrackSchema, MaterialTrackSchema, EventTrackSchema]);
export type Track = z.infer<typeof TrackSchema>;
export type TransformTrack = z.infer<typeof TransformTrackSchema>;
export type ParticleTrack = z.infer<typeof ParticleTrackSchema>;
export type SoundTrack = z.infer<typeof SoundTrackSchema>;
export type MaterialTrack = z.infer<typeof MaterialTrackSchema>;
export type EventTrack = z.infer<typeof EventTrackSchema>;

export const ClipSchema = z.strictObject({
  name: Name,
  /** ticks; the clip's time runs 0..length */
  length: z.number().int().min(1).max(MOTION_LIMITS.durationTicks),
  loop: z.enum(LOOPS),
  tracks: z.array(TrackSchema).max(MOTION_LIMITS.tracksPerClip),
});
export type Clip = z.infer<typeof ClipSchema>;

// -------------------------------------------------------------------------------------------- state machines
export const GuardSchema = z.strictObject({ var: Name, op: z.enum(["lt", "le", "eq", "ne", "ge", "gt"]), value: z.number().int().min(-1000).max(1000) });
export type Guard = z.infer<typeof GuardSchema>;
export const ActionSchema = z.discriminatedUnion("do", [
  z.strictObject({ do: z.literal("set"), var: Name, value: z.number().int().min(-1000).max(1000) }),
  z.strictObject({ do: z.literal("add"), var: Name, by: z.number().int().min(-1000).max(1000) }),
  z.strictObject({ do: z.literal("emit"), event: Id }),
]);
export type MachineAction = z.infer<typeof ActionSchema>;
export const StateSchema = z.strictObject({
  name: Name,
  clip: Name.optional(),
  onEnter: z.array(ActionSchema).max(MOTION_LIMITS.actions).optional(),
  /** leave automatically: after `ticks` in the state, or (no ticks) at the end of a `once` clip */
  after: z.strictObject({ to: Name, ticks: Ticks.optional() }).optional(),
});
export type MachineState = z.infer<typeof StateSchema>;
export const TransitionSchema = z.strictObject({
  from: z.union([Name, z.literal("*")]), on: Id, to: Name,
  guard: z.array(GuardSchema).min(1).max(MOTION_LIMITS.guards).optional(),
  /** ignore the event until the current state has run this many ticks (anti-spam) */
  minTicks: Ticks.optional(),
});
export type Transition = z.infer<typeof TransitionSchema>;
export const MachineSchema = z.strictObject({
  name: Name,
  initial: Name,
  vars: z.array(z.strictObject({ name: Name, init: z.number().int().min(-1000).max(1000), min: z.number().int().min(-1000).max(1000), max: z.number().int().min(-1000).max(1000) })).max(MOTION_LIMITS.vars).optional(),
  states: z.array(StateSchema).min(1).max(MOTION_LIMITS.states),
  transitions: z.array(TransitionSchema).max(MOTION_LIMITS.transitions),
});
export type Machine = z.infer<typeof MachineSchema>;

// ------------------------------------------------------------------------------------------------------ spec
export const MotionSpecSchema = z.strictObject({
  schemaVersion: z.literal(MOTION_SPEC_VERSION),
  id: Id,
  title: z.string().min(1).max(60).regex(/^[^\u0000-\u001f]*$/).optional(),
  rig: z.strictObject({ nodes: z.array(RigNodeSchema).min(1).max(MOTION_LIMITS.nodes) }),
  clips: z.array(ClipSchema).min(1).max(MOTION_LIMITS.clips),
  machines: z.array(MachineSchema).max(MOTION_LIMITS.machines).optional(),
  meta: z.strictObject({
    tags: z.array(Id).max(MOTION_LIMITS.tags).optional(),
    source: z.enum(SOURCES).optional(),
    /** catalog preset id (`motion:gun_reload`) or generator id (`gen:gait`) this spec came from */
    preset: z.string().regex(/^(motion|effect|gen):[a-z][a-z0-9_]{1,40}$/).optional(),
    params: z.record(z.string().regex(/^[a-z][a-zA-Z0-9_]{0,31}$/), z.union([z.number(), z.string().max(40), z.boolean()])).optional(),
  }).optional(),
});
export type MotionSpec = z.infer<typeof MotionSpecSchema>;

export function motionJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(MotionSpecSchema, { io: "input", reused: "ref" }) as Record<string, unknown>;
}

// ---------------------------------------------------------------------------------------------- canonical JSON
/** Sorted-key JSON (spec hashing, golden files). */
export function canonicalMotion(v: unknown): string {
  const walk = (x: unknown): unknown => (Array.isArray(x) ? x.map(walk) : x && typeof x === "object" ? Object.fromEntries(Object.keys(x as object).sort().map((k) => [k, walk((x as Record<string, unknown>)[k])])) : x);
  return JSON.stringify(walk(v));
}

export const nodeOf = (s: MotionSpec, name: string) => s.rig.nodes.find((n) => n.name === name);
export const clipOf = (s: MotionSpec, name: string) => s.clips.find((c) => c.name === name);
export const machineOf = (s: MotionSpec, name?: string) => (name ? s.machines?.find((m) => m.name === name) : s.machines?.[0]);

