// Cyrus motion core: per-game CAPS and the motion CAPABILITY an adapter declares in its asset profile
// (lib/cyrus/adapters/asset-profile.ts `motion`). validateMotion(spec, caps) reports every cap a spec breaks; an
// adapter's lower() reports every track it cannot express (dropped). Pure, client-safe.
import type { MaterialChannel, NodeKind, TrackKind } from "./spec";
import { MOTION_LIMITS } from "./spec";

export type MotionCaps = {
  nodes: number;
  depth: number;
  clips: number;
  tracksPerClip: number;
  keysPerTrack: number;
  keysTotal: number;
  durationTicks: number;
  /** worst-case particles spawned in one tick of one clip (bursts + rates) */
  particlesPerTick: number;
  /** worst-case particles one play of a clip spawns */
  particlesPerClip: number;
  soundsPerClip: number;
  machines: number;
  states: number;
  transitions: number;
  /** game entities one live instance needs (e.g. Minecraft: one display per visible part + one interaction) */
  liveEntities: number;
};

export type Support = "native" | "approx" | "none";

export type MotionCapability = {
  game: string;
  /** native simulation rate of the game's lowering (ticks per second) */
  tickRate: number;
  trackKinds: Readonly<Record<TrackKind, Support>>;
  nodeKinds: readonly NodeKind[];
  materialChannels: readonly MaterialChannel[];
  /** can an actor be attached to a seat / socket (vehicles) */
  attach: boolean;
  interpolation: "linear-segments" | "keyframes" | "none";
  caps: MotionCaps;
  /** how the lowered motion reaches players */
  delivery: string;
  maturity: "planned" | "experimental" | "beta" | "stable";
  notes: readonly string[];
};

/** The studio's authoring caps (the structural limits): what the editor accepts before any game is chosen. */
export const NEUTRAL_CAPS: MotionCaps = {
  nodes: MOTION_LIMITS.nodes, depth: MOTION_LIMITS.depth, clips: MOTION_LIMITS.clips, tracksPerClip: MOTION_LIMITS.tracksPerClip, keysPerTrack: MOTION_LIMITS.keysPerTrack,
  keysTotal: 4096, durationTicks: MOTION_LIMITS.durationTicks, particlesPerTick: 2048, particlesPerClip: 20000, soundsPerClip: 64,
  machines: MOTION_LIMITS.machines, states: MOTION_LIMITS.states, transitions: MOTION_LIMITS.transitions, liveEntities: 256,
};

export const NEUTRAL_CAPABILITY: MotionCapability = {
  game: "neutral", tickRate: 20,
  trackKinds: { transform: "native", particle: "native", sound: "native", material: "native", event: "native" },
  nodeKinds: ["bone", "part", "socket", "hinge", "wheel", "seat", "emitter"], materialChannels: ["emissive", "opacity", "tint", "frame", "brightness"],
  attach: true, interpolation: "keyframes", caps: NEUTRAL_CAPS, delivery: "studio preview only", maturity: "beta", notes: ["The studio simulation: every track kind, no game limits."],
};

