// Cyrus motion core: the PURE, DETERMINISTIC sampler. sample(spec, clip, tick) -> Pose; cues(clip, from, to) -> the
// sound / particle / event cues in the half-open window (from, to]; particlesAt(...) -> the live particles of a clip at
// a tick, computed analytically (no integration, so any frame can be rendered on its own). No clock, no Math.random,
// every number rounded to 1e-4 (golden tests are byte-stable). Tick time is the clip's LOCAL time: tick 0 = the clip
// started (a machine state was entered).
import {
  Reuler, Sc, T, apply, applyDir, clamp, ease, hash32, hexToRgb, lerp, mul, mulberry32, r4, r4v, I4,
  type M4, type Vec3,
} from "./math";
import type { Clip, Emitter, MotionSpec, ParticleTrack, RigNode, TransformTrack } from "./spec";
import { TICK_RATE, clipOf, nodeOf } from "./spec";

export type NodePose = { pos: Vec3; rot: Vec3; scale: Vec3 };
export type MaterialPose = { emissive?: number; opacity?: number; tint?: string; frame?: number; brightness?: number };
export type Pose = { nodes: Record<string, NodePose>; material: Record<string, MaterialPose> };

/** Clip time (ticks, 0..length) of a local tick, by loop mode. once/hold clamp; loop wraps; pingpong reflects. */
export function clipTime(clip: Pick<Clip, "length" | "loop">, tick: number): number {
  const L = clip.length;
  if (tick <= 0) return 0;
  switch (clip.loop) {
    case "loop": { const m = tick % L; return m; }
    case "pingpong": { const m = tick % (2 * L); return m <= L ? m : 2 * L - m; }
    default: return Math.min(tick, L);
  }
}

function keyed(track: TransformTrack, t: number): Vec3 {
  const ks = track.keys!;
  if (t <= ks[0].t) return [...ks[0].v] as Vec3;
  const last = ks[ks.length - 1];
  if (t >= last.t) return [...last.v] as Vec3;
  let i = 0;
  while (i < ks.length - 2 && t >= ks[i + 1].t) i++;
  const a = ks[i], b = ks[i + 1];
  const f = b.t === a.t ? 1 : clamp((t - a.t) / (b.t - a.t), 0, 1);
  const e = ease(b.ease, f);
  return [lerp(a.v[0], b.v[0], e), lerp(a.v[1], b.v[1], e), lerp(a.v[2], b.v[2], e)];
}

/** Value of one transform track at clip time t (ticks). Waves and keys are offsets (scale: factors). */
export function sampleTransform(track: TransformTrack, clip: Pick<Clip, "length">, t: number): Vec3 {
  const base = track.channel === "scale" ? 1 : 0;
  if (track.wave) {
    const w = track.wave;
    const a = 2 * Math.PI * ((t / clip.length) * w.cycles + w.phase);
    const s = Math.sin(a);
    return [0, 1, 2].map((k) => base + (w.offset?.[k] ?? 0) + w.amp[k] * s) as Vec3;
  }
  if (!track.keys?.length) return [base, base, base];
  return keyed(track, t);
}

function sampleMaterialKeys(keys: { t: number; v: number | string; ease?: "step" | "linear" }[], t: number): number | string {
  if (t <= keys[0].t) return keys[0].v;
  const last = keys[keys.length - 1];
  if (t >= last.t) return last.v;
  let i = 0;
  while (i < keys.length - 2 && t >= keys[i + 1].t) i++;
  const a = keys[i], b = keys[i + 1];
  if (b.ease !== "linear" || typeof a.v !== typeof b.v) return a.v;
  const f = clamp((t - a.t) / (b.t - a.t || 1), 0, 1);
  if (typeof a.v === "number" && typeof b.v === "number") return lerp(a.v, b.v, f);
  const ca = hexToRgb(a.v as string), cb = hexToRgb(b.v as string);
  return "#" + [0, 1, 2].map((k) => Math.round(lerp(ca[k], cb[k], f)).toString(16).padStart(2, "0")).join("");
}

/** The pose of every rig node at a local tick of a clip (null clip = rest pose). Pure. */
export function sample(spec: MotionSpec, clipName: string | null, tick: number): Pose {
  const clip = clipName ? clipOf(spec, clipName) : undefined;
  const t = clip ? clipTime(clip, tick) : 0;
  const nodes: Record<string, NodePose> = {};
  const material: Record<string, MaterialPose> = {};
  for (const n of spec.rig.nodes) nodes[n.name] = { pos: [0, 0, 0], rot: [0, 0, 0], scale: [1, 1, 1] };
  for (const tr of clip?.tracks ?? []) {
    if (tr.kind === "transform") {
      const p = nodes[tr.node];
      if (!p) continue;
      const v = sampleTransform(tr, clip!, t);
      if (tr.channel === "pos") p.pos = v; else if (tr.channel === "rot") p.rot = v; else p.scale = v;
    } else if (tr.kind === "material") {
      const m = (material[tr.node] ??= {});
      const v = sampleMaterialKeys(tr.keys, t);
      if (tr.channel === "tint") m.tint = typeof v === "string" ? v : undefined;
      else if (typeof v === "number") m[tr.channel] = r4(v);
    }
  }
  for (const k of Object.keys(nodes)) { const p = nodes[k]; p.pos = r4v(p.pos); p.rot = r4v(p.rot); p.scale = r4v(p.scale); }
  return { nodes, material };
}

/** Local matrix of a node for a pose: T(pivot + rest.pos + pos) * R(rest.rot + rot) * S(rest.scale * scale) * T(-pivot). */
export function localMatrix(n: RigNode, p: NodePose | undefined): M4 {
  const rp = n.rest?.pos ?? [0, 0, 0], rr = n.rest?.rot ?? [0, 0, 0], rs = n.rest?.scale ?? [1, 1, 1];
  const pos = p?.pos ?? [0, 0, 0], rot = p?.rot ?? [0, 0, 0], sc = p?.scale ?? [1, 1, 1];
  const [px, py, pz] = n.pivot;
  return mul(T(px + rp[0] + pos[0], py + rp[1] + pos[1], pz + rp[2] + pos[2]), mul(Reuler([rr[0] + rot[0], rr[1] + rot[1], rr[2] + rot[2]]), mul(Sc(rs[0] * sc[0], rs[1] * sc[1], rs[2] * sc[2]), T(-px, -py, -pz))));
}

/** World (rig space) matrix of every node for a pose. A broken parent chain is treated as a root (validate reports it). */
export function worldMatrices(spec: MotionSpec, pose: Pose): Record<string, M4> {
  const out: Record<string, M4> = {};
  const by = new Map(spec.rig.nodes.map((n) => [n.name, n]));
  const world = (name: string, guard: Set<string>): M4 => {
    const hit = out[name];
    if (hit) return hit;
    const n = by.get(name)!;
    const parent = n.parent && by.has(n.parent) && !guard.has(n.parent) ? world(n.parent, new Set([...guard, name])) : null;
    const m = parent ? mul(parent, localMatrix(n, pose.nodes[name])) : localMatrix(n, pose.nodes[name]);
    out[name] = m;
    return m;
  };
  for (const n of spec.rig.nodes) world(n.name, new Set([n.name]));
  return out;
}

/** Node world pivot positions for a pose (handy for tests, emitters and sockets). */
export function nodePositions(spec: MotionSpec, pose: Pose): Record<string, Vec3> {
  const w = worldMatrices(spec, pose);
  return Object.fromEntries(spec.rig.nodes.map((n) => [n.name, r4v(apply(w[n.name] ?? I4(), n.pivot))]));
}

// ------------------------------------------------------------------------------------------------------- cues
export type Cue =
  | { kind: "sound"; t: number; sound: string; gain: number; pitch: number; node?: string; track: number }
  | { kind: "particle"; t: number; node: string; duration: number; effect?: string; track: number }
  | { kind: "event"; t: number; name: string; attach?: { child: string; socket: string }; detach?: { child: string }; track: number };

/**
 * Cues whose time falls in the local-tick window (from, to]. `once`/`hold` clips fire each cue once (cue time inside
 * [0, length)); `loop` fires every cycle; `pingpong` fires on forward passes only. Ordered by time, then track index.
 */
export function cues(clip: Clip, from: number, to: number): Cue[] {
  const out: Cue[] = [];
  if (to <= from) return out;
  const L = clip.length;
  const period = clip.loop === "loop" ? L : clip.loop === "pingpong" ? 2 * L : 0;
  clip.tracks.forEach((tr, i) => {
    if (tr.kind !== "sound" && tr.kind !== "particle" && tr.kind !== "event") return;
    const at = tr.at;
    if (at >= L) return;
    const times: number[] = [];
    if (!period) { if (at > from && at <= to) times.push(at); }
    else {
      const k0 = Math.max(0, Math.floor((from - at) / period));
      for (let k = k0; ; k++) { const t = at + k * period; if (t > to) break; if (t > from) times.push(t); if (times.length > 64) break; }
    }
    for (const t of times) {
      if (tr.kind === "sound") out.push({ kind: "sound", t, sound: tr.sound, gain: tr.gain ?? 1, pitch: tr.pitch ?? 1, ...(tr.node ? { node: tr.node } : {}), track: i });
      else if (tr.kind === "particle") out.push({ kind: "particle", t, node: tr.node, duration: tr.duration ?? 0, ...(tr.effect ? { effect: tr.effect } : {}), track: i });
      else out.push({ kind: "event", t, name: tr.name, ...(tr.attach ? { attach: tr.attach } : {}), ...(tr.detach ? { detach: tr.detach } : {}), track: i });
    }
  });
  return out.sort((a, b) => a.t - b.t || a.track - b.track);
}

// -------------------------------------------------------------------------------------------------- particles
/** Particles an emitter spawns at emission tick k (0 = the track start) of a track running `duration` ticks. */
export function emittedAt(e: Emitter, duration: number, k: number): number {
  let n = k === 0 ? e.burst ?? 0 : 0;
  if (e.rate && k >= 0 && k < Math.max(1, duration)) n += Math.floor((k + 1) * e.rate) - Math.floor(k * e.rate);
  return n;
}
/** Worst-case particles of one track in a single tick, and in total. */
export function particleBudget(tr: ParticleTrack): { perTick: number; total: number } {
  let perTick = 0, total = 0;
  const d = tr.duration ?? 0;
  for (const e of tr.emitters) {
    const r = Math.ceil(e.rate ?? 0);
    perTick += (e.burst ?? 0) + r;
    total += (e.burst ?? 0) + (e.rate ? Math.floor(Math.max(1, d) * e.rate) : 0);
  }
  return { perTick, total };
}

export type LiveParticle = { pos: Vec3; size: number; color: string; age: number; life: number; sprite: Emitter["sprite"]; track: number };

function unitDir(rand: () => number, e: Emitter): Vec3 {
  const shape = e.shape ?? "point";
  const d = e.dir ?? [0, 1, 0];
  const dl = Math.hypot(d[0], d[1], d[2]) || 1;
  const dir: Vec3 = [d[0] / dl, d[1] / dl, d[2] / dl];
  if (shape === "cone") {
    const half = ((e.cone ?? 30) * Math.PI) / 180;
    const cosT = 1 - rand() * (1 - Math.cos(half)), sinT = Math.sqrt(Math.max(0, 1 - cosT * cosT)), ph = rand() * 2 * Math.PI;
    // orthonormal basis around dir
    const a: Vec3 = Math.abs(dir[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
    const u: Vec3 = [dir[1] * a[2] - dir[2] * a[1], dir[2] * a[0] - dir[0] * a[2], dir[0] * a[1] - dir[1] * a[0]];
    const ul = Math.hypot(...u) || 1; u[0] /= ul; u[1] /= ul; u[2] /= ul;
    const v: Vec3 = [dir[1] * u[2] - dir[2] * u[1], dir[2] * u[0] - dir[0] * u[2], dir[0] * u[1] - dir[1] * u[0]];
    return [0, 1, 2].map((k) => dir[k] * cosT + (u[k] * Math.cos(ph) + v[k] * Math.sin(ph)) * sinT) as Vec3;
  }
  if (shape === "disc") { const ph = rand() * 2 * Math.PI; return [Math.cos(ph), 0.15 + rand() * 0.2, Math.sin(ph)]; }
  // sphere / point: uniform on the sphere
  const zc = rand() * 2 - 1, ph = rand() * 2 * Math.PI, rr = Math.sqrt(1 - zc * zc);
  return [rr * Math.cos(ph), zc, rr * Math.sin(ph)];
}

function rampColor(colors: string[] | undefined, f: number): string {
  if (!colors?.length) return "#ffffff";
  if (colors.length === 1) return colors[0];
  const x = clamp(f, 0, 1) * (colors.length - 1), i = Math.min(colors.length - 2, Math.floor(x)), g = x - i;
  const a = hexToRgb(colors[i]), b = hexToRgb(colors[i + 1]);
  return "#" + [0, 1, 2].map((k) => Math.round(lerp(a[k], b[k], g)).toString(16).padStart(2, "0")).join("");
}

/**
 * Every live particle of a clip at a local tick: births are replayed analytically from each emitter's seeded stream,
 * the emitter node's world position/rotation at the birth tick, initial velocity, gravity. Deterministic: the same
 * (spec, clip, tick) always gives the same list. Loops include births from the previous cycle that are still alive.
 */
export function particlesAt(spec: MotionSpec, clipName: string, tick: number, limit = 4000): LiveParticle[] {
  const clip = clipOf(spec, clipName);
  if (!clip) return [];
  const out: LiveParticle[] = [];
  const poseCache = new Map<number, Record<string, M4>>();
  const worldAt = (t: number) => { let w = poseCache.get(t); if (!w) { w = worldMatrices(spec, sample(spec, clipName, t)); poseCache.set(t, w); } return w; };
  clip.tracks.forEach((tr, ti) => {
    if (tr.kind !== "particle") return;
