// Cyrus motion core: the STATE-MACHINE RUNNER. Deterministic, tick-stepped, no clock of its own. Rules (the Minecraft
// runtime in lib/cyrus/designer/motion implements the same ones, and test/cyrus-motion.test.ts holds both to it):
//   at tick T (T = 0 is the start; the initial state's onEnter runs first):
//     1. `after`: when the state has run its `after.ticks` (or reached the end of its `once` clip), leave it;
//     2. inputs queued for T, in order; then events raised by `emit` actions, in order;
//        an event takes the FIRST transition (array order) whose from is the state (or "*"), whose guards all hold and
//        whose minTicks has passed; an event nothing takes is logged as ignored;
//     3. at most MAX_TRANSITIONS_PER_TICK transitions per tick (a loop of emits / zero-tick afters is cut and logged).
//   The entered state's clip starts at local tick 0 on the transition tick. Vars are integers clamped to [min, max].
import type { Guard, Machine, MachineAction, MotionSpec } from "./spec";
import { clipOf, machineOf } from "./spec";

export const MAX_TRANSITIONS_PER_TICK = 8;

export type MachineLog =
  | { tick: number; kind: "enter"; state: string; from: string | null; via: string }
  | { tick: number; kind: "ignored"; event: string; state: string; reason: string }
  | { tick: number; kind: "cut"; state: string; reason: string };
export type MachineFrame = { tick: number; state: string; stateTick: number; clip: string | null; vars: Record<string, number> };

export class MachineRunner {
  readonly machine: Machine;
  readonly log: MachineLog[] = [];
  state = "";
  enteredAt = 0;
  tick = 0;
  vars: Record<string, number> = {};
  private queue: string[] = [];
  private started = false;

  constructor(private readonly spec: MotionSpec, machineName?: string) {
    const m = machineOf(spec, machineName);
    if (!m) throw new Error(`no state machine ${machineName ?? "(first)"} in ${spec.id}`);
    this.machine = m;
    for (const v of m.vars ?? []) this.vars[v.name] = Math.max(v.min, Math.min(v.max, v.init));
  }

  /** Queue an event for the NEXT step (the tick about to run). */
  send(event: string) { this.queue.push(event); }

  private guardOk(g: Guard[] | undefined): boolean {
    for (const x of g ?? []) {
      const v = this.vars[x.var] ?? 0;
      const ok = x.op === "lt" ? v < x.value : x.op === "le" ? v <= x.value : x.op === "eq" ? v === x.value : x.op === "ne" ? v !== x.value : x.op === "ge" ? v >= x.value : v > x.value;
      if (!ok) return false;
    }
    return true;
  }
  private run(actions: MachineAction[] | undefined, emits: string[]) {
    for (const a of actions ?? []) {
      if (a.do === "emit") { emits.push(a.event); continue; }
      const def = this.machine.vars?.find((v) => v.name === a.var);
      if (!def) continue;
      const next = a.do === "set" ? a.value : (this.vars[a.var] ?? 0) + a.by;
      this.vars[a.var] = Math.max(def.min, Math.min(def.max, next));
    }
  }
  private enter(to: string, via: string, emits: string[]) {
    const from = this.started ? this.state : null;
    this.state = to; this.enteredAt = this.tick; this.started = true;
    this.log.push({ tick: this.tick, kind: "enter", state: to, from, via });
    this.run(this.machine.states.find((s) => s.name === to)?.onEnter, emits);
  }
  /** Ticks the `after` of the current state waits for, or null (no automatic exit). */
  afterTicks(state = this.state): number | null {
    const s = this.machine.states.find((x) => x.name === state);
    if (!s?.after) return null;
    if (s.after.ticks !== undefined) return s.after.ticks;
    const c = s.clip ? clipOf(this.spec, s.clip) : undefined;
    return c && c.loop === "once" ? c.length : null;
  }

  /** Run tick `this.tick` (inputs queued with send() apply now) and return its frame; then advance to the next tick. */
  step(): MachineFrame {
    const emits: string[] = [];
    let n = 0;
    if (!this.started) this.enter(this.machine.initial, "initial", emits);
    // 1. after (repeat for zero-tick chains, bounded)
    for (;;) {
      const at = this.afterTicks();
      if (at === null || this.tick - this.enteredAt < at) break;
      if (n >= MAX_TRANSITIONS_PER_TICK) { this.log.push({ tick: this.tick, kind: "cut", state: this.state, reason: `more than ${MAX_TRANSITIONS_PER_TICK} transitions in one tick` }); break; }
      const s = this.machine.states.find((x) => x.name === this.state)!;
      this.enter(s.after!.to, "after", emits); n++;
      if (at > 0) break; // a real timer: one exit per tick
    }
    // 2. inputs, then emitted events
    const events = [...this.queue];
    this.queue = [];
    for (let i = 0; i < events.length + emits.length; i++) {
      const ev = i < events.length ? events[i] : emits[i - events.length];
      const stateTick = this.tick - this.enteredAt;
      const tr = this.machine.transitions.find((t) => (t.from === this.state || t.from === "*") && t.on === ev && this.guardOk(t.guard) && stateTick >= (t.minTicks ?? 0));
      if (!tr) {
        const any = this.machine.transitions.some((t) => (t.from === this.state || t.from === "*") && t.on === ev);
        this.log.push({ tick: this.tick, kind: "ignored", event: ev, state: this.state, reason: any ? "guard or minTicks not met" : "no transition for this event here" });
        continue;
      }
      if (n >= MAX_TRANSITIONS_PER_TICK) { this.log.push({ tick: this.tick, kind: "cut", state: this.state, reason: `more than ${MAX_TRANSITIONS_PER_TICK} transitions in one tick` }); break; }
      this.enter(tr.to, ev, emits); n++;
    }
    const st = this.machine.states.find((x) => x.name === this.state);
    const frame: MachineFrame = { tick: this.tick, state: this.state, stateTick: this.tick - this.enteredAt, clip: st?.clip ?? null, vars: { ...this.vars } };
    this.tick++;
    return frame;
  }
}

export type MachineInput = { tick: number; event: string };

/** Run a machine for `ticks` ticks with scripted inputs (sorted by tick, stable). */
export function runMachine(spec: MotionSpec, machineName: string | undefined, inputs: MachineInput[], ticks: number): { frames: MachineFrame[]; log: MachineLog[] } {
  const r = new MachineRunner(spec, machineName);
  const byTick = new Map<number, string[]>();
  for (const i of inputs) byTick.set(i.tick, [...(byTick.get(i.tick) ?? []), i.event]);
  const frames: MachineFrame[] = [];
  for (let t = 0; t < ticks; t++) {
    for (const e of byTick.get(t) ?? []) r.send(e);
    frames.push(r.step());
  }
  return { frames, log: r.log };
}

