// Cyrus motion core: the SIMULATION driver the studio preview, the contact-sheet renderer and the tests share. It runs a
// state machine (or one clip) tick by tick with scripted inputs and reports, per tick, the state, the clip and its local
// tick, the cues fired in that tick and (optionally) the pose and live particles. Deterministic: same spec + inputs =
// same frames. A three.js viewport plays the SAME frames: it renders sample() at tick + alpha between steps.
import { runMachine, type MachineInput, type MachineLog } from "./machine";
import { cues as clipCues, particlesAt, sample, type Cue, type LiveParticle, type Pose } from "./sample";
import type { MotionSpec } from "./spec";
import { clipOf } from "./spec";

export type SimFrame = {
  tick: number;
  state: string | null;
  clip: string | null;
  clipTick: number;
  cues: Cue[];
  vars?: Record<string, number>;
  pose?: Pose;
  particles?: LiveParticle[];
};
export type SimOptions = { machine?: string; clip?: string; inputs?: MachineInput[]; ticks: number; withPose?: boolean; withParticles?: boolean };

export function simulate(spec: MotionSpec, o: SimOptions): { frames: SimFrame[]; log: MachineLog[] } {
  const frames: SimFrame[] = [];
  const decorate = (f: SimFrame) => {
    if (o.withPose) f.pose = sample(spec, f.clip, f.clipTick);
    if (o.withParticles && f.clip) f.particles = particlesAt(spec, f.clip, f.clipTick);
    return f;
  };
  if (o.clip || !spec.machines?.length) {
    const name = o.clip ?? spec.clips[0].name;
    const clip = clipOf(spec, name);
    if (!clip) throw new Error(`no clip ${name}`);
    for (let t = 0; t < o.ticks; t++) frames.push(decorate({ tick: t, state: null, clip: name, clipTick: t, cues: clipCues(clip, t - 1, t) }));
    return { frames, log: [] };
  }
  const run = runMachine(spec, o.machine, o.inputs ?? [], o.ticks);
  for (const m of run.frames) {
    const clip = m.clip ? clipOf(spec, m.clip) : undefined;
    frames.push(decorate({ tick: m.tick, state: m.state, clip: m.clip, clipTick: m.stateTick, cues: clip ? clipCues(clip, m.stateTick - 1, m.stateTick) : [], vars: m.vars }));
  }
  return { frames, log: run.log };
}

/** One line per tick with something happening (state changes and cues): the studio's event log and a golden format. */
export function eventLog(frames: SimFrame[]): string[] {
  const out: string[] = [];
  let prev: string | null | undefined;
  for (const f of frames) {
    if (f.state !== null && f.state !== prev) out.push(`t${f.tick} state ${f.state}${f.clip ? ` clip ${f.clip}` : ""}${f.vars && Object.keys(f.vars).length ? ` ${Object.entries(f.vars).map(([k, v]) => `${k}=${v}`).join(" ")}` : ""}`);
    prev = f.state;
    for (const c of f.cues) out.push(`t${f.tick} ${c.kind} ${c.kind === "sound" ? c.sound : c.kind === "particle" ? `${c.effect ?? "emitter"}@${c.node}` : c.name}`);
  }
  return out;
}

