// Cyrus motion core: VALIDATION. validateMotion(input, capability?) never throws; it returns structured issues
// { path, code, severity, message } (schema, references, rig, timing, machine logic) plus the per-game cap checks of the
// capability's caps and track-kind support, and the measured stats a studio budget panel shows.
import type { MotionCapability, MotionCaps } from "./caps";
import { NEUTRAL_CAPABILITY } from "./caps";
import { particleBudget } from "./sample";
import { ACTOR, CHANNELS, MOTION_LIMITS, MotionSpecSchema, type Clip, type Machine, type MotionSpec, type RigNode } from "./spec";

export type MotionIssue = { path: string; code: string; severity: "error" | "warn"; message: string };
export type MotionStats = { nodes: number; depth: number; clips: number; maxTracks: number; maxKeys: number; keysTotal: number; maxDuration: number; particlesPerTick: number; particlesPerClip: number; maxSounds: number; machines: number; maxStates: number; maxTransitions: number; liveEntities: number };
export type MotionValidation = { ok: boolean; spec: MotionSpec | null; errors: MotionIssue[]; warnings: MotionIssue[]; issues: MotionIssue[]; stats: MotionStats | null; game: string };

const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");

/** Entities one live instance needs: nodes a binding draws (parts / hinges / wheels with a proxy or kind part). */
export function visibleNodes(spec: MotionSpec): RigNode[] {
  return spec.rig.nodes.filter((n) => n.proxy || n.kind === "part" || n.kind === "hinge" || n.kind === "wheel");
}

function depthOf(by: Map<string, RigNode>, name: string): number {
  let d = 0, cur = by.get(name);
  const seen = new Set<string>();
  while (cur && cur.parent) { if (seen.has(cur.name)) return -1; seen.add(cur.name); cur = by.get(cur.parent); if (!cur) return -1; d++; }
  return cur ? d : -1;
}

export function validateMotion(input: unknown, capability: MotionCapability = NEUTRAL_CAPABILITY): MotionValidation {
  const issues: MotionIssue[] = [];
  const err = (path: string, code: string, message: string) => issues.push({ path, code, severity: "error", message });
  const warn = (path: string, code: string, message: string) => issues.push({ path, code, severity: "warn", message });
  const done = (spec: MotionSpec | null, stats: MotionStats | null): MotionValidation => {
    const errors = issues.filter((i) => i.severity === "error"), warnings = issues.filter((i) => i.severity === "warn");
    return { ok: !errors.length && !!spec, spec: errors.length ? null : spec, errors, warnings, issues, stats, game: capability.game };
  };
  let bytes = Infinity;
  try { bytes = new TextEncoder().encode(JSON.stringify(input)).length; } catch { /* not JSON */ }
  if (bytes > MOTION_LIMITS.specBytes) { err("(root)", "spec_size", `the motion spec is ${bytes} bytes; the limit is ${MOTION_LIMITS.specBytes}`); return done(null, null); }
  const p = MotionSpecSchema.safeParse(input);
  if (!p.success) { for (const i of p.error.issues.slice(0, 30)) err(issuePath(i.path) || "(root)", "schema", i.message); return done(null, null); }
  const s = p.data;
  const caps: MotionCaps = capability.caps;

  // ---- rig
  const by = new Map<string, RigNode>();
  s.rig.nodes.forEach((n, i) => { if (by.has(n.name)) err(`rig.nodes[${i}].name`, "duplicate_node", `node ${n.name} is defined twice`); by.set(n.name, n); });
  const roots = s.rig.nodes.filter((n) => n.parent === null);
  if (roots.length !== 1) err("rig.nodes", "root_count", `the rig needs exactly one root node (parent null); it has ${roots.length}`);
  let depth = 0;
  s.rig.nodes.forEach((n, i) => {
    const at = `rig.nodes[${i}]`;
    if (n.parent && !by.has(n.parent)) err(`${at}.parent`, "unresolved_ref", `parent ${n.parent} does not exist`);
    const d = depthOf(by, n.name);
    if (d < 0 && n.parent && by.has(n.parent)) err(`${at}.parent`, "cycle", `node ${n.name} is inside a parent cycle`);
    depth = Math.max(depth, d);
    if (n.kind === "hinge" && !n.hinge) err(`${at}.hinge`, "hinge_missing", "a hinge node needs hinge {axis, min, max}");
    if (n.hinge && n.kind !== "hinge") err(`${at}.hinge`, "hinge_kind", "hinge settings need kind hinge");
    if (n.hinge && n.hinge.min > n.hinge.max) err(`${at}.hinge`, "hinge_limits", "hinge min must be <= max");
    if (n.kind === "wheel" && !n.wheel) err(`${at}.wheel`, "wheel_missing", "a wheel node needs wheel {axle, radius}");
    if (n.wheel && n.kind !== "wheel") err(`${at}.wheel`, "wheel_kind", "wheel settings need kind wheel");
    if (n.seat && n.kind !== "seat") err(`${at}.seat`, "seat_kind", "seat settings need kind seat");
    if (!capability.nodeKinds.includes(n.kind)) warn(`${at}.kind`, "node_kind_unsupported", `${capability.game} has no ${n.kind} nodes; it is lowered as a plain part or left out`);
  });
  if (s.rig.nodes.length > caps.nodes) err("rig.nodes", "cap_nodes", `${s.rig.nodes.length} nodes; the ${capability.game} limit is ${caps.nodes}`);
  if (depth > caps.depth) err("rig.nodes", "cap_depth", `the rig is nested ${depth} deep; the ${capability.game} limit is ${caps.depth}`);
  const live = visibleNodes(s).length + (capability.game === "minecraft" ? 1 : 0);
  if (live > caps.liveEntities) err("rig.nodes", "cap_entities", `one instance needs ${live} entities; the ${capability.game} limit is ${caps.liveEntities}`);

  // ---- clips
  const clipNames = new Set<string>();
  let keysTotal = 0, maxTracks = 0, maxKeys = 0, maxDuration = 0, ppt = 0, ppc = 0, maxSounds = 0;
  const kindUse = new Set<string>();
  const eventNames = new Set<string>();
  const checkClip = (c: Clip, ci: number) => {
    const at = `clips[${ci}]`;
    if (clipNames.has(c.name)) err(`${at}.name`, "duplicate_clip", `clip ${c.name} is defined twice`);
    clipNames.add(c.name);
    maxTracks = Math.max(maxTracks, c.tracks.length); maxDuration = Math.max(maxDuration, c.length);
    if (c.tracks.length > caps.tracksPerClip) err(`${at}.tracks`, "cap_tracks", `${c.tracks.length} tracks; the ${capability.game} limit is ${caps.tracksPerClip}`);
