        tr.emitters.forEach((e, ei) => {
          if (e.life[0] > e.life[1]) err(`${tp}.emitters[${ei}].life`, "range_order", "life [min, max] with min <= max");
          if (e.speed[0] > e.speed[1]) err(`${tp}.emitters[${ei}].speed`, "range_order", "speed [min, max] with min <= max");
          if (!(e.burst ?? 0) && !(e.rate ?? 0)) err(`${tp}.emitters[${ei}]`, "no_particles", "an emitter needs burst or rate");
          if ((e.rate ?? 0) > 0 && !(tr.duration ?? 0)) warn(`${tp}.duration`, "rate_without_duration", "rate without duration emits for one tick only");
        });
        const b = particleBudget(tr);
        tickParticles.set(tr.at, (tickParticles.get(tr.at) ?? 0) + b.perTick);
        clipParticles += b.total;
      } else if (tr.kind === "sound") {
        sounds++;
        if (tr.at >= c.length) err(`${tp}.at`, "cue_after_end", `at tick ${tr.at}, at or after the clip end (${c.length})`);
        if (tr.node && !by.has(tr.node)) err(`${tp}.node`, "unresolved_ref", `node ${tr.node} does not exist`);
      } else if (tr.kind === "material") {
        const ks = tr.keys;
        keysTotal += ks.length; maxKeys = Math.max(maxKeys, ks.length);
        ks.forEach((k, ki) => {
          if (ki && k.t <= ks[ki - 1].t) err(`${tp}.keys[${ki}].t`, "key_order", "key times must strictly increase");
          if (k.t > c.length) err(`${tp}.keys[${ki}].t`, "key_after_end", `key at tick ${k.t} is after the clip end`);
          if ((tr.channel === "tint") !== (typeof k.v === "string")) err(`${tp}.keys[${ki}].v`, "material_value", tr.channel === "tint" ? "tint keys are colours like #ff8800" : `${tr.channel} keys are numbers`);
          if (typeof k.v === "number" && (tr.channel === "opacity" || tr.channel === "emissive") && k.v > 1) err(`${tp}.keys[${ki}].v`, "material_range", `${tr.channel} is 0..1`);
          if (typeof k.v === "number" && tr.channel === "brightness" && k.v > 15) err(`${tp}.keys[${ki}].v`, "material_range", "brightness is a light level 0..15");
          if (typeof k.v === "number" && tr.channel === "frame" && !Number.isInteger(k.v)) err(`${tp}.keys[${ki}].v`, "material_range", "frame is a whole texture frame index");
        });
        if (!capability.materialChannels.includes(tr.channel)) warn(tp, "material_unsupported", `${capability.game} cannot animate ${tr.channel}; this track is left out there`);
      } else if (tr.kind === "event") {
        eventNames.add(tr.name);
        if (tr.at >= c.length) err(`${tp}.at`, "cue_after_end", `at tick ${tr.at}, at or after the clip end (${c.length})`);
        const ref = tr.attach ?? tr.detach;
        if (tr.attach && tr.detach) err(tp, "attach_detach", "one event either attaches or detaches");
        if (ref && ref.child !== ACTOR && !by.has(ref.child)) err(`${tp}`, "unresolved_ref", `child ${ref.child} is neither a node nor ${ACTOR}`);
        if (tr.attach) { const so = by.get(tr.attach.socket); if (!so) err(`${tp}.attach.socket`, "unresolved_ref", `socket ${tr.attach.socket} does not exist`); else if (so.kind !== "socket" && so.kind !== "seat") err(`${tp}.attach.socket`, "not_socket", `${tr.attach.socket} is a ${so.kind}, not a socket or seat`); }
        if (ref && !capability.attach) warn(tp, "attach_unsupported", `${capability.game} cannot attach actors; this event still fires but nothing is reparented`);
      }
    });
    const peak = Math.max(0, ...tickParticles.values());
    ppt = Math.max(ppt, peak); ppc = Math.max(ppc, clipParticles); maxSounds = Math.max(maxSounds, sounds);
    if (peak > caps.particlesPerTick) err(`${at}.tracks`, "cap_particles_tick", `${peak} particles in one tick; the ${capability.game} limit is ${caps.particlesPerTick}`);
    if (clipParticles > caps.particlesPerClip) err(`${at}.tracks`, "cap_particles_clip", `${clipParticles} particles per play; the ${capability.game} limit is ${caps.particlesPerClip}`);
    if (sounds > caps.soundsPerClip) err(`${at}.tracks`, "cap_sounds", `${sounds} sound cues; the ${capability.game} limit is ${caps.soundsPerClip}`);
    tickParticles = new Map();
  };
  s.clips.forEach(checkClip);
  if (s.clips.length > caps.clips) err("clips", "cap_clips", `${s.clips.length} clips; the ${capability.game} limit is ${caps.clips}`);
  if (keysTotal > caps.keysTotal) err("clips", "cap_keys_total", `${keysTotal} keys in all; the ${capability.game} limit is ${caps.keysTotal}`);
  for (const k of kindUse) if (capability.trackKinds[k as keyof typeof capability.trackKinds] === "none") warn("clips", "track_kind_unsupported", `${capability.game} cannot play ${k} tracks; they are left out there`);

  // ---- machines
  const machines = s.machines ?? [];
  if (machines.length > caps.machines) err("machines", "cap_machines", `${machines.length} machines; the ${capability.game} limit is ${caps.machines}`);
  const mNames = new Set<string>();
  let maxStates = 0, maxTransitions = 0;
  machines.forEach((m: Machine, mi) => {
    const at = `machines[${mi}]`;
    if (mNames.has(m.name)) err(`${at}.name`, "duplicate_machine", `machine ${m.name} is defined twice`);
    mNames.add(m.name);
    maxStates = Math.max(maxStates, m.states.length); maxTransitions = Math.max(maxTransitions, m.transitions.length);
    if (m.states.length > caps.states) err(`${at}.states`, "cap_states", `${m.states.length} states; the ${capability.game} limit is ${caps.states}`);
    if (m.transitions.length > caps.transitions) err(`${at}.transitions`, "cap_transitions", `${m.transitions.length} transitions; the ${capability.game} limit is ${caps.transitions}`);
    const states = new Map(m.states.map((x) => [x.name, x]));
    if (states.size !== m.states.length) err(`${at}.states`, "duplicate_state", "state names must be unique");
    const vars = new Map((m.vars ?? []).map((v) => [v.name, v]));
    (m.vars ?? []).forEach((v, vi) => { if (v.min > v.max || v.init < v.min || v.init > v.max) err(`${at}.vars[${vi}]`, "var_range", `var ${v.name}: min <= init <= max`); });
    if (!states.has(m.initial)) err(`${at}.initial`, "unresolved_ref", `initial state ${m.initial} does not exist`);
    const varRef = (p: string, name: string) => { if (!vars.has(name)) err(p, "unresolved_ref", `var ${name} is not declared in vars`); };
    const handled = new Set(m.transitions.map((t) => t.on));
    m.states.forEach((st, si) => {
      const sp = `${at}.states[${si}]`;
      if (st.clip && !clipNames.has(st.clip)) err(`${sp}.clip`, "unresolved_ref", `clip ${st.clip} does not exist`);
      if (st.after && !states.has(st.after.to)) err(`${sp}.after.to`, "unresolved_ref", `state ${st.after.to} does not exist`);
      if (st.after && st.after.ticks === undefined) {
        const c = st.clip ? s.clips.find((x) => x.name === st.clip) : undefined;
        if (!c) err(`${sp}.after`, "after_needs_ticks", "after without ticks needs a clip (it leaves at the clip end)");
        else if (c.loop !== "once") err(`${sp}.after`, "after_never", `clip ${c.name} is ${c.loop}, it never ends: give after.ticks`);
      }
      (st.onEnter ?? []).forEach((a, ai) => {
        if (a.do === "emit") { if (!handled.has(a.event)) warn(`${sp}.onEnter[${ai}]`, "emit_unhandled", `no transition listens to ${a.event}`); }
        else varRef(`${sp}.onEnter[${ai}].var`, a.var);
      });
    });
    m.transitions.forEach((t, ti) => {
      const tp = `${at}.transitions[${ti}]`;
      if (t.from !== "*" && !states.has(t.from)) err(`${tp}.from`, "unresolved_ref", `state ${t.from} does not exist`);
      if (!states.has(t.to)) err(`${tp}.to`, "unresolved_ref", `state ${t.to} does not exist`);
      (t.guard ?? []).forEach((g, gi) => varRef(`${tp}.guard[${gi}].var`, g.var));
    });
    // zero-tick after cycle (an instant loop)
    for (const st of m.states) {
      let cur: string | undefined = st.name; const seen = new Set<string>();
      while (cur) {
        const x = states.get(cur);
        if (!x?.after || x.after.ticks !== 0) break;
        if (seen.has(cur)) { err(`${at}.states`, "instant_cycle", `states ${[...seen].join(" -> ")} leave each other in zero ticks forever`); break; }
        seen.add(cur); cur = x.after.to;
      }
    }
    // reachability from the initial state
    const reach = new Set<string>([m.initial]);
    for (let changed = true; changed;) {
      changed = false;
      for (const t of m.transitions) if ((t.from === "*" || reach.has(t.from)) && !reach.has(t.to)) { reach.add(t.to); changed = true; }
      for (const st of m.states) if (reach.has(st.name) && st.after && !reach.has(st.after.to)) { reach.add(st.after.to); changed = true; }
    }
    m.states.forEach((st, si) => { if (!reach.has(st.name)) warn(`${at}.states[${si}]`, "unreachable_state", `state ${st.name} can never be entered`); });
  });

  // channel sanity: every transform channel known (schema guarantees), stats
  void CHANNELS;
  const stats: MotionStats = { nodes: s.rig.nodes.length, depth, clips: s.clips.length, maxTracks, maxKeys, keysTotal, maxDuration, particlesPerTick: ppt, particlesPerClip: ppc, maxSounds, machines: machines.length, maxStates, maxTransitions, liveEntities: live };
  return done(s, stats);
}

