// Cyrus motion core: the PLAYBACK CLOCK contract the Model Studio viewport (layer 1) drives and the timeline (layer 2)
// scrubs. No timers inside: the host calls advance(ms) from its own requestAnimationFrame (or a test calls it with fixed
// steps), the simulation steps at WHOLE ticks, and the renderer draws sample() at tick + alpha for smooth frames. Pure.
export type ClockState = { tick: number; alpha: number; playing: boolean; speed: number; range: [number, number] | null; tickRate: number };
export type MotionClock = {
  play(): void;
  pause(): void;
  /** jump to a tick (fractional allowed: the alpha part); clamps into the range when one is set */
  seek(tick: number): void;
  /** advance n whole ticks while paused (frame step); returns the ticks crossed */
  step(n?: number): number[];
  setSpeed(x: number): void;
  /** loop playback between a and b (ticks), or null for unbounded */
  setRange(r: [number, number] | null): void;
  /** feed wall time; returns every whole tick crossed (in order) so the caller steps the simulation for each */
  advance(ms: number): number[];
  now(): ClockState;
  subscribe(fn: (s: ClockState) => void): () => void;
};

export function createClock(o: { tickRate?: number; start?: number } = {}): MotionClock {
  const tickRate = o.tickRate ?? 20;
  let pos = o.start ?? 0; // fractional ticks
  let playing = false, speed = 1;
  let range: [number, number] | null = null;
  const subs = new Set<(s: ClockState) => void>();
  const state = (): ClockState => ({ tick: Math.floor(pos), alpha: pos - Math.floor(pos), playing, speed, range, tickRate });
  const emit = () => { const s = state(); for (const f of subs) f(s); };
  const wrap = (p: number) => {
    if (!range) return Math.max(0, p);
    const [a, b] = range, len = Math.max(1, b - a);
    return p < a ? a : p >= b ? a + ((p - a) % len) : p;
  };
  const move = (delta: number): number[] => {
    const crossed: number[] = [];
    let p = pos;
    const target = pos + delta;
    // whole ticks in (pos, target]
    for (let t = Math.floor(p) + 1; t <= Math.floor(target) && crossed.length < 10000; t++) crossed.push(range ? wrap(t) : t);
    pos = wrap(target);
    return crossed;
  };
  return {
    play() { playing = true; emit(); },
    pause() { playing = false; emit(); },
    seek(t) { pos = wrap(Math.max(0, t)); emit(); },
    step(n = 1) { const c = move(Math.max(0, Math.floor(n))); pos = Math.floor(pos); emit(); return c; },
    setSpeed(x) { speed = Math.max(0.05, Math.min(8, x)); emit(); },
    setRange(r) { range = r && r[1] > r[0] ? [Math.max(0, r[0]), r[1]] : null; pos = wrap(pos); emit(); },
    advance(ms) { if (!playing || ms <= 0) return []; const c = move((ms / 1000) * tickRate * speed); emit(); return c; },
    now: state,
    subscribe(fn) { subs.add(fn); return () => subs.delete(fn); },
  };
}
EOF
cat > /tank/dev-worktrees/cyrus-r21/lib/cyrus/motion/adapter.ts <<'EOF'
// Cyrus motion core: the per-game EXPORTER / ADAPTER contract. A game's adapter declares a MotionCapability (in its
// asset profile, lib/cyrus/adapters/asset-profile.ts `motion`) and implements lower(): MotionSpec -> that game's motion
// program. Whatever the game cannot express is reported in `dropped` with a reason, never silently lost; `warnings` are
// approximations (e.g. an ease split into linear segments). Pure.
import type { MotionCapability } from "./caps";
import type { MotionSpec } from "./spec";
import type { MotionIssue } from "./validate";

export type Dropped = { path: string; reason: string };
export type LowerResult<P> = { ok: true; program: P; warnings: MotionIssue[]; dropped: Dropped[] } | { ok: false; errors: MotionIssue[]; warnings: MotionIssue[]; dropped: Dropped[] };

export type MotionAdapter<P, Ctx = unknown> = {
  game: string;
  capability: MotionCapability;
  lower(spec: MotionSpec, ctx: Ctx): LowerResult<P>;
};

/** A support summary for the catalog: which games can play a spec, and what each would drop. */
export function supportRow<P, C>(spec: MotionSpec, adapters: { a: MotionAdapter<P, C>; ctx: C }[]): { game: string; ok: boolean; dropped: number; warnings: number; reasons: string[] }[] {
  return adapters.map(({ a, ctx }) => {
    const r = a.lower(spec, ctx);
    return { game: a.game, ok: r.ok, dropped: r.dropped.length, warnings: r.warnings.length, reasons: [...(r.ok ? [] : r.errors.map((e) => e.message)), ...r.dropped.map((d) => d.reason)].slice(0, 6) };
  });
}
EOF

