// Cyrus motion core: the BRIDGE to the clip formats that existed before it, so there is ONE timeline model.
//   - RigSpec v1 clips (lib/cyrus/creature/spec.ts: seconds, key time 0..1, Blockbench units 16 = 1 block)
//   - Model Studio L2 editor clips (lib/cyrus/modelstudio/editor/doc.ts EClip, feature/cyrus-r17-editor: the same shape
//     with bone ids and key ids)
// Both convert to MotionSpec clips (ticks, blocks) and back without loss for transform tracks; a MotionSpec clip's
// particle / sound / material / event tracks have no RigSpec form and are reported in `dropped` on the way back.
// Structural types only (no import of the editor module), so this compiles with or without the r17 branch.
import { r4 } from "./math";
import type { Clip, Ease, RigNode } from "./types-bridge";
import { TICK_RATE } from "./spec";

export const UNITS_PER_BLOCK = 16;

export type LegacyKey = { t: number; v: [number, number, number]; ease?: "linear" | "smooth"; id?: string };
export type LegacyTrack = { bone: string; channel: "rotation" | "position" | "scale"; wave?: { amp: [number, number, number]; offset?: [number, number, number]; cycles: number; phase: number }; keys?: LegacyKey[] };
export type LegacyClip = { name?: string; length: number; loop: boolean; tracks: LegacyTrack[] };
export type LegacyBone = { name: string; parent: string | null; pivot: [number, number, number]; rotation?: [number, number, number] };

const CH = { rotation: "rot", position: "pos", scale: "scale" } as const;
const CH_BACK = { rot: "rotation", pos: "position", scale: "scale" } as const;
const u = (v: number, ch: string) => (ch === "position" || ch === "pos" ? r4(v / UNITS_PER_BLOCK) : v);
const ub = (v: number, ch: string) => (ch === "pos" ? r4(v * UNITS_PER_BLOCK) : v);

/** RigSpec / editor bones -> rig nodes (Blockbench units -> blocks). */
export function nodesFromBones(bones: LegacyBone[], nameOf: (id: string) => string = (x) => x): RigNode[] {
  return bones.map((b) => ({
    name: nameOf(b.name), parent: b.parent === null ? null : nameOf(b.parent), kind: "bone" as const,
    pivot: [r4(b.pivot[0] / UNITS_PER_BLOCK), r4(b.pivot[1] / UNITS_PER_BLOCK), r4(b.pivot[2] / UNITS_PER_BLOCK)] as [number, number, number],
    ...(b.rotation && b.rotation.some((x) => x !== 0) ? { rest: { rot: [...b.rotation] as [number, number, number] } } : {}),
  }));
}

/** A RigSpec / editor clip -> a MotionSpec clip. `nameOf` maps editor bone ids to names (RigSpec: identity). */
export function fromLegacyClip(name: string, c: LegacyClip, nameOf: (id: string) => string = (x) => x): Clip {
  const length = Math.max(1, Math.round(c.length * TICK_RATE));
  return {
    name, length, loop: c.loop ? "loop" : "once",
    tracks: c.tracks.map((t) => ({
      kind: "transform" as const, node: nameOf(t.bone), channel: CH[t.channel],
      ...(t.wave ? { wave: { amp: t.wave.amp.map((x) => u(x, t.channel)) as [number, number, number], ...(t.wave.offset ? { offset: t.wave.offset.map((x) => u(x, t.channel)) as [number, number, number] } : {}), cycles: t.wave.cycles, phase: t.wave.phase } } : {}),
      ...(t.keys ? { keys: t.keys.map((k) => ({ t: r4(k.t * length), v: k.v.map((x) => u(x, t.channel)) as [number, number, number], ease: (k.ease ?? "smooth") as Ease })) } : {}),
    })),
  };
}

/**
 * A MotionSpec clip -> a RigSpec / editor clip (seconds, key time 0..1, units). Only transform tracks fit; eases other
 * than linear/smooth become smooth (reported), other track kinds are dropped (reported).
 */
export function toLegacyClip(c: Clip, idOf: (name: string) => string = (x) => x): { clip: LegacyClip; dropped: { path: string; reason: string }[] } {
  const dropped: { path: string; reason: string }[] = [];
  const tracks: LegacyTrack[] = [];
  c.tracks.forEach((t, i) => {
    if (t.kind !== "transform") { dropped.push({ path: `tracks[${i}]`, reason: `${t.kind} tracks have no RigSpec form (they stay in the MotionSpec)` }); return; }
    const ch = CH_BACK[t.channel];
    tracks.push({
      bone: idOf(t.node), channel: ch,
      ...(t.wave ? { wave: { amp: t.wave.amp.map((x) => ub(x, t.channel)) as [number, number, number], ...(t.wave.offset ? { offset: t.wave.offset.map((x) => ub(x, t.channel)) as [number, number, number] } : {}), cycles: t.wave.cycles, phase: t.wave.phase } } : {}),
      ...(t.keys ? { keys: t.keys.map((k, ki) => {
        const e = k.ease ?? "linear";
        if (e !== "linear" && e !== "smooth") dropped.push({ path: `tracks[${i}].keys[${ki}].ease`, reason: `ease ${e} becomes smooth in RigSpec` });
        return { t: r4(k.t / c.length), v: k.v.map((x) => ub(x, t.channel)) as [number, number, number], ease: e === "linear" ? "linear" as const : "smooth" as const };
      }) } : {}),
    });
  });
  return { clip: { name: c.name, length: r4(c.length / TICK_RATE), loop: c.loop === "loop" || c.loop === "pingpong", tracks }, dropped };
}

