// Cyrus MOTION CORE (lib/cyrus/motion): schema, deterministic sampler (goldens), cues, analytic particles, state-machine
// runner, structured validation against caps, clock, the RigSpec / editor bridge, and the generated JSON Schema.
// Goldens: test/fixtures/cyrus-motion/golden.json (regenerate deliberately: UPDATE_CYRUS_MOTION_GOLDEN=1).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import path from "node:path";
import {
  MotionSpecSchema, canonicalMotion, clipTime, createClock, cues, eventLog, fromLegacyClip, nodePositions, particlesAt, runMachine, sample,
  simulate, toLegacyClip, validateMotion, NEUTRAL_CAPABILITY, MAX_TRANSITIONS_PER_TICK, motionJsonSchema, type MotionCapability, type MotionSpec,
} from "../lib/cyrus/motion";
import { ease, quatFromEuler, decompose, compose, mulberry32 } from "../lib/cyrus/motion/math";
import { motionArtifacts } from "../scripts/cyrus/build-motion-artifacts";

const FX = path.join(__dirname, "fixtures/cyrus-motion");
const load = (n: string): MotionSpec => MotionSpecSchema.parse(JSON.parse(readFileSync(path.join(FX, n), "utf8")));
const door = load("door.json");
const gun = load("gun.json");
const sha = (s: string) => createHash("sha256").update(s).digest("hex");
const GOLDEN = path.join(FX, "golden.json");
const golden: Record<string, string> = existsSync(GOLDEN) ? JSON.parse(readFileSync(GOLDEN, "utf8")) : {};
const fresh: Record<string, string> = {};
function gold(key: string, value: unknown) {
  const h = sha(canonicalMotion(value));
  fresh[key] = h;
  if (process.env.UPDATE_CYRUS_MOTION_GOLDEN === "1") { writeFileSync(GOLDEN, JSON.stringify({ ...golden, ...fresh }, null, 1) + "\n"); return; }
  assert.equal(h, golden[key], `golden ${key} changed (UPDATE_CYRUS_MOTION_GOLDEN=1 to accept)`);
}

describe("motion core: schema + JSON Schema", () => {
  it("fixtures parse and validate clean on the neutral capability", () => {
    for (const s of [door, gun]) { const v = validateMotion(s); assert.equal(v.ok, true, JSON.stringify(v.errors)); assert.deepEqual(v.warnings, []); }
  });
  it("the committed JSON Schema is current", async () => {
    const files = await motionArtifacts();
