    const log = eventLog(sim.frames);
    assert.deepEqual(log.slice(0, 9), [
      "t0 state idle clip idle ammo=2", "t2 state fire clip fire ammo=1", "t2 particle effect:muzzle_flash@muzzle", "t2 sound sound:gun_pistol_shot",
      "t6 state idle clip idle ammo=1", "t8 state fire clip fire ammo=0", "t8 particle effect:muzzle_flash@muzzle", "t8 sound sound:gun_pistol_shot", "t12 state idle clip idle ammo=0",
    ]);
    assert.ok(log.includes("t14 state dry clip dry ammo=0"));
    assert.ok(log.includes("t20 state reload clip reload ammo=6"));
    assert.ok(log.includes("t46 sound sound:gun_slide_rack") && log.includes("t47 event chambered"));
    assert.ok(log.includes("t50 state idle clip idle ammo=6") && log.includes("t55 state fire clip fire ammo=5"));
    gold("gun.eventlog", log);
  });
  it("inputs while busy are ignored with a reason; reload at full ammo is blocked by its guard", () => {
    const r = runMachine(gun, "gun", [{ tick: 1, event: "fire" }, { tick: 2, event: "fire" }], 10);
    assert.deepEqual(r.log.filter((l) => l.kind === "ignored").map((l) => l.kind === "ignored" && `${l.tick}:${l.event}:${l.reason}`), ["2:fire:no transition for this event here"]);
    const full = runMachine(gun, "gun", [{ tick: 1, event: "reload" }, { tick: 3, event: "reload" }], 60);
    assert.ok(full.log.some((l) => l.kind === "ignored" && l.event === "reload" && l.tick === 3));
  });
  it("door: minTicks blocks a too-early toggle; after leaves at the clip end", () => {
    const r = runMachine(door, "door", [{ tick: 1, event: "toggle" }, { tick: 13, event: "toggle" }, { tick: 20, event: "toggle" }], 40);
    const enters = r.log.filter((l) => l.kind === "enter").map((l) => l.kind === "enter" && `${l.tick}:${l.state}`);
    assert.deepEqual(enters, ["0:closed", "1:opening", "13:open", "20:closing", "30:closed"]);
  });
