    const loopy: MotionSpec = { ...door, machines: [{ name: "m", initial: "a", states: [{ name: "a", after: { to: "b", ticks: 0 } }, { name: "b", after: { to: "a", ticks: 0 } }], transitions: [] }] };
    const r = runMachine(loopy, "m", [], 2);
    assert.ok(r.log.some((l) => l.kind === "cut"));
    assert.ok(r.log.filter((l) => l.kind === "enter" && l.tick === 0).length <= MAX_TRANSITIONS_PER_TICK + 1);
    assert.ok(validateMotion(loopy).errors.some((e) => e.code === "instant_cycle"));
  });
