        { name: "wheel_fl", parent: "chassis", kind: "wheel", pivot: [-0.8, 0.35, -1.2], wheel: { axle: "x", radius: 0.35, steer: { max: 30 } } },
        { name: "door_l", parent: "chassis", kind: "hinge", pivot: [-0.9, 0.6, -0.4], hinge: { axis: "y", min: -70, max: 0 } },
        { name: "seat_driver", parent: "chassis", kind: "seat", pivot: [-0.4, 0.6, 0], seat: { facing: 0 } },
      ] },
      clips: [{ name: "enter", length: 40, loop: "once", tracks: [
        { kind: "transform", node: "door_l", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 10, v: [0, -65, 0], ease: "out" }, { t: 34, v: [0, -65, 0] }, { t: 40, v: [0, 0, 0], ease: "in" }] },
        { kind: "transform", node: "wheel_fl", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 40, v: [720, 20, 0] }] },
        { kind: "event", at: 24, name: "seated", attach: { child: "$actor", socket: "seat_driver" } },
