describe("motion core: clock", () => {
  it("advance crosses whole ticks only while playing; speed and range loop", () => {
    const c = createClock();
    assert.deepEqual(c.advance(100), []);
    c.play();
    assert.deepEqual(c.advance(120), [1, 2]); // 2.4 ticks
    assert.ok(Math.abs(c.now().alpha - 0.4) < 1e-9);
    c.setSpeed(2);
    assert.deepEqual(c.advance(50), [3, 4]); // +2 ticks
    c.setRange([0, 5]); c.seek(4.5);
    assert.deepEqual(c.advance(50), [0, 1]);
    c.pause(); assert.deepEqual(c.advance(1000), []);
    assert.deepEqual(c.step(2), [2, 3]);
  });
});

describe("motion core: bridge to RigSpec / editor clips (one timeline model)", () => {
  it("RigSpec clip -> MotionSpec clip -> RigSpec clip is lossless for transform tracks", () => {
    const rig = { length: 1.2, loop: true, tracks: [
      { bone: "leg_l", channel: "rotation" as const, wave: { amp: [30, 0, 0] as [number, number, number], cycles: 1, phase: 0 } },
      { bone: "body", channel: "position" as const, keys: [{ t: 0, v: [0, 0, 0] as [number, number, number], ease: "smooth" as const }, { t: 0.5, v: [0, 1.6, 0] as [number, number, number], ease: "linear" as const }, { t: 1, v: [0, 0, 0] as [number, number, number], ease: "smooth" as const }] },
    ] };
    const m = fromLegacyClip("walk", rig);
    assert.equal(m.length, 24);
    assert.deepEqual((m.tracks[1] as { keys: { v: number[] }[] }).keys[1].v, [0, 0.1, 0]); // 1.6 units = 0.1 block
    const back = toLegacyClip(m);
    assert.deepEqual(back.dropped, []);
    assert.deepEqual(back.clip, { name: "walk", ...rig });
  });
  it("non-transform tracks are reported as dropped on the way back", () => {
    assert.equal(toLegacyClip(gun.clips[1]).dropped.length, 3);
  });
});

