      "t0 state idle clip idle ammo=2", "t2 state fire clip fire ammo=1", "t2 particle effect:muzzle_flash@muzzle", "t2 sound sound:gun_pistol_shot",
      "t6 state idle clip idle ammo=1", "t8 state fire clip fire ammo=0", "t8 particle effect:muzzle_flash@muzzle", "t8 sound sound:gun_pistol_shot", "t12 state idle clip idle ammo=0",
    ]);
    assert.ok(log.includes("t14 state dry clip dry ammo=0"));
    assert.ok(log.includes("t20 state reload clip reload ammo=6"));
    assert.ok(log.includes("t46 sound sound:gun_slide_rack") && log.includes("t47 event chambered"));
    assert.ok(log.includes("t50 state idle clip idle ammo=6") && log.includes("t55 state fire clip fire ammo=5"));
    gold("gun.eventlog", log);
  });
  it("inputs while busy are ignored with a reason; reload at full ammo is blocked by its guard", () => {
    const r = runMachine(gun, "gun", [{ tick: 1, event: "fire" }, { tick: 2, event: "fire" }], 10);
    assert.deepEqual(r.log.filter((l) => l.kind === "ignored").map((l) => l.kind === "ignored" && `${l.tick}:${l.event}:${l.reason}`), ["2:fire:no transition for this event here"]);
    const full = runMachine(gun, "gun", [{ tick: 1, event: "reload" }, { tick: 3, event: "reload" }], 60);
    assert.ok(full.log.some((l) => l.kind === "ignored" && l.event === "reload" && l.tick === 3));
  });
  it("door: minTicks blocks a too-early toggle; after leaves at the clip end", () => {
    const r = runMachine(door, "door", [{ tick: 1, event: "toggle" }, { tick: 13, event: "toggle" }, { tick: 20, event: "toggle" }], 40);
    const enters = r.log.filter((l) => l.kind === "enter").map((l) => l.kind === "enter" && `${l.tick}:${l.state}`);
    assert.deepEqual(enters, ["0:closed", "1:opening", "13:open", "20:closing", "30:closed"]);
  });
  it("a zero-tick after loop is cut at the per-tick limit (and the validator rejects it)", () => {
    const loopy: MotionSpec = { ...door, machines: [{ name: "m", initial: "a", states: [{ name: "a", after: { to: "b", ticks: 0 } }, { name: "b", after: { to: "a", ticks: 0 } }], transitions: [] }] };
    const r = runMachine(loopy, "m", [], 2);
    assert.ok(r.log.some((l) => l.kind === "cut"));
    assert.ok(r.log.filter((l) => l.kind === "enter" && l.tick === 0).length <= MAX_TRANSITIONS_PER_TICK + 1);
    assert.ok(validateMotion(loopy).errors.some((e) => e.code === "instant_cycle"));
  });
  it("simulate is reproducible (frames with poses and particles)", () => {
    const a = simulate(gun, { inputs: [{ tick: 1, event: "fire" }], ticks: 8, withPose: true, withParticles: true });
    const b = simulate(gun, { inputs: [{ tick: 1, event: "fire" }], ticks: 8, withPose: true, withParticles: true });
    assert.equal(canonicalMotion(a), canonicalMotion(b));
    gold("gun.sim8", a.frames);
  });
});

describe("motion core: validation issues + caps", () => {
  const tight: MotionCapability = { ...NEUTRAL_CAPABILITY, game: "tight", materialChannels: ["brightness"], attach: false, trackKinds: { ...NEUTRAL_CAPABILITY.trackKinds, material: "none" },
    caps: { ...NEUTRAL_CAPABILITY.caps, nodes: 3, particlesPerTick: 4, durationTicks: 20, soundsPerClip: 2, liveEntities: 3 } };
  it("caps become errors with the game name; unsupported kinds become warnings", () => {
    const v = validateMotion(gun, tight);
    const codes = v.errors.map((e) => e.code).sort();
    assert.deepEqual([...new Set(codes)], ["cap_duration", "cap_entities", "cap_nodes", "cap_particles_tick", "cap_sounds"].sort());
    assert.ok(v.errors.every((e) => e.message.includes("tight")));
    assert.ok(v.warnings.some((w) => w.code === "track_kind_unsupported"));
    assert.equal(v.stats?.particlesPerTick, 6);
  });
  it("rig and reference errors", () => {
    const bad = JSON.parse(JSON.stringify(door)) as MotionSpec;
    bad.clips[0].tracks[0] = { kind: "transform", node: "door", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 10, v: [10, 120, 0] }] };
    bad.clips[1].tracks.push({ kind: "transform", node: "ghost", channel: "pos", keys: [{ t: 0, v: [0, 0, 0] }] });
    bad.machines![0].states[1].clip = "nope";
    bad.machines![0].transitions.push({ from: "open", on: "slam", to: "gone" });
    const codes = validateMotion(bad).errors.map((e) => e.code);
    for (const c of ["hinge_axis", "hinge_limit", "unresolved_ref"]) assert.ok(codes.includes(c), c);
    assert.ok(validateMotion(bad).errors.filter((e) => e.code === "unresolved_ref").length >= 3);
  });
  it("timing errors: key order, after a looping clip, cue after end", () => {
    const bad = JSON.parse(JSON.stringify(door)) as MotionSpec;
    (bad.clips[0].tracks[0] as { keys: { t: number }[] }).keys[2].t = 10;
    bad.clips[1].tracks.push({ kind: "sound", at: 10, sound: "minecraft:block.wooden_door.close" });
    bad.machines![0].states[2].after = { to: "closed" };
    const codes = validateMotion(bad).errors.map((e) => e.code);
    for (const c of ["key_order", "cue_after_end", "after_never"]) assert.ok(codes.includes(c), c);
  });
  it("vehicles are expressible: wheels, seats and an actor attach validate on the neutral core", () => {
    const car: MotionSpec = {
      schemaVersion: 1, id: "car_core",
      rig: { nodes: [
        { name: "chassis", parent: null, kind: "part", pivot: [0, 0.5, 0] },
        { name: "wheel_fl", parent: "chassis", kind: "wheel", pivot: [-0.8, 0.35, -1.2], wheel: { axle: "x", radius: 0.35, steer: { max: 30 } } },
        { name: "door_l", parent: "chassis", kind: "hinge", pivot: [-0.9, 0.6, -0.4], hinge: { axis: "y", min: -70, max: 0 } },
        { name: "seat_driver", parent: "chassis", kind: "seat", pivot: [-0.4, 0.6, 0], seat: { facing: 0 } },
      ] },
      clips: [{ name: "enter", length: 40, loop: "once", tracks: [
        { kind: "transform", node: "door_l", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 10, v: [0, -65, 0], ease: "out" }, { t: 34, v: [0, -65, 0] }, { t: 40, v: [0, 0, 0], ease: "in" }] },
        { kind: "transform", node: "wheel_fl", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 40, v: [720, 20, 0] }] },
        { kind: "event", at: 24, name: "seated", attach: { child: "$actor", socket: "seat_driver" } },
      ] }],
    };
    const v = validateMotion(car);
    assert.equal(v.ok, true, JSON.stringify(v.errors));
    assert.deepEqual(cues(car.clips[0], -1, 40).map((c) => c.kind === "event" && c.attach), [{ child: "$actor", socket: "seat_driver" }]);
    assert.ok(validateMotion(car, { ...NEUTRAL_CAPABILITY, game: "noattach", attach: false }).warnings.some((w) => w.code === "attach_unsupported"));
  });
});

describe("motion core: clock", () => {
  it("advance crosses whole ticks only while playing; speed and range loop", () => {
    const c = createClock();
    assert.deepEqual(c.advance(100), []);
    c.play();
    assert.deepEqual(c.advance(120), [1, 2]); // 2.4 ticks
    assert.ok(Math.abs(c.now().alpha - 0.4) < 1e-9);
    c.setSpeed(2);
    assert.deepEqual(c.advance(50), [3, 4]); // +2 ticks
    c.setRange([0, 5]); c.seek(4.5);
    assert.deepEqual(c.advance(50), [0, 1]);
    c.pause(); assert.deepEqual(c.advance(1000), []);
    assert.deepEqual(c.step(2), [2, 3]);
  });
});

describe("motion core: bridge to RigSpec / editor clips (one timeline model)", () => {
  it("RigSpec clip -> MotionSpec clip -> RigSpec clip is lossless for transform tracks", () => {
    const rig = { length: 1.2, loop: true, tracks: [
      { bone: "leg_l", channel: "rotation" as const, wave: { amp: [30, 0, 0] as [number, number, number], cycles: 1, phase: 0 } },
      { bone: "body", channel: "position" as const, keys: [{ t: 0, v: [0, 0, 0] as [number, number, number], ease: "smooth" as const }, { t: 0.5, v: [0, 1.6, 0] as [number, number, number], ease: "linear" as const }, { t: 1, v: [0, 0, 0] as [number, number, number], ease: "smooth" as const }] },
    ] };
    const m = fromLegacyClip("walk", rig);
    assert.equal(m.length, 24);
    assert.deepEqual((m.tracks[1] as { keys: { v: number[] }[] }).keys[1].v, [0, 0.1, 0]); // 1.6 units = 0.1 block
    const back = toLegacyClip(m);
    assert.deepEqual(back.dropped, []);
    assert.deepEqual(back.clip, { name: "walk", ...rig });
  });
  it("non-transform tracks are reported as dropped on the way back", () => {
    assert.equal(toLegacyClip(gun.clips[1]).dropped.length, 3);
  });
});

