import { num, q3, resolveParams, str, type ParamDef, type ParamValues } from "./params";

export type EffectBuild = { emitters: Emitter[]; duration: number; length: number; loop: "once" | "loop"; sound?: { sound: string; gain?: number; pitch?: number; at?: number }; light?: { peak: number; fadeTicks: number; flicker?: boolean } };
export type EffectPreset = { id: string; title: string; summary: string; tags: string[]; params: ParamDef[]; build(p: ParamValues): EffectBuild };

const SND = (d: string, label = "Sound"): ParamDef => ({ name: "sound", type: "sound", default: d, label });
