      { name: "tint", type: "enum", options: ["warm", "blue", "green"], default: "warm", label: "Colour" },
    ],
    build: (p) => {
      const s = num(p, "size");
      const hot = str(p, "tint") === "blue" ? ["#e6f4ff", "#5aa8ff"] : str(p, "tint") === "green" ? ["#eaffd8", "#58e05a"] : ["#fff6c8", "#ffb03a"];
      return {
        length: 16, loop: "once", duration: 0,
        emitters: [
          { sprite: "flash", shape: "cone", cone: 15, dir: [0, 0, -1], burst: 4, life: [1, 2], speed: [3 * s, 6 * s].map(q3) as [number, number], size: [q3(0.35 * s), 0.05], colors: hot },
          ...(num(p, "sparks") ? [{ sprite: "spark" as const, shape: "cone" as const, cone: 25, dir: [0, 0, -1] as [number, number, number], burst: r(num(p, "sparks")), life: [2, 4] as [number, number], speed: [6 * s, 12 * s].map(q3) as [number, number], size: [0.06, 0.02] as [number, number], colors: ["#ffe08a", "#ff7a1a"] }] : []),
          { sprite: "smoke", shape: "cone", cone: 35, dir: [0, 0, -1], burst: 3, life: [8, 14], speed: [0.5, 1.2], gravity: -1, size: [q3(0.12 * s), q3(0.35 * s)], colors: ["#9a9a9a", "#5a5a5a"] },
        ],
        light: { peak: 15, fadeTicks: 2 },
      };
    },
  },
  {
    id: "effect:explosion", title: "Explosion", summary: "Flash, fireball, rising smoke and falling debris with a boom.",
    tags: ["explosion", "blast", "bomb", "fire", "smoke"],
    params: [{ name: "power", type: "number", min: 0.5, max: 3, default: 1, step: 0.05, label: "Power" }, SND("minecraft:entity.generic.explode")],
    build: (p) => {
      const k = num(p, "power");
      return {
        length: 60, loop: "once", duration: 0,
        emitters: [
          { sprite: "flash", shape: "point", burst: 1, life: [3, 3], speed: [0, 0], size: [q3(2.5 * k), q3(0.5 * k)], colors: ["#ffffff", "#ffd27a"] },
          { sprite: "flame", shape: "sphere", radius: q3(0.3 * k), burst: r(24 * k), life: [6, 14], speed: [3 * k, 9 * k].map(q3) as [number, number], gravity: -2, size: [q3(0.45 * k), 0.1], colors: ["#fff1a8", "#ff8a1a", "#b8300a"] },
          { sprite: "smoke", shape: "sphere", radius: q3(0.5 * k), burst: r(16 * k), life: [20, 40], speed: [1 * k, 3 * k].map(q3) as [number, number], gravity: -1.5, size: [q3(0.4 * k), q3(1.4 * k)], colors: ["#5c5c5c", "#2e2e2e"] },
          { sprite: "debris", shape: "sphere", burst: r(12 * k), life: [10, 24], speed: [4 * k, 10 * k].map(q3) as [number, number], gravity: 18, size: [0.08, 0.08], colors: ["#3b2f25"] },
        ],
        sound: { sound: str(p, "sound"), gain: q3(Math.min(2, 0.8 + 0.4 * k)) },
        light: { peak: 15, fadeTicks: 6 },
      };
    },
  },
  {
    id: "effect:fire", title: "Fire", summary: "A looping flame with smoke wisps, embers and a flickering light.",
    tags: ["fire", "flame", "campfire", "torch", "burning"],
    params: [{ name: "intensity", type: "number", min: 0.25, max: 3, default: 1, step: 0.05, label: "Intensity" }, { name: "radius", type: "number", min: 0, max: 2, default: 0.3, step: 0.05, label: "Radius", unit: "blocks" }, SND("minecraft:block.fire.ambient")],
    build: (p) => {
      const i = num(p, "intensity"), rad = num(p, "radius");
      return {
        length: 40, loop: "loop", duration: 40,
        emitters: [
          { sprite: "flame", shape: "disc", radius: rad, rate: q3(3 * i), life: [8, 16], speed: [0.6, 1.4], dir: [0, 1, 0], gravity: -1, size: [0.25, 0.05], colors: ["#fff2a0", "#ff8a1a", "#c4300a"] },
          { sprite: "smoke", shape: "disc", radius: q3(rad * 0.6), rate: q3(0.6 * i), life: [24, 40], speed: [0.4, 0.9], gravity: -0.8, size: [0.2, 0.7], colors: ["#7a7a7a", "#3c3c3c"] },
          { sprite: "spark", shape: "disc", radius: rad, rate: q3(0.3 * i), life: [10, 20], speed: [1, 2.5], gravity: -0.5, size: [0.05, 0.02], colors: ["#ffd36a", "#ff6a10"] },
        ],
        sound: { sound: str(p, "sound"), gain: 0.6 },
        light: { peak: 13, fadeTicks: 0, flicker: true },
      };
    },
  },
  {
    id: "effect:smoke", title: "Smoke", summary: "A looping column of soft grey smoke.",
    tags: ["smoke", "chimney", "steam", "fog"],
    params: [{ name: "density", type: "number", min: 0.25, max: 4, default: 1, step: 0.05, label: "Density" }, { name: "rise", type: "number", min: 0.2, max: 3, default: 1, step: 0.05, label: "Rise speed" }],
    build: (p) => {
      const d = num(p, "density"), up = num(p, "rise");
      return {
        length: 40, loop: "loop", duration: 40,
        emitters: [{ sprite: "smoke", shape: "sphere", radius: 0.2, rate: q3(1.5 * d), life: [30, 60], speed: [0.2 * up, 0.6 * up].map(q3) as [number, number], dir: [0, 1, 0], gravity: q3(-0.8 * up), size: [0.3, 1.2], colors: ["#bdbdbd", "#6e6e6e", "#3a3a3a"] }],
      };
    },
  },
  {
    id: "effect:water_splash", title: "Water splash", summary: "Droplets thrown up and falling back, a foam ring and bubbles.",
    tags: ["water", "splash", "liquid", "fountain"],
    params: [{ name: "size", type: "number", min: 0.5, max: 2, default: 1, step: 0.05, label: "Size" }, SND("minecraft:entity.generic.splash")],
    build: (p) => {
      const s = num(p, "size");
      return {
        length: 30, loop: "once", duration: 0,
        emitters: [
          { sprite: "droplet", shape: "cone", cone: 35, dir: [0, 1, 0], burst: r(30 * s), life: [10, 20], speed: [3 * s, 6 * s].map(q3) as [number, number], gravity: 20, size: [0.08, 0.06], colors: ["#cfe9ff", "#5aa0e6"] },
          { sprite: "droplet", shape: "disc", radius: q3(0.2 * s), burst: r(16 * s), life: [6, 10], speed: [1.5 * s, 2.5 * s].map(q3) as [number, number], gravity: 10, size: [0.1, 0.04], colors: ["#ffffff", "#a8d4ff"] },
          { sprite: "bubble", shape: "disc", radius: q3(0.4 * s), burst: 8, life: [8, 16], speed: [0.3, 0.8], gravity: -2, size: [0.06, 0.03], colors: ["#e8f6ff"] },
        ],
        sound: { sound: str(p, "sound"), gain: 1 },
      };
    },
  },
];

export const effectById = (id: string) => EFFECTS.find((e) => e.id === id);

/**
 * The tracks one effect adds to a clip at `node` from tick `at`: one particle track (+ a sound cue, + a brightness
 * flash on `lightNode` when given). Seeds come from the effect id + `seed` so two placements differ but stay stable.
 */
export function effectTracks(id: string, o: { node: string; at: number; params?: Record<string, unknown>; seed?: number; lightNode?: string; withSound?: boolean; duration?: number }): { tracks: Track[]; issues: { param: string; message: string }[] } {
  const e = effectById(id);
  if (!e) throw new Error(`unknown effect ${id}`);
  const { values, issues } = resolveParams(e.params, o.params);
  const b = e.build(values);
  const pt: ParticleTrack = { kind: "particle", node: o.node, at: o.at, effect: e.id as ParticleTrack["effect"], emitters: b.emitters, ...(o.duration ?? b.duration ? { duration: o.duration ?? b.duration } : {}), ...(o.seed !== undefined ? { seed: o.seed } : {}) };
  const tracks: Track[] = [pt];
  if (b.sound && o.withSound !== false) { const st: SoundTrack = { kind: "sound", at: o.at + (b.sound.at ?? 0), sound: b.sound.sound, ...(b.sound.gain !== undefined ? { gain: b.sound.gain } : {}), ...(b.sound.pitch !== undefined ? { pitch: b.sound.pitch } : {}), node: o.node }; tracks.push(st); }
  if (b.light && o.lightNode) {
    const keys: MaterialTrack["keys"] = b.light.flicker
      ? [0, 5, 9, 14, 20, 26, 31, 37].map((t, i) => ({ t: o.at + t, v: [b.light!.peak, b.light!.peak - 2, b.light!.peak - 1, b.light!.peak - 3, b.light!.peak, b.light!.peak - 2, b.light!.peak - 1, b.light!.peak - 3][i], ease: "step" as const }))
      : [{ t: o.at, v: b.light.peak, ease: "step" }, { t: o.at + Math.max(1, b.light.fadeTicks), v: 0, ease: b.light.fadeTicks > 2 ? "linear" : "step" }];
    tracks.push({ kind: "material", node: o.lightNode, channel: "brightness", keys });
  }
  return { tracks, issues };
}

/** A standalone effect spec (catalog entry + preview): one emitter node at the origin, one clip "play". */
export function effectSpec(id: string, params: Record<string, unknown> = {}): { spec: MotionSpec; issues: { param: string; message: string }[] } {
  const e = effectById(id);
  if (!e) throw new Error(`unknown effect ${id}`);
  const { values, issues } = resolveParams(e.params, params);
  const b = e.build(values);
  const { tracks } = effectTracks(id, { node: "fx", at: 0, params: values, lightNode: "fx", seed: 1 });
  const name = id.slice("effect:".length);
  return {
    spec: {
      schemaVersion: 1, id: name, title: e.title,
      rig: { nodes: [{ name: "fx", parent: null, kind: "emitter", pivot: [0, 0, 0] }] },
      clips: [{ name: "play", length: b.length, loop: b.loop, tracks }],
      meta: { tags: e.tags.slice(0, 12), source: "preset", preset: id as `effect:${string}`, params: values },
    },
    issues,
  };
}

