 * flash on `lightNode` when given). Seeds come from the effect id + `seed` so two placements differ but stay stable.
 */
export function effectTracks(id: string, o: { node: string; at: number; params?: Record<string, unknown>; seed?: number; lightNode?: string; withSound?: boolean; duration?: number }): { tracks: Track[]; issues: { param: string; message: string }[] } {
  const e = effectById(id);
  if (!e) throw new Error(`unknown effect ${id}`);
  const { values, issues } = resolveParams(e.params, o.params);
  const b = e.build(values);
  const pt: ParticleTrack = { kind: "particle", node: o.node, at: o.at, effect: e.id as ParticleTrack["effect"], emitters: b.emitters, ...(o.duration ?? b.duration ? { duration: o.duration ?? b.duration } : {}), ...(o.seed !== undefined ? { seed: o.seed } : {}) };
  const tracks: Track[] = [pt];
  if (b.sound && o.withSound !== false) { const st: SoundTrack = { kind: "sound", at: o.at + (b.sound.at ?? 0), sound: b.sound.sound, ...(b.sound.gain !== undefined ? { gain: b.sound.gain } : {}), ...(b.sound.pitch !== undefined ? { pitch: b.sound.pitch } : {}), node: o.node }; tracks.push(st); }
  if (b.light && o.lightNode) {
    const keys: MaterialTrack["keys"] = b.light.flicker
      ? [0, 5, 9, 14, 20, 26, 31, 37].map((t, i) => ({ t: o.at + t, v: [b.light!.peak, b.light!.peak - 2, b.light!.peak - 1, b.light!.peak - 3, b.light!.peak, b.light!.peak - 2, b.light!.peak - 1, b.light!.peak - 3][i], ease: "step" as const }))
      : [{ t: o.at, v: b.light.peak, ease: "step" }, { t: o.at + Math.max(1, b.light.fadeTicks), v: 0, ease: b.light.fadeTicks > 2 ? "linear" : "step" }];
    tracks.push({ kind: "material", node: o.lightNode, channel: "brightness", keys });
  }
  return { tracks, issues };
}

/** A standalone effect spec (catalog entry + preview): one emitter node at the origin, one clip "play". */
export function effectSpec(id: string, params: Record<string, unknown> = {}): { spec: MotionSpec; issues: { param: string; message: string }[] } {
  const e = effectById(id);
  if (!e) throw new Error(`unknown effect ${id}`);
  const { values, issues } = resolveParams(e.params, params);
  const b = e.build(values);
  const { tracks } = effectTracks(id, { node: "fx", at: 0, params: values, lightNode: "fx", seed: 1 });
  const name = id.slice("effect:".length);
  return {
    spec: {
      schemaVersion: 1, id: name, title: e.title,
      rig: { nodes: [{ name: "fx", parent: null, kind: "emitter", pivot: [0, 0, 0] }] },
      clips: [{ name: "play", length: b.length, loop: b.loop, tracks }],
      meta: { tags: e.tags.slice(0, 12), source: "preset", preset: id as `effect:${string}`, params: values },
    },
    issues,
  };
}

