// Cyrus motion presets, kind `motion`: a semi-automatic pistol / rifle. Two catalog entries share one rig:
//   motion:gun_fire    one clip: slide kick, recoil, hammer drop, trigger pull, muzzle flash, brass, shot, light
//   motion:gun_reload  the full state machine: idle / fire / fire_last -> empty (slide locked back) / dry click /
//                      reload (mag out, mag in) -> cock (slide release) with integer ammo + chambered vars
// Parametric (magazine size, timings, recoil, slide travel, sounds); timings in ticks (20 per second). Rig in blocks,
// gun pointing -z, origin at the grip. Sound ids are Sound Library catalog ids (`sound:<id>`) or vanilla keys.
import type { Clip, Machine, MotionSpec, RigNode, Track } from "../spec";
import { effectTracks } from "./effects";
import { num, q3, resolveParams, str, type ParamDef, type ParamValues } from "./params";

export const GUN_PARAMS: ParamDef[] = [
  { name: "magSize", type: "number", min: 1, max: 60, default: 12, step: 1, label: "Magazine size" },
  { name: "fireTicks", type: "number", min: 2, max: 20, default: 4, step: 1, label: "Fire cycle", unit: "ticks" },
  { name: "reloadTicks", type: "number", min: 16, max: 80, default: 34, step: 1, label: "Reload", unit: "ticks" },
  { name: "recoil", type: "number", min: 0, max: 20, default: 6, step: 0.5, label: "Recoil kick", unit: "degrees" },
  { name: "slideTravel", type: "number", min: 0.02, max: 0.3, default: 0.12, step: 0.01, label: "Slide travel", unit: "blocks" },
  { name: "length", type: "number", min: 0.4, max: 1.6, default: 0.75, step: 0.05, label: "Gun length", unit: "blocks" },
  { name: "shot", type: "sound", default: "sound:gun_pistol_shot", label: "Shot sound" },
  { name: "dry", type: "sound", default: "minecraft:block.lever.click", label: "Dry click" },
  { name: "magOut", type: "sound", default: "minecraft:block.iron_trapdoor.open", label: "Magazine out" },
  { name: "magIn", type: "sound", default: "minecraft:block.iron_trapdoor.close", label: "Magazine in" },
  { name: "rack", type: "sound", default: "minecraft:block.piston.contract", label: "Slide rack" },
];

function rig(p: ParamValues): RigNode[] {
  const L = num(p, "length");
  return [
    { name: "body", parent: null, kind: "part", pivot: [0, 0, 0], proxy: { size: [0.16, 0.14, q3(L * 0.9)], offset: [0, 0.2, q3(-L * 0.35)], color: "#3a3f47" } },
    { name: "grip", parent: "body", kind: "part", pivot: [0, 0.12, 0], rest: { rot: [-12, 0, 0] }, proxy: { size: [0.14, 0.3, 0.16], offset: [0, -0.05, 0.02], color: "#2a2d33" } },
    { name: "slide", parent: "body", kind: "part", pivot: [0, 0.3, q3(-L * 0.35)], proxy: { size: [0.15, 0.09, q3(L * 0.86)], offset: [0, 0, 0], color: "#646b76" } },
    { name: "hammer", parent: "body", kind: "hinge", pivot: [0, 0.3, q3(L * 0.08)], hinge: { axis: "x", min: -50, max: 0 }, proxy: { size: [0.04, 0.08, 0.04], offset: [0, 0.04, 0], color: "#1e2025" } },
    { name: "trigger", parent: "body", kind: "hinge", pivot: [0, 0.12, q3(-L * 0.12)], hinge: { axis: "x", min: 0, max: 25 }, proxy: { size: [0.03, 0.08, 0.03], offset: [0, -0.04, 0], color: "#1e2025" } },
    { name: "mag", parent: "body", kind: "part", pivot: [0, 0.05, 0.02], rest: { rot: [-12, 0, 0] }, proxy: { size: [0.1, 0.26, 0.12], offset: [0, -0.15, 0], color: "#202328" } },
    { name: "muzzle", parent: "slide", kind: "emitter", pivot: [0, 0.3, q3(-L * 0.78)] },
    { name: "ejector", parent: "slide", kind: "emitter", pivot: [0.08, 0.32, q3(-L * 0.2)] },
  ];
}

function fireClip(p: ParamValues, name: "fire" | "fire_last"): Clip {
  const T = num(p, "fireTicks"), kick = num(p, "slideTravel"), rec = num(p, "recoil");
  const last = name === "fire_last";
  const tracks: Track[] = [
    { kind: "transform", node: "slide", channel: "pos", keys: last ? [{ t: 0, v: [0, 0, 0] }, { t: 1, v: [0, 0, kick], ease: "out" }] : [{ t: 0, v: [0, 0, 0] }, { t: 1, v: [0, 0, kick], ease: "out" }, { t: T, v: [0, 0, 0], ease: "inout" }] },
    { kind: "transform", node: "body", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 1, v: [rec, 0, 0], ease: "out" }, { t: T, v: [0, 0, 0], ease: "inout" }] },
    { kind: "transform", node: "hammer", channel: "rot", keys: last ? [{ t: 0, v: [-45, 0, 0] }, { t: 1, v: [0, 0, 0], ease: "in" }] : [{ t: 0, v: [-45, 0, 0] }, { t: 1, v: [0, 0, 0], ease: "in" }, { t: 2, v: [-45, 0, 0], ease: "out" }] },
    { kind: "transform", node: "trigger", channel: "rot", keys: [{ t: 0, v: [20, 0, 0] }, { t: T, v: [0, 0, 0], ease: "out" }] },
    ...effectTracks("effect:muzzle_flash", { node: "muzzle", at: 0, lightNode: "muzzle", seed: 11 }).tracks,
    { kind: "particle", node: "ejector", at: 1, effect: "effect:brass", seed: 13, emitters: [{ sprite: "debris", shape: "cone", cone: 20, dir: [1, 0.6, 0.2], burst: 1, life: [10, 14], speed: [2, 3], gravity: 18, size: [0.05, 0.05], colors: ["#d8a948"] }] },
    { kind: "sound", at: 0, sound: str(p, "shot"), gain: 1, pitch: 1, node: "muzzle" },
  ];
  return { name, length: T, loop: "once", tracks };
}

function reloadClip(p: ParamValues): Clip {
  const R = num(p, "reloadTicks");
  const t = (f: number) => Math.max(1, Math.min(R - 1, Math.round(R * f)));
  return {
    name: "reload", length: R, loop: "once",
    tracks: [
      { kind: "transform", node: "mag", channel: "pos", keys: [{ t: 0, v: [0, 0, 0] }, { t: t(0.18), v: [0, -0.45, 0.08], ease: "in" }, { t: t(0.42), v: [0, -0.45, 0.08], ease: "step" }, { t: t(0.6), v: [0, 0, 0], ease: "out" }] },
      { kind: "transform", node: "body", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: t(0.15), v: [-8, 0, 18], ease: "inout" }, { t: t(0.75), v: [-8, 0, 18] }, { t: R, v: [0, 0, 0], ease: "inout" }] },
      { kind: "sound", at: t(0.12), sound: str(p, "magOut"), pitch: 1.4 },
      { kind: "sound", at: t(0.56), sound: str(p, "magIn"), pitch: 1.5 },
      { kind: "event", at: t(0.6), name: "mag_in" },
    ],
  };
}

function cockClip(p: ParamValues): Clip {
  const kick = num(p, "slideTravel");
  return {
    name: "cock", length: 10, loop: "once",
    tracks: [
      { kind: "transform", node: "slide", channel: "pos", keys: [{ t: 0, v: [0, 0, kick] }, { t: 4, v: [0, 0, q3(kick * 1.15)], ease: "out" }, { t: 6, v: [0, 0, 0], ease: "in" }] },
      { kind: "transform", node: "hammer", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 4, v: [-45, 0, 0], ease: "out" }] },
      { kind: "sound", at: 5, sound: str(p, "rack"), pitch: 1.6 },
      { kind: "event", at: 6, name: "chambered" },
    ],
  };
}

export function gunFireSpec(params: Record<string, unknown> = {}): { spec: MotionSpec; issues: { param: string; message: string }[] } {
  const { values, issues } = resolveParams(GUN_PARAMS, params);
  return { spec: { schemaVersion: 1, id: "gun_fire", title: "Gun fire", rig: { nodes: rig(values) }, clips: [fireClip(values, "fire")], meta: { tags: ["gun", "weapon", "pistol", "fire"], source: "preset", preset: "motion:gun_fire", params: values } }, issues };
}

export function gunReloadSpec(params: Record<string, unknown> = {}): { spec: MotionSpec; issues: { param: string; message: string }[] } {
  const { values, issues } = resolveParams(GUN_PARAMS, params);
  const mag = num(values, "magSize");
  const kick = num(values, "slideTravel");
  const clips: Clip[] = [
    { name: "idle", length: 1, loop: "hold", tracks: [{ kind: "transform", node: "hammer", channel: "rot", keys: [{ t: 0, v: [-45, 0, 0] }] }] },
    fireClip(values, "fire"),
    fireClip(values, "fire_last"),
    { name: "empty", length: 1, loop: "hold", tracks: [{ kind: "transform", node: "slide", channel: "pos", keys: [{ t: 0, v: [0, 0, kick] }] }] },
    { name: "dry", length: 4, loop: "once", tracks: [{ kind: "transform", node: "trigger", channel: "rot", keys: [{ t: 0, v: [20, 0, 0] }, { t: 4, v: [0, 0, 0], ease: "out" }] }, { kind: "sound", at: 0, sound: str(values, "dry"), pitch: 1.6 }] },
    reloadClip(values),
    cockClip(values),
  ];
  // the slide stays locked back through a reload from empty: the reload clip's own tracks do not move the slide, and
  // cock starts from the locked position
  const machine: Machine = {
    name: "gun", initial: "idle",
    vars: [{ name: "ammo", init: mag, min: 0, max: mag }, { name: "chambered", init: 1, min: 0, max: 1 }],
    states: [
      { name: "idle", clip: "idle", onEnter: [{ do: "emit", event: "auto_cock" }] },
      { name: "fire", clip: "fire", onEnter: [{ do: "add", var: "ammo", by: -1 }], after: { to: "idle" } },
      { name: "fire_last", clip: "fire_last", onEnter: [{ do: "add", var: "ammo", by: -1 }, { do: "set", var: "chambered", value: 0 }], after: { to: "empty" } },
      { name: "empty", clip: "empty" },
      { name: "dry", clip: "dry", after: { to: "empty" } },
      { name: "reload", clip: "reload", onEnter: [{ do: "set", var: "ammo", value: mag }], after: { to: "idle" } },
      { name: "cock", clip: "cock", onEnter: [{ do: "set", var: "chambered", value: 1 }], after: { to: "idle" } },
    ],
    transitions: [
      { from: "idle", on: "fire", to: "fire", guard: [{ var: "ammo", op: "gt", value: 1 }] },
      { from: "idle", on: "fire", to: "fire_last", guard: [{ var: "ammo", op: "eq", value: 1 }, { var: "chambered", op: "eq", value: 1 }] },
      { from: "empty", on: "fire", to: "dry" },
      { from: "idle", on: "reload", to: "reload", guard: [{ var: "ammo", op: "lt", value: mag }] },
      { from: "empty", on: "reload", to: "reload" },
      { from: "idle", on: "auto_cock", to: "cock", guard: [{ var: "chambered", op: "eq", value: 0 }, { var: "ammo", op: "gt", value: 0 }] },
      { from: "idle", on: "cock", to: "cock", guard: [{ var: "chambered", op: "eq", value: 0 }, { var: "ammo", op: "gt", value: 0 }] },
    ],
  };
  return { spec: { schemaVersion: 1, id: "gun_reload", title: "Gun fire, reload and cock", rig: { nodes: rig(values) }, clips, machines: [machine], meta: { tags: ["gun", "weapon", "pistol", "reload", "cock"], source: "preset", preset: "motion:gun_reload", params: values } }, issues };
}

