// Cyrus motion presets, kind `motion`: a hinged door (also gates, lids, hatches: change the axis / size). A frame, a
// hinge node with limits and a handle; clips shut / open / ajar / close; a toggle state machine with anti-spam
// (minTicks) and explicit open / close events, plus `opened` / `closed` markers. Parametric: size, angle, timings,
// swing side, ease, an overshoot bounce, sounds.
import type { Clip, Ease, MotionSpec } from "../spec";
import { num, q3, resolveParams, str, type ParamDef } from "./params";

export const DOOR_PARAMS: ParamDef[] = [
  { name: "width", type: "number", min: 0.5, max: 3, default: 1, step: 0.0625, label: "Width", unit: "blocks" },
  { name: "height", type: "number", min: 0.5, max: 4, default: 2, step: 0.0625, label: "Height", unit: "blocks" },
  { name: "thickness", type: "number", min: 0.0625, max: 0.5, default: 0.1875, step: 0.0625, label: "Thickness", unit: "blocks" },
  { name: "angle", type: "number", min: 20, max: 120, default: 90, step: 1, label: "Open angle", unit: "degrees" },
  { name: "openTicks", type: "number", min: 2, max: 60, default: 10, step: 1, label: "Open time", unit: "ticks" },
  { name: "closeTicks", type: "number", min: 2, max: 60, default: 8, step: 1, label: "Close time", unit: "ticks" },
  { name: "bounce", type: "number", min: 0, max: 10, default: 3, step: 0.5, label: "Overshoot", unit: "degrees" },
  { name: "swing", type: "enum", options: ["left", "right"], default: "left", label: "Hinge side" },
  { name: "ease", type: "enum", options: ["linear", "out", "inout", "smooth"], default: "out", label: "Ease" },
  { name: "openSound", type: "sound", default: "minecraft:block.wooden_door.open", label: "Open sound" },
  { name: "closeSound", type: "sound", default: "minecraft:block.wooden_door.close", label: "Close sound" },
];

export function doorSpec(params: Record<string, unknown> = {}): { spec: MotionSpec; issues: { param: string; message: string }[] } {
  const { values: p, issues } = resolveParams(DOOR_PARAMS, params);
  const W = num(p, "width"), H = num(p, "height"), D = num(p, "thickness");
  const left = str(p, "swing") === "left";
  // swinging towards -z (away from a player standing at +z); the left hinge turns +y, the right hinge -y
  const sign = left ? 1 : -1;
  const A = num(p, "angle") * sign, B = num(p, "bounce") * sign;
  const hx = q3(left ? -W / 2 : W / 2);
  const oT = num(p, "openTicks"), cT = num(p, "closeTicks"), e = str(p, "ease") as Ease;
  const lim = left ? { min: 0, max: q3(num(p, "angle") + num(p, "bounce")) } : { min: q3(-(num(p, "angle") + num(p, "bounce"))), max: 0 };
  const open: Clip = {
    name: "open", length: oT + (B ? 3 : 0), loop: "once",
    tracks: [
      { kind: "transform", node: "door", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, ...(B ? [{ t: oT, v: [0, q3(A + B), 0] as [number, number, number], ease: e }, { t: oT + 3, v: [0, A, 0] as [number, number, number], ease: "inout" as const }] : [{ t: oT, v: [0, A, 0] as [number, number, number], ease: e }])] },
      { kind: "transform", node: "handle", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 2, v: [0, 0, q3(-30 * sign)], ease: "out" }, { t: 5, v: [0, 0, 0], ease: "inout" }].filter((k) => k.t <= oT + (B ? 3 : 0)) },
      { kind: "sound", at: 0, sound: str(p, "openSound"), node: "door" },
      { kind: "event", at: Math.max(0, oT - 1), name: "opened" },
    ],
  };
  const close: Clip = {
    name: "close", length: cT, loop: "once",
    tracks: [
      { kind: "transform", node: "door", channel: "rot", keys: [{ t: 0, v: [0, A, 0] }, { t: cT, v: [0, 0, 0], ease: "in" }] },
      { kind: "sound", at: Math.max(0, cT - 1), sound: str(p, "closeSound"), node: "door" },
      { kind: "event", at: Math.max(0, cT - 1), name: "closed" },
    ],
  };
  const spec: MotionSpec = {
    schemaVersion: 1, id: "door_hinge", title: "Hinged door",
    rig: { nodes: [
      { name: "frame", parent: null, kind: "part", pivot: [0, 0, 0], proxy: { size: [q3(W + 0.25), 0.125, 0.25], offset: [0, q3(H + 0.0625), 0], color: "#5a3d22" } },
      { name: "door", parent: "frame", kind: "hinge", pivot: [hx, 0, 0], hinge: { axis: "y", ...lim }, proxy: { size: [W, H, D], offset: [0, q3(H / 2), 0], color: "#a8784a" } },
      { name: "handle", parent: "door", kind: "part", pivot: [q3(left ? W * 0.35 : -W * 0.35), q3(H * 0.47), q3(D / 2 + 0.03)], proxy: { size: [0.16, 0.05, 0.05], offset: [q3(left ? -0.05 : 0.05), 0, 0], color: "#d9b44a" } },
    ] },
    clips: [
      { name: "shut", length: 1, loop: "hold", tracks: [] },
      open,
      { name: "ajar", length: 1, loop: "hold", tracks: [{ kind: "transform", node: "door", channel: "rot", keys: [{ t: 0, v: [0, A, 0] }] }] },
      close,
    ],
    machines: [{
      name: "door", initial: "closed",
      states: [
        { name: "closed", clip: "shut" },
        { name: "opening", clip: "open", after: { to: "open" } },
        { name: "open", clip: "ajar" },
        { name: "closing", clip: "close", after: { to: "closed" } },
      ],
      transitions: [
        { from: "closed", on: "toggle", to: "opening", minTicks: 2 },
        { from: "open", on: "toggle", to: "closing", minTicks: 2 },
        { from: "closed", on: "open", to: "opening" },
        { from: "open", on: "close", to: "closing" },
      ],
    }],
    meta: { tags: ["door", "hinge", "gate", "prop"], source: "preset", preset: "motion:door_hinge", params: p },
  };
  return { spec, issues };
}

