// Cyrus motion presets: the PARAMETRIC GAIT GENERATOR (gen:gait) for creatures: idle, walk and attack clips plus a
// small state machine (idle <-> walk on move / stop, attack from anywhere, back to idle). Bone names are the RigSpec
// archetype templates' (lib/cyrus/creature/templates.ts: humanoid, quadruped, floating_ghost), so a generated gait
// drives a RigSpec creature through the bridge (./bridge.ts toLegacyClip) and the Model Studio timeline edits it.
// The walk is waves (the reliable AI primitive): legs in antiphase, arms against legs, body bob at twice the step rate,
// quadrupeds in diagonal pairs, ghosts float and trail. Proxy boxes approximate the template cubes for the preview.
import type { Clip, Machine, MotionSpec, RigNode, Track } from "../spec";
import { num, q3, resolveParams, str, type ParamDef, type ParamValues } from "./params";

export const GAIT_ARCHETYPES = ["humanoid", "quadruped", "floating_ghost"] as const;
export const GAIT_PARAMS: ParamDef[] = [
  { name: "archetype", type: "enum", options: GAIT_ARCHETYPES, default: "humanoid", label: "Body type" },
  { name: "cadence", type: "number", min: 0.5, max: 4, default: 1.6, step: 0.05, label: "Steps per second" },
  { name: "stride", type: "number", min: 5, max: 60, default: 32, step: 1, label: "Leg swing", unit: "degrees" },
  { name: "armSwing", type: "number", min: 0, max: 60, default: 24, step: 1, label: "Arm swing", unit: "degrees" },
  { name: "bob", type: "number", min: 0, max: 0.2, default: 0.04, step: 0.005, label: "Body bob", unit: "blocks" },
  { name: "sway", type: "number", min: 0, max: 15, default: 3, step: 0.5, label: "Body sway", unit: "degrees" },
  { name: "attackTicks", type: "number", min: 6, max: 40, default: 14, step: 1, label: "Attack length", unit: "ticks" },
  { name: "reach", type: "number", min: 20, max: 140, default: 90, step: 1, label: "Attack reach", unit: "degrees" },
  { name: "scale", type: "number", min: 0.4, max: 3, default: 1, step: 0.05, label: "Size" },
  { name: "attackSound", type: "sound", default: "minecraft:entity.zombie.attack_wooden_door", label: "Attack sound" },
];

type B = [string, string | null, [number, number, number], [number, number, number], [number, number, number], string];
// [name, parent, pivot (px), box size (px), box offset from pivot (px), colour]; px = 1/16 block
const BODIES: Record<(typeof GAIT_ARCHETYPES)[number], B[]> = {
  humanoid: [
    ["root", null, [0, 0, 0], [0, 0, 0], [0, 0, 0], "#000000"],
    ["body", "root", [0, 12, 0], [8, 12, 4], [0, 6, 0], "#5f7f9a"],
    ["head", "body", [0, 24, 0], [8, 8, 8], [0, 4, 0], "#d9b38c"],
    ["arm_r", "body", [5, 22, 0], [4, 12, 4], [1, -4, 0], "#5f7f9a"],
    ["arm_l", "body", [-5, 22, 0], [4, 12, 4], [-1, -4, 0], "#5f7f9a"],
    ["leg_r", "root", [2, 12, 0], [4, 12, 4], [0, -6, 0], "#3b4a5a"],
    ["leg_l", "root", [-2, 12, 0], [4, 12, 4], [0, -6, 0], "#3b4a5a"],
  ],
  quadruped: [
    ["root", null, [0, 0, 0], [0, 0, 0], [0, 0, 0], "#000000"],
    ["body", "root", [0, 11, 0], [8, 7, 14], [0, 0, 0], "#8a6a4a"],
    ["head", "body", [0, 12, -7], [6, 6, 6], [0, 1, -3], "#9a7a5a"],
    ["leg_fr", "body", [2.5, 7, -4.5], [3, 7, 3], [0, -3.5, 0], "#6a4a2a"],
