// Cyrus motion PRESET LIBRARY v0 (authored by Cyrus, licence nxeon-original). Catalog kinds `motion` (rigs, clips,
// machines) and `effect` (particle / sound / light bundles). The AI's first move is to pick one of these and set its
// knobs; generators (gen:*) build families from parameters; a human then fixes details in the timeline.
// Entries have the catalog v2 shape (id, kind, title, summary, tags, params, provenance, licence) so they can join
// lib/cyrus/library/v2 once the owner decides the gating of the new kinds (MOTION-PLAN.md section 7). Pure.
import type { MotionSpec } from "../spec";
import { EFFECTS, effectSpec } from "./effects";
import { DOOR_PARAMS, doorSpec } from "./door";
import { GAIT_PARAMS, gaitSpec } from "./gait";
import { GUN_PARAMS, gunFireSpec, gunReloadSpec } from "./gun";
import type { ParamDef } from "./params";

export type MotionCatalogKind = "motion" | "effect";
export type MotionPreset = {
  id: string;
  kind: MotionCatalogKind;
  title: string;
  summary: string;
  tags: string[];
  params: ParamDef[];
  provenance: "cyrus-authored";
  licence: "nxeon-original";
  /** a generator builds a family from parameters (gen:*); a preset is one tuned spec with knobs */
  generator: boolean;
  build(params?: Record<string, unknown>): { spec: MotionSpec; issues: { param: string; message: string }[] };
};

const base = { provenance: "cyrus-authored" as const, licence: "nxeon-original" as const };

export const MOTION_PRESETS: MotionPreset[] = [
  { ...base, id: "motion:gun_fire", kind: "motion", title: "Gun fire", summary: "Slide kick, recoil, hammer drop, muzzle flash, brass, shot sound and a light flash in one clip.", tags: ["gun", "weapon", "fire", "pistol"], params: GUN_PARAMS, generator: false, build: gunFireSpec },
  { ...base, id: "motion:gun_reload", kind: "motion", title: "Gun fire, reload and cock", summary: "A state machine with ammo: fire, last shot locks the slide, dry click, magazine reload and slide release.", tags: ["gun", "weapon", "reload", "cock", "state"], params: GUN_PARAMS, generator: false, build: gunReloadSpec },
  { ...base, id: "motion:door_hinge", kind: "motion", title: "Hinged door", summary: "A door on a hinge with limits: open with overshoot, close, toggle with anti-spam, sounds.", tags: ["door", "hinge", "gate", "prop"], params: DOOR_PARAMS, generator: false, build: doorSpec },
  { ...base, id: "gen:gait", kind: "motion", title: "Creature gait", summary: "Idle, walk and attack for humanoid, quadruped or floating-ghost bodies from a few knobs.", tags: ["creature", "gait", "walk", "attack"], params: GAIT_PARAMS, generator: true, build: gaitSpec },
  ...EFFECTS.map((e): MotionPreset => ({ ...base, id: e.id, kind: "effect", title: e.title, summary: e.summary, tags: e.tags, params: e.params, generator: false, build: (p) => effectSpec(e.id, p) })),
];

export const presetById = (id: string) => MOTION_PRESETS.find((p) => p.id === id);

/** Keyword search over title / tags / summary (the cheap retrieval the AI tool and the preset browser share). */
export function searchPresets(q: string, kind?: MotionCatalogKind): MotionPreset[] {
  const words = q.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 1);
  const score = (p: MotionPreset) => words.reduce((s, w) => s + (p.tags.some((t) => t.startsWith(w)) ? 3 : 0) + (p.title.toLowerCase().includes(w) ? 2 : 0) + (p.summary.toLowerCase().includes(w) ? 1 : 0), 0);
  return MOTION_PRESETS.filter((p) => !kind || p.kind === kind).map((p) => ({ p, s: score(p) })).filter((x) => !words.length || x.s > 0).sort((a, b) => b.s - a.s || a.p.id.localeCompare(b.p.id)).map((x) => x.p);
}

