import type { MotionCapability } from "../motion/caps";

export const minecraftMotionCapability: MotionCapability = {
  game: "minecraft",
  tickRate: 20,
  trackKinds: { transform: "approx", particle: "approx", sound: "native", material: "approx", event: "native" },
  // vehicles are not a Minecraft target (owner, 2026-10-10): no wheel / seat nodes, no attach
  nodeKinds: ["bone", "part", "socket", "hinge", "emitter"],
  materialChannels: ["brightness"],
  attach: false,
  interpolation: "linear-segments",
  instanceOverhead: 1, // the interaction entity that takes clicks
  caps: {
    nodes: 16, depth: 6, clips: 12, tracksPerClip: 32, keysPerTrack: 32, keysTotal: 512, durationTicks: 1200,
    particlesPerTick: 64, particlesPerClip: 512, soundsPerClip: 16, machines: 1, states: 12, transitions: 24, liveEntities: 13,
  },
