// Cyrus motion PRESET LIBRARY v0 (lib/cyrus/motion/presets): every preset builds, validates clean on the neutral core
// AND fits Minecraft's caps at its defaults; parameter sweeps stay valid; behaviour checks (gun machine with ammo, door
// toggles, gait symmetry / seamless loops, effect physics); goldens of every default spec.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { canonicalMotion, eventLog, particlesAt, runMachine, sample, simulate, toLegacyClip, validateMotion, cues, type MotionSpec } from "../lib/cyrus/motion";
import { MOTION_PRESETS, presetById, searchPresets, gunReloadSpec, doorSpec, gaitSpec, effectSpec, EFFECTS, GAIT_ARCHETYPES, resolveParams, GUN_PARAMS } from "../lib/cyrus/motion/presets";
import { minecraftMotionCapability } from "../lib/cyrus/adapters/motion-minecraft";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { validateAssetProfile } from "../lib/cyrus/adapters/asset-profile";

const GOLDEN = path.join(__dirname, "fixtures/cyrus-motion/presets-golden.json");
const golden: Record<string, string> = existsSync(GOLDEN) ? JSON.parse(readFileSync(GOLDEN, "utf8")) : {};
const fresh: Record<string, string> = {};
const sha = (s: string) => createHash("sha256").update(s).digest("hex");
function gold(key: string, value: unknown) {
  fresh[key] = sha(canonicalMotion(value));
  if (process.env.UPDATE_CYRUS_MOTION_GOLDEN === "1") { writeFileSync(GOLDEN, JSON.stringify({ ...golden, ...fresh }, null, 1) + "\n"); return; }
  assert.equal(fresh[key], golden[key], `golden ${key} changed (UPDATE_CYRUS_MOTION_GOLDEN=1 to accept)`);
}

describe("motion presets: library", () => {
  it("has the v0 set: gun fire, gun reload, door, gait + 5 effects", () => {
    assert.deepEqual(MOTION_PRESETS.map((p) => p.id), ["motion:gun_fire", "motion:gun_reload", "motion:door_hinge", "gen:gait", "effect:muzzle_flash", "effect:explosion", "effect:fire", "effect:smoke", "effect:water_splash"]);
    assert.ok(MOTION_PRESETS.every((p) => p.provenance === "cyrus-authored" && p.licence === "nxeon-original"));
  });
  for (const p of MOTION_PRESETS) {
    it(`${p.id}: defaults validate clean on the neutral core and fit Minecraft's caps`, () => {
      const { spec, issues } = p.build();
      assert.deepEqual(issues, []);
      const n = validateMotion(spec);
      assert.equal(n.ok, true, JSON.stringify(n.errors));
      assert.deepEqual(n.warnings.map((w) => w.code), []);
      const mc = validateMotion(spec, minecraftMotionCapability);
      assert.equal(mc.ok, true, JSON.stringify(mc.errors));
      assert.equal(spec.meta?.preset, p.id);
      gold(`${p.id}.default`, spec);
    });
  }
  it("search finds the right preset first", () => {
    assert.equal(searchPresets("gun reload magazine")[0].id, "motion:gun_reload");
    assert.equal(searchPresets("wooden door")[0].id, "motion:door_hinge");
    assert.equal(searchPresets("campfire flame", "effect")[0].id, "effect:fire");
    assert.equal(searchPresets("walk cycle creature")[0].id, "gen:gait");
    assert.equal(searchPresets("bomb blast")[0].id, "effect:explosion");
  });
  it("parameters clamp with explicit issues (never throw)", () => {
    const r = resolveParams(GUN_PARAMS, { magSize: 999, recoil: "big", nope: 1, shot: "not a key" });
    assert.equal(r.values.magSize, 60);
    assert.equal(r.values.recoil, 6);
    assert.deepEqual(r.issues.map((i) => i.param).sort(), ["magSize", "nope", "recoil", "shot"]);
  });
  it("parameter sweeps (min / max / both enums) stay valid on the neutral core", () => {
    for (const p of MOTION_PRESETS) {
      const nums = p.params.filter((d) => d.type === "number");
      for (const end of ["min", "max"] as const) {
        const given = Object.fromEntries(nums.map((d) => [d.name, d.type === "number" ? d[end] : 0]));
        for (const d of p.params) if (d.type === "enum") for (const o of d.options) {
          const { spec } = p.build({ ...given, [d.name]: o });
          const v = validateMotion(spec);
          assert.equal(v.ok, true, `${p.id} ${end} ${d.name}=${o}: ${JSON.stringify(v.errors.slice(0, 3))}`);
        }
        const { spec } = p.build(given);
        assert.equal(validateMotion(spec).ok, true, `${p.id} ${end}`);
      }
    }
  });
  it("Minecraft's asset profile declares the motion capability and still validates", () => {
    assert.equal(minecraftAssetProfile.motion, minecraftMotionCapability);
    assert.deepEqual(validateAssetProfile(minecraftAssetProfile), []);
    assert.equal(minecraftMotionCapability.attach, false);
    assert.ok(!minecraftMotionCapability.nodeKinds.includes("wheel"));
  });
});

describe("motion presets: gun state machine", () => {
  const { spec } = gunReloadSpec({ magSize: 3 });
  it("fire x3 (last locks the slide), dry click, reload from empty, auto slide release", () => {
    const sim = simulate(spec, { inputs: [{ tick: 2, event: "fire" }, { tick: 8, event: "fire" }, { tick: 14, event: "fire" }, { tick: 20, event: "fire" }, { tick: 26, event: "reload" }], ticks: 80 });
    const states = sim.frames.filter((f, i) => i === 0 || f.state !== sim.frames[i - 1].state).map((f) => `${f.tick}:${f.state}:${f.vars?.ammo}/${f.vars?.chambered}`);
    assert.deepEqual(states, ["0:idle:3/1", "2:fire:2/1", "6:idle:2/1", "8:fire:1/1", "12:idle:1/1", "14:fire_last:0/0", "18:empty:0/0", "20:dry:0/0", "24:empty:0/0", "26:reload_empty:3/0", "60:cock:3/1", "70:idle:3/1"]);
    const log = eventLog(sim.frames);
    assert.ok(log.includes("t2 sound sound:gun_pistol_shot") && log.includes("t20 sound minecraft:block.lever.click") && log.includes("t65 sound minecraft:block.piston.contract"));
    gold("gun_reload.mag3.eventlog", log);
  });
  it("the slide stays locked back from the last shot through the empty reload", () => {
    const kick = 0.12;
    assert.deepEqual(sample(spec, "fire_last", 4).nodes.slide.pos, [0, 0, kick]);
    assert.deepEqual(sample(spec, "empty", 0).nodes.slide.pos, [0, 0, kick]);
    assert.deepEqual(sample(spec, "reload_empty", 10).nodes.slide.pos, [0, 0, kick]);
    assert.deepEqual(sample(spec, "cock", 10).nodes.slide.pos, [0, 0, 0]);
    assert.deepEqual(sample(spec, "fire", 4).nodes.slide.pos, [0, 0, 0]);
  });
  it("reload at a full magazine is refused by its guard; fire during reload is ignored", () => {
    const r = runMachine(spec, "gun", [{ tick: 1, event: "reload" }, { tick: 3, event: "fire" }, { tick: 4, event: "reload" }], 50);
    assert.ok(r.log.some((l) => l.kind === "ignored" && l.event === "reload" && l.tick === 1 && l.reason === "guard or minTicks not met"));
    const r2 = runMachine(spec, "gun", [{ tick: 1, event: "fire" }, { tick: 6, event: "reload" }, { tick: 10, event: "fire" }], 50);
    assert.ok(r2.log.some((l) => l.kind === "ignored" && l.event === "fire" && l.tick === 10));
  });
  it("muzzle flash fires with the shot and the muzzle light is 15 then 0", () => {
    const fire = spec.clips.find((c) => c.name === "fire")!;
    assert.deepEqual(cues(fire, -1, 0).map((c) => c.kind), ["particle", "particle", "sound"]);
    assert.deepEqual([0, 1, 2].map((t) => sample(spec, "fire", t).material.muzzle?.brightness), [15, 15, 0]);
    assert.equal(particlesAt(spec, "fire", 0).length, 4 + 6 + 3);
  });
});

describe("motion presets: door", () => {
  it("toggle opens (with overshoot) and closes; explicit open/close events; markers", () => {
    const { spec } = doorSpec();
    const sim = simulate(spec, { inputs: [{ tick: 2, event: "toggle" }, { tick: 3, event: "toggle" }, { tick: 30, event: "toggle" }, { tick: 50, event: "open" }], ticks: 70 });
    const log = eventLog(sim.frames);
    assert.deepEqual(log.filter((l) => / state /.test(l)), ["t0 state closed clip shut", "t2 state opening clip open", "t15 state open clip ajar", "t30 state closing clip close", "t38 state closed clip shut", "t50 state opening clip open", "t63 state open clip ajar"]);
    assert.ok(log.includes("t11 event opened") && log.includes("t37 event closed"));
    assert.deepEqual(sample(spec, "open", 10).nodes.door.rot, [0, 93, 0]);
    assert.deepEqual(sample(spec, "open", 13).nodes.door.rot, [0, 90, 0]);
    gold("door.default.eventlog", log);
  });
  it("right-hand door swings the other way; limits follow", () => {
    const { spec } = doorSpec({ swing: "right", bounce: 0, angle: 80 });
    assert.deepEqual(sample(spec, "open", 99).nodes.door.rot, [0, -80, 0]);
    const h = spec.rig.nodes.find((n) => n.name === "door")!.hinge!;
    assert.deepEqual([h.min, h.max], [-80, 0]);
