p='sample.ts'; s=open(p).read()
a=s.index("function unitDir(rand: () => number, e: Emitter): Vec3 {")
b=s.index("function rampColor(")
s=s[:a]+'''const sphereDir = (u: number, v: number): Vec3 => { const zc = u * 2 - 1, ph = v * 2 * Math.PI, rr = Math.sqrt(Math.max(0, 1 - zc * zc)); return [rr * Math.cos(ph), zc, rr * Math.sin(ph)]; };

/**
 * Spawn offset and velocity direction of one particle (local frame) from five uniform numbers. Offsets: sphere = inside
 * the radius, disc = on the horizontal disc, point/cone = none. Direction: inside `cone` around `dir` when cone is set
 * (or shape cone); otherwise radial for a sphere, `dir` for a disc, any direction for a point.
 */
export function spawnLocal(e: Emitter, u: [number, number, number, number, number]): { offset: Vec3; dir: Vec3 } {
  const shape = e.shape ?? "point";
  const d0 = e.dir ?? [0, 1, 0];
  const dl = Math.hypot(d0[0], d0[1], d0[2]) || 1;
  const dir: Vec3 = [d0[0] / dl, d0[1] / dl, d0[2] / dl];
  const R = e.radius ?? 0;
  const radial = sphereDir(u[3], u[4]);
  let offset: Vec3 = [0, 0, 0];
  if (shape === "sphere") offset = [radial[0] * R * Math.cbrt(u[2]), radial[1] * R * Math.cbrt(u[2]), radial[2] * R * Math.cbrt(u[2])];
  else if (shape === "disc") { const ph = u[3] * 2 * Math.PI, rr = R * Math.sqrt(u[2]); offset = [rr * Math.cos(ph), 0, rr * Math.sin(ph)]; }
  if (e.cone !== undefined || shape === "cone") {
    const half = ((e.cone ?? 30) * Math.PI) / 180;
    const cosT = 1 - u[0] * (1 - Math.cos(half)), sinT = Math.sqrt(Math.max(0, 1 - cosT * cosT)), ph = u[1] * 2 * Math.PI;
    const a: Vec3 = Math.abs(dir[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
    const x: Vec3 = [dir[1] * a[2] - dir[2] * a[1], dir[2] * a[0] - dir[0] * a[2], dir[0] * a[1] - dir[1] * a[0]];
    const xl = Math.hypot(...x) || 1; x[0] /= xl; x[1] /= xl; x[2] /= xl;
    const y: Vec3 = [dir[1] * x[2] - dir[2] * x[1], dir[2] * x[0] - dir[0] * x[2], dir[0] * x[1] - dir[1] * x[0]];
    return { offset, dir: [0, 1, 2].map((k) => dir[k] * cosT + (x[k] * Math.cos(ph) + y[k] * Math.sin(ph)) * sinT) as Vec3 };
  }
