/** Is an emitter's velocity aimed (a cone, or a disc pushing along `dir`) rather than random / radial? */
export const isDirected = (e: Emitter) => e.cone !== undefined || e.shape === "cone" || e.shape === "disc";

/**
 * Every particle one particle track spawns in ONE play starting at local tick `start` (the clip's cycle start + at):
 * birth tick, lifetime, world origin, unit direction and speed (blocks per second), from the seeded stream. The single
 * source of truth for the preview (particlesAt) and every game lowering (Minecraft spawns exactly these).
 */
export function particleBirths(spec: MotionSpec, clip: Clip, trackIndex: number, start: number, worldAt?: (t: number) => Record<string, M4>): ParticleBirth[] {
  const tr = clip.tracks[trackIndex];
  if (!tr || tr.kind !== "particle") return [];
  const node = nodeOf(spec, tr.node);
  if (!node) return [];
  const cache = new Map<number, Record<string, M4>>();
  const wAt = worldAt ?? ((t: number) => { let w = cache.get(t); if (!w) { w = worldMatrices(spec, sample(spec, clip.name, t)); cache.set(t, w); } return w; });
  const dur = tr.duration ?? 0;
  const period = clip.loop === "loop" ? clip.length : clip.loop === "pingpong" ? 2 * clip.length : 0;
  const out: ParticleBirth[] = [];
  tr.emitters.forEach((e, ei) => {
    const rand = mulberry32((tr.seed ?? hash32(`${spec.id}:${clip.name}:${trackIndex}`)) + ei * 7919 + Math.floor(start / Math.max(1, period || 1)) * 104729);
    const span = Math.max(1, dur);
    for (let k = 0; k < span; k++) {
