        const u: [number, number, number, number, number] = [rand(), rand(), rand(), rand(), rand()];
        const life = Math.round(lerp(e.life[0], e.life[1], uLife));
        const m = wAt(Math.max(0, birth - (period ? Math.floor(birth / period) * period : 0)))[node.name] ?? I4();
        const loc = spawnLocal(e, u);
        const origin = apply(m, [node.pivot[0] + loc.offset[0], node.pivot[1] + loc.offset[1], node.pivot[2] + loc.offset[2]]);
        const d = applyDir(m, loc.dir);
        const dl = Math.hypot(d[0], d[1], d[2]) || 1;
        out.push({ emitter: ei, birth, life, origin, dir: [d[0] / dl, d[1] / dl, d[2] / dl], speed: lerp(e.speed[0], e.speed[1], uSpeed), directed: isDirected(e) });
      }
    }
  });
  return out;
}

