        const sec = age / TICK_RATE, g = e.gravity ?? 0;
        const pos: Vec3 = [b.origin[0] + b.dir[0] * b.speed * sec, b.origin[1] + b.dir[1] * b.speed * sec - 0.5 * g * sec * sec, b.origin[2] + b.dir[2] * b.speed * sec];
