// Cyrus motion core -> MINECRAFT lowering (the adapter's lower(), lib/cyrus/motion/adapter.ts contract). Pure and
// deterministic: same MotionSpec + binding = same program, byte for byte (golden tested). Labels from
// cyrus-research/R-motion-effects.md: V = verified, U = unverified.
//   - Every visible rig node becomes ONE display entity (block_display by default, item_display for items / custom item
//     models) standing at the instance origin; the node hierarchy is baked into each part's transformation per tick
//     (no passenger chains). Display transformation = translation * left_rotation * scale (right_rotation identity).
//   - Transform tracks become interpolation SEGMENTS {start tick, duration, target}: at `start` the runtime sets
//     interpolation delay 0, duration, and the target transformation (V: Paper Display API; changes in one tick count as
//     one). The client is assumed to interpolate translation / scale linearly and rotation by slerp (U), so eases are
//     split greedily into the longest segments that stay within TOLERANCE of the sampled curve, max 90 degrees each;
//     `step` keys become duration-0 snaps. Resolution: 1 tick (50 ms, V).
//   - Particle tracks spawn exactly the core's particle births (lib/cyrus/motion/sample.ts particleBirths): aimed
//     emitters as one directed vanilla particle each (count 0 = velocity form), random / radial ones as one counted
//     burst per tick. Sprites map to data-free vanilla particles (MC_PARTICLES). Looks are approximate (U).
//   - Sound cues play by key at their tick (`sound:<catalog id>` must resolve to a key of this mod's sounds).
//   - material.brightness becomes display brightness on that node's part; other material channels, attach/detach and
//     wheel / seat semantics are DROPPED with a reason (vehicles are not a Minecraft target).
import type { Dropped, LowerResult } from "../../motion/adapter";
import { minecraftMotionCapability } from "../../adapters/motion-minecraft";
import { I4, Sc, T, apply, compose, decompose, lerp, mul, quatAngle, r4, slerp, type M4, type Quat, type Vec3 } from "../../motion/math";
import { clipTime, cues, isDirected, particleBirths, sample, worldMatrices } from "../../motion/sample";
import type { Clip, MotionSpec, RigNode } from "../../motion/spec";
import { TICK_RATE } from "../../motion/spec";
import { validateMotion, visibleNodes, type MotionIssue } from "../../motion/validate";

/** Data-free particles of every registry version (the designer's verified PARTICLES + four more, javac-checked in the flights). */
export const MC_PARTICLES = ["flame", "soul_fire_flame", "smoke", "large_smoke", "cloud", "poof", "crit", "electric_spark", "glow", "end_rod", "explosion", "lava", "splash", "bubble_pop", "falling_water", "firework", "snowflake", "ash"] as const;
export type McParticle = (typeof MC_PARTICLES)[number];

/** Blocks a proxy box may be drawn with (nearest colour wins) when the binding names none. */
export const PROXY_BLOCKS: [string, string][] = [
  ["minecraft:white_concrete", "#cfd5d6"], ["minecraft:light_gray_concrete", "#7d7d73"], ["minecraft:gray_concrete", "#36393d"], ["minecraft:black_concrete", "#080a0f"],
  ["minecraft:brown_concrete", "#603c20"], ["minecraft:red_concrete", "#8e2121"], ["minecraft:orange_concrete", "#e06101"], ["minecraft:yellow_concrete", "#f0af15"],
  ["minecraft:lime_concrete", "#5ea918"], ["minecraft:green_concrete", "#495b24"], ["minecraft:cyan_concrete", "#157788"], ["minecraft:light_blue_concrete", "#2389c7"],
  ["minecraft:blue_concrete", "#2c2e8f"], ["minecraft:purple_concrete", "#64209c"], ["minecraft:magenta_concrete", "#a9309f"], ["minecraft:pink_concrete", "#d5658e"],
  ["minecraft:oak_planks", "#a2834f"], ["minecraft:spruce_planks", "#735531"], ["minecraft:dark_oak_planks", "#42291a"], ["minecraft:birch_planks", "#c0af79"],
  ["minecraft:iron_block", "#dcdcdc"], ["minecraft:gold_block", "#f6d03d"], ["minecraft:polished_deepslate", "#484849"], ["minecraft:stone", "#7d7d7d"],
];
const rgb = (h: string) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
export function nearestBlock(hex: string): string {
  const c = rgb(hex);
  let best = PROXY_BLOCKS[0][0], bd = Infinity;
  for (const [b, h] of PROXY_BLOCKS) { const d = rgb(h).reduce((s, v, i) => s + (v - c[i]) ** 2, 0); if (d < bd) { bd = d; best = b; } }
  return best;
}

/** Lowering tolerances and limits. */
export const TOLERANCE = { pos: 0.01, deg: 1, scale: 0.01 } as const;
export const MC_LOWER_LIMITS = { maxSegmentTicks: 100, maxSegmentDegrees: 90, segmentsTotal: 4096, cuesTotal: 2048, numbersTotal: 60000 } as const;

export type McPartBinding = { block?: string; item?: string; model?: string };
export type McBinding = { parts?: Record<string, McPartBinding>; triggers?: { rightClick?: string; sneakRightClick?: string; leftClick?: string } };
export type McLowerCtx = {
  /** `sound:<catalog id>` -> the sound key this mod plays for it (from the mod's sound sets); unresolved ids are dropped */
  sounds?: Record<string, string>;
  /** the mod's own namespace (sound keys / item models in it are allowed) */
  namespace: string;
};

export type McPart = { node: string; display: "block" | "item"; material: string; model?: string; /** visual box inside the node, column-major */ local: M4 };
/** 10 numbers: translation x y z, left rotation quaternion x y z w, scale x y z (rounded 1e-4) */
export type McTransform = number[];
export type McSegment = { start: number; dur: number; v: McTransform };
export type McCue =
  | { tick: number; kind: "sound"; key: string; gain: number; pitch: number; at: Vec3 }
  | { tick: number; kind: "particle"; particle: McParticle; count: number; at: Vec3; spread: Vec3; speed: number }
  | { tick: number; kind: "directed"; particle: McParticle; at: Vec3; dir: Vec3; speed: number }
  | { tick: number; kind: "brightness"; part: number; level: number }
  | { tick: number; kind: "event"; name: string };
export type McClip = { name: string; length: number; loop: "once" | "hold" | "loop"; segments: McSegment[][]; cues: McCue[] };
export type McMachine = {
  name: string; initial: number; states: { name: string; clip: number; after: { to: number; ticks: number } | null; onEnter: [number, number, number][] }[];
  transitions: { from: number; on: string; to: number; minTicks: number; guard: [number, number, number][] }[];
  vars: { name: string; init: number; min: number; max: number }[];
};
export type McProgram = {
  id: string; parts: McPart[]; clips: McClip[]; machine: McMachine;
  /** each part's transformation at the initial state's clip tick 0 (spawn pose) */
  spawn: McTransform[];
  interaction: { width: number; height: number };
  triggers: { rightClick: string | null; sneakRightClick: string | null; leftClick: string | null };
  stats: { parts: number; clips: number; segments: number; cues: number; snaps: number; numbers: number };
};

const OPS = ["lt", "le", "eq", "ne", "ge", "gt"] as const;
const toT = (m: M4): { v: McTransform; d: ReturnType<typeof decompose> } => { const d = decompose(m); return { v: [...d.t, ...d.q, ...d.s].map(r4), d }; };
const vecOf = (v: McTransform) => ({ t: v.slice(0, 3) as Vec3, q: v.slice(3, 7) as Quat, s: v.slice(7, 10) as Vec3 });
const same = (a: McTransform, b: McTransform) => a.every((x, i) => Math.abs(x - b[i]) < 1e-4);

/** Sprite (+ colours, size) -> the vanilla particle that reads closest. */
export function mcParticleFor(e: { sprite: string; colors?: string[]; size?: [number, number] }): McParticle {
  const c = (e.colors ?? []).map(rgb);
  const blue = c.some(([r, g, b]) => b > r + 40 && b > g);
  const warm = c.some(([r, g, b]) => r > 150 && r > b + 60 && g > 60);
  const big = (e.size?.[0] ?? 0.1) >= 1.5;
  switch (e.sprite) {
    case "flame": return blue ? "soul_fire_flame" : "flame";
    case "smoke": return (e.size?.[1] ?? e.size?.[0] ?? 0.2) >= 0.6 ? "large_smoke" : "smoke";
    case "spark": return blue ? "electric_spark" : "crit";
    case "flash": return big ? "explosion" : blue ? "electric_spark" : "flame";
    case "glow": return "glow";
    case "droplet": return "splash";
    case "bubble": return "bubble_pop";
    case "debris": return warm ? "lava" : "poof";
    default: return "poof";
  }
}

function soundKey(ref: string, ctx: McLowerCtx): { key: string } | { dropped: string } | { error: string } {
  if (ref.startsWith("sound:")) { const k = ctx.sounds?.[ref.slice(6)]; return k ? { key: k } : { dropped: `${ref} is not one of this mod's sounds (pick it from the Sound Library so it ships in the resource pack)` }; }
  const ns = ref.split(":")[0];
  if (ns === "minecraft" || ns === ctx.namespace) return { key: ref };
  return { error: `${ref} uses the namespace ${ns}; sounds are minecraft: keys, this mod's ${ctx.namespace}: keys or sound:<library id>` };
}

/** Fit interpolation segments to one part's sampled transforms over clip ticks 0..L. */
function fitSegments(at: (t: number) => McTransform, L: number, counters: { snaps: number }): McSegment[] {
  const out: McSegment[] = [];
  const P: McTransform[] = Array.from({ length: L + 1 }, (_, t) => at(t));
  let a = 0;
  let current: McTransform | null = null;
  let blockedUntil = -1; // a snap occupies its tick
  const fits = (a0: number, b0: number) => {
    const A = vecOf(P[a0]), B = vecOf(P[b0]);
    if (quatAngle(A.q, B.q) > MC_LOWER_LIMITS.maxSegmentDegrees) return false;
    for (let t = a0 + 1; t < b0; t++) {
      const f = (t - a0) / (b0 - a0), X = vecOf(P[t]);
      const tl = [0, 1, 2].map((k) => lerp(A.t[k], B.t[k], f)), sl = [0, 1, 2].map((k) => lerp(A.s[k], B.s[k], f));
      if (Math.hypot(tl[0] - X.t[0], tl[1] - X.t[1], tl[2] - X.t[2]) > TOLERANCE.pos) return false;
      if (Math.hypot(sl[0] - X.s[0], sl[1] - X.s[1], sl[2] - X.s[2]) > TOLERANCE.scale) return false;
      if (quatAngle(slerp(A.q, B.q, f), X.q) > TOLERANCE.deg) return false;
    }
    return true;
  };
  // tick 0: always move towards the first target (the client blends from whatever the previous clip left)
  while (a < L) {
    let b = a + 1;
    while (b + 1 <= L && b + 1 - a <= MC_LOWER_LIMITS.maxSegmentTicks && fits(a, b + 1)) b++;
    const target = P[b];
    const isStep = b === a + 1 && !same(P[a], P[b]) && same(at(a + 0.5), P[a]);
    if (isStep) {
      // hold until the key, then snap (duration 0) on tick b
      if (out.length === 0 && a === 0) { out.push({ start: 0, dur: 1, v: P[0] }); current = P[0]; }
      const start = Math.max(b, blockedUntil + 1);
      if (out.length && out[out.length - 1].start === start) out.pop();
      out.push({ start, dur: 0, v: target }); counters.snaps++;
      current = target; blockedUntil = start;
    } else if (!current || !same(current, target) || out.length === 0) {
      const start = Math.max(a, blockedUntil + 1);
      if (start < b) { out.push({ start, dur: b - start, v: target }); current = target; }
    }
    a = b;
  }
  if (!out.length) out.push({ start: 0, dur: 1, v: P[Math.min(1, L)] });
  return out;
}

/** The pingpong mapping as a 2L loop. */
const lowered = (c: Clip): { length: number; loop: McClip["loop"]; time: (t: number) => number } =>
  c.loop === "pingpong" ? { length: 2 * c.length, loop: "loop", time: (t) => clipTime(c, t) } : { length: c.length, loop: c.loop === "loop" ? "loop" : c.loop === "hold" ? "hold" : "once", time: (t) => clipTime(c, t) };

export function lowerMinecraft(spec: MotionSpec, binding: McBinding, ctx: McLowerCtx): LowerResult<McProgram> {
  const warnings: MotionIssue[] = [];
  const errors: MotionIssue[] = [];
  const dropped: Dropped[] = [];
  const v = validateMotion(spec, minecraftMotionCapability);
  warnings.push(...v.warnings);
  if (!v.ok) return { ok: false, errors: v.errors, warnings, dropped };
  const err = (path: string, code: string, message: string) => errors.push({ path, code, severity: "error", message });
  const warn = (path: string, code: string, message: string) => warnings.push({ path, code, severity: "warn", message });

  // ---- parts
  const visible = visibleNodes(spec);
  const partIndex = new Map<string, number>();
  const parts: McPart[] = [];
  for (const k of Object.keys(binding.parts ?? {})) if (!spec.rig.nodes.some((n) => n.name === k)) err(`minecraft.parts.${k}`, "unresolved_ref", `no rig node ${k}`);
  const all = [...visible, ...spec.rig.nodes.filter((n) => binding.parts?.[n.name] && !visible.includes(n))];
  for (const n of all) {
    const b = binding.parts?.[n.name] ?? {};
    const size = n.proxy?.size ?? [1, 1, 1], off = n.proxy?.offset ?? [0, 0, 0];
    if (!n.proxy && !binding.parts?.[n.name]) { warn(`rig.${n.name}`, "part_without_look", `${n.name} has no proxy box or binding; it is drawn as a 1-block placeholder`); }
    if ([b.block, b.item].filter(Boolean).length > 1) err(`minecraft.parts.${n.name}`, "part_binding", "a part is a block OR an item (with an optional model)");
    if (b.model && !b.item) err(`minecraft.parts.${n.name}.model`, "model_needs_item", "a custom item model needs the item it replaces (item)");
    if (b.model && !b.model.startsWith(`${ctx.namespace}:`)) err(`minecraft.parts.${n.name}.model`, "foreign_namespace", `item models must be in this mod's namespace ${ctx.namespace}`);
    const item = !!b.item;
    // block_display draws the unit cube (0..1); item_display draws the item centred on its origin
    const box: M4 = item ? mul(T(off[0], off[1], off[2]), Sc(size[0], size[1], size[2])) : mul(T(off[0] - size[0] / 2, off[1] - size[1] / 2, off[2] - size[2] / 2), Sc(size[0], size[1], size[2]));
    const local = mul(T(n.pivot[0], n.pivot[1], n.pivot[2]), box);
    partIndex.set(n.name, parts.length);
    parts.push({ node: n.name, display: item ? "item" : "block", material: (item ? b.item : b.block) ?? nearestBlock(n.proxy?.color ?? "#7d7d7d"), ...(b.model ? { model: b.model } : {}), local });
  }
  for (const n of spec.rig.nodes) {
    if (n.kind === "wheel" || n.kind === "seat") dropped.push({ path: `rig.${n.name}`, reason: `${n.kind} nodes are drawn as plain parts on Minecraft (vehicles are not a Minecraft target)` });
  }
  if (parts.length + 1 > minecraftMotionCapability.caps.liveEntities) err("rig", "cap_entities", `${parts.length + 1} entities per instance; the limit is ${minecraftMotionCapability.caps.liveEntities}`);

  // ---- clips
  const counters = { snaps: 0 };
  const clips: McClip[] = [];
  let segTotal = 0, cueTotal = 0;
  spec.clips.forEach((c, ci) => {
    const lo = lowered(c);
    const worldCache = new Map<number, Record<string, M4>>();
    const worldAt = (t: number) => { let w = worldCache.get(t); if (!w) { w = worldMatrices(spec, sample(spec, c.name, lo.time(t))); worldCache.set(t, w); } return w; };
    const segments = parts.map((p, pi) => {
      const at = (t: number): McTransform => {
        const m = mul(worldAt(t)[p.node] ?? I4(), p.local);
        const r = toT(m);
        if (r.d.shear > 1e-3 && !warnings.some((w) => w.code === "shear" && w.path === `clips[${ci}]`)) warn(`clips[${ci}]`, "shear", `${p.node}: non-uniform scale under a rotation cannot be shown exactly by a display entity (approximated)`);
        return r.v;
      };
      void pi;
      return fitSegments(at, lo.length, counters);
    });
    const out: McCue[] = [];
    const rigPos = (node: string | undefined, t: number): Vec3 => {
      if (!node) return [0, 0, 0];
      const n = spec.rig.nodes.find((x) => x.name === node) as RigNode;
      const p = apply(worldAt(t)[node] ?? I4(), n.pivot);
      return [r4(p[0]), r4(p[1]), r4(p[2])];
    };
    for (const cue of cues(c, -1, lo.length - 1)) {
      const tr = c.tracks[cue.track];
      if (cue.kind === "sound") {
        const k = soundKey(cue.sound, ctx);
        if ("error" in k) err(`clips[${ci}].tracks[${cue.track}].sound`, "sound_namespace", k.error);
        else if ("dropped" in k) dropped.push({ path: `clips[${ci}].tracks[${cue.track}]`, reason: k.dropped });
        else out.push({ tick: cue.t, kind: "sound", key: k.key, gain: r4(cue.gain), pitch: r4(cue.pitch), at: rigPos(cue.node, cue.t) });
      } else if (cue.kind === "event") {
        out.push({ tick: cue.t, kind: "event", name: cue.name });
        if (cue.attach || cue.detach) dropped.push({ path: `clips[${ci}].tracks[${cue.track}]`, reason: "attaching or detaching an actor is not built for Minecraft; the event still fires" });
      } else if (cue.kind === "particle" && tr.kind === "particle") {
        const births = particleBirths(spec, c, cue.track, cue.t, (t) => worldAt(t));
        const groups = new Map<string, { tick: number; particle: McParticle; n: number; at: Vec3; spread: number; speed: number }>();
        for (const b of births) {
          if (b.birth >= lo.length && lo.loop !== "loop") continue;
          const tick = lo.loop === "loop" ? b.birth % lo.length : b.birth;
          const e = tr.emitters[b.emitter];
          const particle = mcParticleFor(e);
          if (b.directed) out.push({ tick, kind: "directed", particle, at: [r4(b.origin[0]), r4(b.origin[1]), r4(b.origin[2])], dir: [r4(b.dir[0]), r4(b.dir[1]), r4(b.dir[2])], speed: r4(b.speed / TICK_RATE) });
          else {
            const key = `${tick}:${b.emitter}`;
            const g = groups.get(key);
            const at = rigPos(tr.node, tick);
            if (g) g.n++; else groups.set(key, { tick, particle, n: 1, at, spread: r4(Math.max(0.05, (e.radius ?? 0) * 0.5)), speed: r4(((e.speed[0] + e.speed[1]) / 2) / TICK_RATE) });
          }
        }
        for (const g of groups.values()) out.push({ tick: g.tick, kind: "particle", particle: g.particle, count: g.n, at: g.at, spread: [g.spread, g.spread, g.spread], speed: g.speed });
      }
    }
    // material: brightness on parts; everything else dropped
    c.tracks.forEach((tr, ti) => {
      if (tr.kind !== "material") return;
      const pi = partIndex.get(tr.node);
      if (tr.channel !== "brightness") { dropped.push({ path: `clips[${ci}].tracks[${ti}]`, reason: `${tr.channel} cannot be animated on Minecraft display entities` }); return; }
      if (pi === undefined) { dropped.push({ path: `clips[${ci}].tracks[${ti}]`, reason: `${tr.node} has no display part to light (Minecraft has no dynamic lights)` }); return; }
      let last: number | null = null;
      for (let t = 0; t < lo.length; t++) {
        const lv = sample(spec, c.name, lo.time(t)).material[tr.node]?.brightness;
        const level = lv === undefined ? -1 : Math.max(-1, Math.min(15, Math.round(lv))) || -1;
        if (level !== last) { out.push({ tick: t, kind: "brightness", part: pi, level }); last = level; }
      }
    });
    out.sort((x, y) => x.tick - y.tick || ["sound", "particle", "directed", "brightness", "event"].indexOf(x.kind) - ["sound", "particle", "directed", "brightness", "event"].indexOf(y.kind));
    segTotal += segments.reduce((s, x) => s + x.length, 0); cueTotal += out.length;
    clips.push({ name: c.name, length: lo.length, loop: lo.loop, segments, cues: out });
  });
  const numbers = segTotal * 12 + cueTotal * 9;
  if (segTotal > MC_LOWER_LIMITS.segmentsTotal) err("clips", "lower_segments", `${segTotal} interpolation segments; the limit is ${MC_LOWER_LIMITS.segmentsTotal} (fewer keys or shorter clips)`);
  if (cueTotal > MC_LOWER_LIMITS.cuesTotal) err("clips", "lower_cues", `${cueTotal} cues; the limit is ${MC_LOWER_LIMITS.cuesTotal}`);
  if (numbers > MC_LOWER_LIMITS.numbersTotal) err("clips", "lower_size", `the program needs ${numbers} numbers; the limit is ${MC_LOWER_LIMITS.numbersTotal}`);

  // ---- machine (a spec without one gets a one-state machine playing the first clip)
  const clipIdx = new Map(spec.clips.map((c, i) => [c.name, i]));
  const m = spec.machines?.[0];
  let machine: McMachine;
  if (!m) machine = { name: "default", initial: 0, states: [{ name: spec.clips[0].name, clip: 0, after: null, onEnter: [] }], transitions: spec.clips.slice(1).map((c, i) => ({ from: -1, on: c.name, to: i + 1, minTicks: 0, guard: [] })).concat([]), vars: [] };
  else {
    const si = new Map(m.states.map((s, i) => [s.name, i]));
    const vi = new Map((m.vars ?? []).map((x, i) => [x.name, i]));
    const events = [...new Set(m.transitions.map((t) => t.on).concat(m.states.flatMap((s) => (s.onEnter ?? []).flatMap((a) => (a.do === "emit" ? [a.event] : [])))))].sort();
    const ei = new Map(events.map((e, i) => [e, i]));
    machine = {
      name: m.name, initial: si.get(m.initial) ?? 0,
      vars: (m.vars ?? []).map((x) => ({ name: x.name, init: x.init, min: x.min, max: x.max })),
      states: m.states.map((s) => {
        const clip = s.clip ? clipIdx.get(s.clip) ?? -1 : -1;
        const c = s.clip ? spec.clips.find((x) => x.name === s.clip) : undefined;
        const ticks = s.after ? s.after.ticks ?? (c && c.loop === "once" ? c.length : -1) : -1;
        return { name: s.name, clip, after: s.after && ticks >= 0 ? { to: si.get(s.after.to) ?? 0, ticks } : null, onEnter: (s.onEnter ?? []).map((a): [number, number, number] => (a.do === "set" ? [0, vi.get(a.var) ?? 0, a.value] : a.do === "add" ? [1, vi.get(a.var) ?? 0, a.by] : [2, ei.get(a.event) ?? 0, 0])) };
      }),
      transitions: m.transitions.map((t) => ({ from: t.from === "*" ? -1 : si.get(t.from) ?? -1, on: t.on, to: si.get(t.to) ?? 0, minTicks: t.minTicks ?? 0, guard: (t.guard ?? []).map((g): [number, number, number] => [vi.get(g.var) ?? 0, OPS.indexOf(g.op), g.value]) })),
    };
    // emit actions are encoded by index into the sorted event list: keep that list on the program via names
    (machine as McMachine & { events?: string[] }).events = events;
  }
  const handled = new Set(machine.transitions.map((t) => t.on));
  const tr = binding.triggers ?? {};
  for (const [k, e] of Object.entries(tr)) if (e && !handled.has(e)) warn(`minecraft.triggers.${k}`, "trigger_unhandled", `no transition listens to ${e}, so ${k} does nothing`);

  // ---- spawn pose + interaction box
  const init = machine.states[machine.initial];
  const initClip = init && init.clip >= 0 ? spec.clips[init.clip].name : null;
  const w0 = worldMatrices(spec, sample(spec, initClip, 0));
  const spawn = parts.map((p) => toT(mul(w0[p.node] ?? I4(), p.local)).v);
  let minX = 0, maxX = 0, minZ = 0, maxZ = 0, maxY = 0.25;
  parts.forEach((p) => {
    const m4 = mul(w0[p.node] ?? I4(), p.local);
    const unit = p.display === "block" ? [[0, 0, 0], [1, 1, 1]] : [[-0.5, -0.5, -0.5], [0.5, 0.5, 0.5]];
    for (const x of [0, 1]) for (const y of [0, 1]) for (const z of [0, 1]) {
      const q = apply(m4, [unit[x][0], unit[y][1], unit[z][2]]);
      minX = Math.min(minX, q[0]); maxX = Math.max(maxX, q[0]); minZ = Math.min(minZ, q[2]); maxZ = Math.max(maxZ, q[2]); maxY = Math.max(maxY, q[1]);
    }
  });
  const width = r4(Math.min(3, Math.max(0.25, 2 * Math.max(-minX, maxX, -minZ, maxZ))));
  const height = r4(Math.min(4, Math.max(0.25, maxY)));
  if (errors.length) return { ok: false, errors, warnings, dropped };
  void compose;
  return {
    ok: true, warnings, dropped,
    program: {
      id: spec.id, parts, clips, machine, spawn, interaction: { width, height },
      triggers: { rightClick: tr.rightClick ?? null, sneakRightClick: tr.sneakRightClick ?? null, leftClick: tr.leftClick ?? null },
      stats: { parts: parts.length, clips: clips.length, segments: segTotal, cues: cueTotal, snaps: counters.snaps, numbers },
    },
  };
}

/** The transformation a part shows after a clip has run `tick` ticks (the last segment that started, at its target). */
export function partTargetAt(clip: McClip, part: number, tick: number): McTransform | null {
  let v: McTransform | null = null;
  for (const s of clip.segments[part] ?? []) if (s.start <= tick) v = s.v;
  return v;
}

