// Cyrus motion on Minecraft: the MotionDesign IR, a design file like items / menus / quests (assets/designs/<id>.json,
// `"kind": "motion"`). It carries a game-neutral MotionSpec (lib/cyrus/motion) or a PRESET reference with parameters
// (the AI's cheapest, most reliable path), plus the Minecraft binding: what each part looks like (a vanilla block, a
// vanilla item, or a custom item model of this mod), which clicks on the prop raise which machine events, instance
// caps. validateMotionDesign resolves the preset, validates the spec against Minecraft's motion capability and LOWERS
// it (./lower.ts), so a design that passes is a design that compiles. Never throws.
import { z } from "zod";
import { isVanilla, missingIdReason } from "../../datapack/versions";
import { MotionSpecSchema, type MotionSpec } from "../../motion/spec";
import type { Dropped } from "../../motion/adapter";
import { MOTION_PRESETS, presetById } from "../../motion/presets";
import { Key, NsRef, Text, VanillaRef, type DzIssue } from "../spec";
import { lowerMinecraft, type McProgram } from "./lower";

export const MOTION_DESIGN_VERSION = 1;
export const MOTION_DESIGN_LIMITS = { maxMotions: 4, maxSpecBytes: 64 * 1024, instances: [1, 16] as const, viewRange: [0.1, 2] as const, pluginInstances: 16 } as const;

const PartBinding = z.union([
  z.strictObject({ block: VanillaRef }),
  z.strictObject({ item: VanillaRef, model: NsRef.optional() }),
]);
const EventName = z.string().regex(/^[a-z][a-z0-9_]{1,31}$/);
export const MotionDesignSchema = z.strictObject({
  schemaVersion: z.literal(MOTION_DESIGN_VERSION),
  kind: z.literal("motion"),
  /** file name and command id (`/<mod> motion spawn <id>`) */
  id: Key,
  title: Text(40).optional(),
  /** a full MotionSpec, or a preset of the motion library with parameters */
  motion: z.union([z.strictObject({ preset: z.string().regex(/^(motion|effect|gen):[a-z][a-z0-9_]{1,40}$/), params: z.record(z.string().regex(/^[a-z][a-zA-Z0-9_]{0,31}$/), z.union([z.number(), z.string().max(100)])).optional() }), z.unknown()]),
  minecraft: z.strictObject({
    /** look of a rig node: a vanilla block, or a vanilla item (optionally replaced by this mod's item model). Unbound visible nodes use their proxy box as a coloured block. */
    parts: z.record(z.string().regex(/^[a-z][a-z0-9_]{0,23}$/), PartBinding).optional(),
    /** which clicks on the prop raise which events (machine-less specs: right-click plays the first clip) */
    triggers: z.strictObject({ rightClick: EventName.optional(), sneakRightClick: EventName.optional(), leftClick: EventName.optional() }).optional(),
    /** live props of this motion at once (config motions.<id>.max_instances clamps to the same range) */
    maxInstances: z.number().int().min(MOTION_DESIGN_LIMITS.instances[0]).max(MOTION_DESIGN_LIMITS.instances[1]).optional(),
    viewRange: z.number().min(MOTION_DESIGN_LIMITS.viewRange[0]).max(MOTION_DESIGN_LIMITS.viewRange[1]).optional(),
