export function resolveMotion(d: MotionDesign): { spec: MotionSpec | null; errors: DzIssue[]; warnings: DzIssue[] } {
  const m = d.motion as { preset?: unknown; params?: Record<string, unknown> } | unknown;
  if (m && typeof m === "object" && typeof (m as { preset?: unknown }).preset === "string") {
    const id = (m as { preset: string }).preset;
    const p = presetById(id);
    if (!p) return { spec: null, errors: [{ path: "motion.preset", code: "unknown_preset", message: `no motion preset ${id}; use one of ${MOTION_PRESETS.map((x) => x.id).join(", ")}` }], warnings: [] };
    const b = p.build((m as { params?: Record<string, unknown> }).params ?? {});
    return { spec: { ...b.spec, id: d.id }, errors: [], warnings: b.issues.map((i) => ({ path: `motion.params.${i.param}`, code: "param_clamped", message: i.message })) };
  }
  const s = MotionSpecSchema.safeParse(m);
  if (!s.success) return { spec: null, errors: s.error.issues.slice(0, 20).map((i) => ({ path: `motion.${issuePath(i.path)}`.replace(/\.$/, ""), code: "schema", message: i.message })), warnings: [] };
  if (s.data.id !== d.id) return { spec: null, errors: [{ path: "motion.id", code: "id_mismatch", message: `motion.id "${s.data.id}" must equal the design id "${d.id}"` }], warnings: [] };
