// Cyrus motion on Minecraft: the verified Java components (rendered into a mod's package like ../components): the
// runtime hub (Motions) and the program base (MotionDef). The runtime implements EXACTLY the motion core's machine rules
// (lib/cyrus/motion/machine.ts) and plays the lowered program (./lower.ts): interpolation segments on display entities,
// sound / particle / brightness / event cues, all on the Paper main thread (one 1-tick timer), all entities
// non-persistent and tagged, capped per motion and plugin-wide. No commands are dispatched, nothing is reflected.
export const MOTION_DEF_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.List;
import org.bukkit.Particle;
import org.bukkit.block.data.BlockData;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;

/**
 * Component motion-def v1: one lowered motion program (lib/cyrus/designer/motion/lower.ts). Generated subclasses fill
 * the arrays; the bulky numbers (segments, cues, poses) arrive as compact space-separated text parsed once on enable.
 * Cue kinds: 0 sound, 1 particle burst, 2 directed particle, 3 brightness, 4 event. Loop: 0 once, 1 hold, 2 loop.
 */
public abstract class MotionDef {
    public final String id;
    public final String title;
    public BlockData[] blocks;
    public ItemStack[] items;
    public float[][] spawn;
    public float[][] rest;
    public float width;
    public float height;
    public String[] clipNames;
    public int[] clipLength;
    public int[] clipLoop;
    public int[][][] segStart;
    public int[][][] segDur;
    public float[][][] segVal;
    public int[][] cueTick;
    public int[][] cueKind;
    public int[][] cueRef;
    public float[][] cueNum;
    public String[] sounds;
    public Particle[] particles;
    public String[] states;
    public int[] stateClip;
    public int[] afterTo;
    public int[] afterTicks;
    public int[][] onEnter;
    public int[] tFrom;
    public int[] tOn;
    public int[] tTo;
    public int[] tMin;
    public int[][] tGuard;
    public String[] vars;
    public int[] varInit;
    public int[] varMin;
    public int[] varMax;
    public String[] events;
    public int initial;
    public String rightClick;
    public String sneakRightClick;
    public String leftClick;
    public int defaultMax = 4;
    public float defaultView = 1.0f;
    public boolean snap = true;

    protected MotionDef(String id, String title) {
        this.id = id;
        this.title = title;
    }

    public final int parts() { return blocks.length; }

    public final int segments() {
        int n = 0;
        for (int[][] c : segStart) for (int[] p : c) n += p.length;
        return n;
    }

    public final int cues() {
        int n = 0;
        for (int[] c : cueTick) n += c.length;
        return n;
    }

    /** Numbers from space-separated text chunks (generated; never user input). */
    protected static float[] floats(String... chunks) {
        List<Float> out = new ArrayList<>();
        for (String c : chunks) for (String t : c.trim().split(" ")) if (!t.isEmpty()) out.add(Float.parseFloat(t));
        float[] a = new float[out.size()];
        for (int i = 0; i < a.length; i++) a[i] = out.get(i);
        return a;
    }

    protected static int[] ints(String... chunks) {
        float[] f = floats(chunks);
        int[] a = new int[f.length];
        for (int i = 0; i < a.length; i++) a[i] = Math.round(f[i]);
        return a;
    }

    /** Split a flat array into rows of n. */
    protected static float[][] rows(float[] flat, int n) {
        float[][] out = new float[flat.length / n][];
        for (int i = 0; i < out.length; i++) { out[i] = new float[n]; System.arraycopy(flat, i * n, out[i], 0, n); }
        return out;
    }

    protected static int[][] triples(int... flat) {
        int[][] out = new int[flat.length / 3][];
        for (int i = 0; i < out.length; i++) out[i] = new int[] { flat[i * 3], flat[i * 3 + 1], flat[i * 3 + 2] };
        return out;
    }

    /** Segments of one clip + part: "start dur v0..v9 ..." -> starts, durations, values. */
    protected final void segs(int clip, int part, String... chunks) {
        float[] f = floats(chunks);
        int n = f.length / 12;
        segStart[clip][part] = new int[n];
        segDur[clip][part] = new int[n];
        segVal[clip][part] = new float[n * 10];
        for (int i = 0; i < n; i++) {
            segStart[clip][part][i] = Math.round(f[i * 12]);
            segDur[clip][part][i] = Math.round(f[i * 12 + 1]);
            System.arraycopy(f, i * 12 + 2, segVal[clip][part], i * 10, 10);
        }
    }

    /** Cues of one clip: "tick kind ref n0..n7 ..." (sorted by tick). */
    protected final void cueList(int clip, String... chunks) {
        float[] f = floats(chunks);
        int n = f.length / 11;
        cueTick[clip] = new int[n];
        cueKind[clip] = new int[n];
        cueRef[clip] = new int[n];
        cueNum[clip] = new float[n * 8];
        for (int i = 0; i < n; i++) {
            cueTick[clip][i] = Math.round(f[i * 11]);
            cueKind[clip][i] = Math.round(f[i * 11 + 1]);
            cueRef[clip][i] = Math.round(f[i * 11 + 2]);
            System.arraycopy(f, i * 11 + 3, cueNum[clip], i * 8, 8);
        }
    }

    protected final void clips(int count) {
        segStart = new int[count][][];
        segDur = new int[count][][];
        segVal = new float[count][][];
        cueTick = new int[count][];
        cueKind = new int[count][];
        cueRef = new int[count][];
        cueNum = new float[count][];
        for (int c = 0; c < count; c++) {
            segStart[c] = new int[blocks.length][];
            segDur[c] = new int[blocks.length][];
            segVal[c] = new float[blocks.length][];
        }
    }

    /** An item for an item_display part, optionally showing this mod's item model (1.21.4+, see Compat). */
    protected static ItemStack item(ItemStack stack, String namespace, String model) {
        if (model == null) return stack;
        ItemMeta meta = stack.getItemMeta();
        if (meta == null) return stack;
        Compat.itemModel(meta, namespace, model);
        stack.setItemMeta(meta);
        return stack;
    }
}
`;

export const MOTIONS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.SoundCategory;
import org.bukkit.World;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.PluginCommand;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.BlockDisplay;
import org.bukkit.entity.Display;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Interaction;
import org.bukkit.entity.ItemDisplay;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.HandlerList;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.player.PlayerInteractEntityEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;
import org.bukkit.util.Transformation;
import org.joml.Quaternionf;
import org.joml.Vector3f;

/**
 * Component motion-runtime v1: plays lowered motion programs (MotionDef) on display entities. One instance = one display
 * entity per part + one interaction entity for clicks, all non-persistent (gone on restart / chunk unload) and tagged
 * <ns>.motion, <ns>.motion.<id>, <ns>.mi<n>, <ns>.mi<n>p<part>. A single 1-tick main-thread timer steps every instance:
 * the state machine first (same rules as lib/cyrus/motion/machine.ts: after, then inputs in order, then emitted events;
 * at most 8 transitions per tick), then the clip frame (segments starting this tick, cues of this tick).
 * Caps: config motions.<id>.max_instances (1..16) per motion, 16 live instances plugin-wide.
 * Commands (wrapped around the mod command): /<mod> motion list | spawn <id> [world x y z [yaw]] | event <#|id|all> <event>
 *   | state [#] | despawn <#|id|all> | check <id> | debug on|off.  Permissions <ns>.motion (spawn/event/despawn/debug,
 *   op), <ns>.command (list/state/check, op), <ns>.motion.use (click a prop, everyone).
 */
public final class Motions implements Listener {
    public static final int MAX_LIVE = 16;
    public static final int MAX_TRANSITIONS_PER_TICK = 8;
    private static final int CLICK_COOLDOWN_TICKS = 4;

    private final JavaPlugin plugin;
    private final String ns;
    private final Map<String, MotionDef> defs = new LinkedHashMap<>();
    private final List<Inst> live = new ArrayList<>();
    private final Map<UUID, Long> lastClick = new HashMap<>();
    private BukkitTask task;
    private int seq;
    private long now;
    private boolean debug;

    private final class Inst {
        final int n;
        final MotionDef d;
        final Location origin;
        final float yaw;
        final Display[] parts;
        final Interaction hit;
        final long born;
        final int[] vars;
        final ArrayDeque<String> inbox = new ArrayDeque<>();
        int state = -1;
        long enteredAt;
        int clip = -1;
        long clipStart;
        int[] segIdx;
        int cueIdx;
        boolean started;

        Inst(int n, MotionDef d, Location origin, float yaw, Display[] parts, Interaction hit) {
            this.n = n; this.d = d; this.origin = origin; this.yaw = yaw; this.parts = parts; this.hit = hit; this.born = now;
            this.vars = new int[d.vars.length];
            for (int i = 0; i < vars.length; i++) vars[i] = Math.max(d.varMin[i], Math.min(d.varMax[i], d.varInit[i]));
            this.segIdx = new int[parts.length];
        }

        boolean valid() {
            if (hit != null && !hit.isValid()) return false;
            for (Display p : parts) if (p == null || !p.isValid()) return false;
            return true;
        }

        void remove() {
            for (Display p : parts) if (p != null) p.remove();
            if (hit != null) hit.remove();
        }
    }

    public Motions(JavaPlugin plugin, String namespace, List<MotionDef> list) {
        this.plugin = plugin;
        this.ns = namespace;
        for (MotionDef d : list) defs.put(d.id, d);
    }

    public void enable(PluginCommand command) {
        plugin.getServer().getPluginManager().registerEvents(this, plugin);
        if (command != null) {
            CommandExecutor prev = command.getExecutor();
            TabCompleter prevTab = command.getTabCompleter();
            command.setExecutor((s, c, l, a) -> {
                if (a.length > 0 && a[0].equalsIgnoreCase("motion")) { command(s, l, a); return true; }
                return prev != null && prev.onCommand(s, c, l, a);
            });
            command.setTabCompleter((s, c, l, a) -> {
                if (a.length == 1) {
                    List<String> out = new ArrayList<>(prevTab == null ? List.of() : prevTab.onTabComplete(s, c, l, a));
                    if ("motion".startsWith(a[0].toLowerCase(Locale.ROOT))) out.add("motion");
                    return out;
                }
                if (a.length == 2 && a[0].equalsIgnoreCase("motion")) return filter(List.of("list", "spawn", "event", "state", "despawn", "check", "debug"), a[1]);
                if (a.length == 3 && a[0].equalsIgnoreCase("motion") && (a[1].equalsIgnoreCase("spawn") || a[1].equalsIgnoreCase("check"))) return filter(new ArrayList<>(defs.keySet()), a[2]);
                return prevTab == null ? List.of() : prevTab.onTabComplete(s, c, l, a);
            });
        }
        task = plugin.getServer().getScheduler().runTaskTimer(plugin, this::tick, 1L, 1L);
        plugin.getLogger().info("Motion ready: " + (defs.isEmpty() ? "-" : String.join(", ", defs.keySet())));
    }

    public void disable() {
        if (task != null) task.cancel();
        task = null;
        for (Inst i : live) i.remove();
        live.clear();
        lastClick.clear();
        HandlerList.unregisterAll(this);
    }

    private static List<String> filter(List<String> all, String prefix) {
        List<String> out = new ArrayList<>();
        for (String s : all) if (s.startsWith(prefix.toLowerCase(Locale.ROOT))) out.add(s);
        return out;
    }

    private static void say(CommandSender s, String text, NamedTextColor color) { s.sendMessage(Component.text(text, color)); }

    private void log(String line) { if (debug) plugin.getLogger().info("[motion] " + line); }

    // ------------------------------------------------------------------------------------------------- settings
    private int maxInstances(MotionDef d) {
        int v = plugin.getConfig().getInt("motions." + d.id + ".max_instances", d.defaultMax);
        return Math.max(1, Math.min(16, v));
    }

    private float viewRange(MotionDef d) {
        double v = plugin.getConfig().getDouble("motions." + d.id + ".view_range", d.defaultView);
        return (float) Math.max(0.1, Math.min(2.0, v));
    }

    private float volume(MotionDef d) {
        double v = plugin.getConfig().getDouble("motions." + d.id + ".volume", 1.0);
        return (float) Math.max(0.0, Math.min(2.0, v));
    }

    // -------------------------------------------------------------------------------------------------- spawning
    private Transformation transform(float[] v, int o) {
        return new Transformation(new Vector3f(v[o], v[o + 1], v[o + 2]), new Quaternionf(v[o + 3], v[o + 4], v[o + 5], v[o + 6]), new Vector3f(v[o + 7], v[o + 8], v[o + 9]), new Quaternionf());
    }

    private String tag(int n) { return ns + ".mi" + n; }

    /** Spawn a prop; returns null (and says why) when a cap is reached. */
    public Inst spawn(MotionDef d, Location at, float yaw, CommandSender who) {
        if (live.size() >= MAX_LIVE) { say(who, "Too many motion props are live (" + MAX_LIVE + "); despawn some first.", NamedTextColor.RED); return null; }
        int mine = 0;
        for (Inst i : live) if (i.d == d) mine++;
        if (mine >= maxInstances(d)) { say(who, d.id + " already has " + mine + " live props (motions." + d.id + ".max_instances)", NamedTextColor.RED); return null; }
        World w = at.getWorld();
        if (w == null) return null;
        Location o = at.clone();
        float y = yaw;
        if (d.snap) {
            o = new Location(w, Math.floor(at.getX()) + 0.5, Math.floor(at.getY()), Math.floor(at.getZ()) + 0.5);
            y = Math.round(yaw / 90.0f) * 90.0f;
        }
        o.setYaw(y);
        o.setPitch(0f);
        final int n = ++seq;
        final float range = viewRange(d);
        Display[] parts = new Display[d.parts()];
        for (int p = 0; p < parts.length; p++) {
            final int part = p;
            final float[] pose = d.spawn[p];
            java.util.function.Consumer<Display> setup = e -> {
                e.setPersistent(false);
                e.addScoreboardTag(ns + ".motion");
                e.addScoreboardTag(ns + ".motion." + d.id);
                e.addScoreboardTag(tag(n));
                e.addScoreboardTag(tag(n) + "p" + part);
                e.setInterpolationDelay(0);
                e.setInterpolationDuration(0);
                e.setTeleportDuration(0);
                e.setShadowRadius(0f);
                e.setShadowStrength(0f);
                e.setViewRange(range);
                e.setTransformation(transform(pose, 0));
            };
            if (d.blocks[p] != null) {
                final org.bukkit.block.data.BlockData bd = d.blocks[p];
                parts[p] = w.spawn(o, BlockDisplay.class, e -> { e.setBlock(bd); setup.accept(e); });
            } else {
                final org.bukkit.inventory.ItemStack st = d.items[p];
                parts[p] = w.spawn(o, ItemDisplay.class, e -> { e.setItemStack(st); setup.accept(e); });
            }
        }
        Interaction hit = w.spawn(o, Interaction.class, e -> {
            e.setPersistent(false);
            e.addScoreboardTag(ns + ".motion");
            e.addScoreboardTag(ns + ".motion." + d.id);
            e.addScoreboardTag(tag(n));
            e.setInteractionWidth(d.width);
            e.setInteractionHeight(d.height);
            e.setResponsive(true);
        });
        Inst inst = new Inst(n, d, o, y, parts, hit);
        live.add(inst);
        log("#" + n + " " + d.id + " spawned at " + w.getName() + " " + fmt(o.getX()) + " " + fmt(o.getY()) + " " + fmt(o.getZ()) + " yaw " + fmt(y));
        return inst;
    }

    private static String fmt(double v) {
        double r = Math.round(v * 10000.0) / 10000.0;
        if (r == Math.rint(r)) return Long.toString((long) r);
        return Double.toString(r);
    }

    // -------------------------------------------------------------------------------------------------- machine
    private boolean guard(Inst i, int t) {
        for (int[] g : i.d.tGuard[t]) {
            int v = i.vars[g[0]];
            boolean ok;
            switch (g[1]) {
                case 0 -> ok = v < g[2];
                case 1 -> ok = v <= g[2];
                case 2 -> ok = v == g[2];
                case 3 -> ok = v != g[2];
                case 4 -> ok = v >= g[2];
                default -> ok = v > g[2];
            }
            if (!ok) return false;
        }
        return true;
    }

    private void enter(Inst i, int to, String via, List<String> emits) {
        MotionDef d = i.d;
        String from = i.state < 0 ? "-" : d.states[i.state];
        i.state = to;
        i.enteredAt = now;
        i.started = true;
        startClip(i, d.stateClip[to]);
        for (int[] a : d.onEnter[to]) {
            if (a[0] == 2) { emits.add(d.events[a[1]]); continue; }
            int next = a[0] == 0 ? a[2] : i.vars[a[1]] + a[2];
            i.vars[a[1]] = Math.max(d.varMin[a[1]], Math.min(d.varMax[a[1]], next));
        }
        log("#" + i.n + " t" + (now - i.born) + " " + from + "->" + d.states[to] + " (" + via + ")" + varsText(i));
    }

    private String varsText(Inst i) {
        if (i.vars.length == 0) return "";
        StringBuilder b = new StringBuilder();
        for (int k = 0; k < i.vars.length; k++) b.append(' ').append(i.d.vars[k]).append('=').append(i.vars[k]);
        return b.toString();
    }

    private void stepMachine(Inst i) {
        MotionDef d = i.d;
        List<String> emits = new ArrayList<>();
        int n = 0;
        if (!i.started) enter(i, d.initial, "initial", emits);
        while (true) {
            int at = d.afterTicks[i.state];
            if (at < 0 || now - i.enteredAt < at) break;
            if (n >= MAX_TRANSITIONS_PER_TICK) { log("#" + i.n + " cut: more than " + MAX_TRANSITIONS_PER_TICK + " transitions in one tick"); break; }
            enter(i, d.afterTo[i.state], "after", emits);
            n++;
            if (at > 0) break;
        }
        List<String> events = new ArrayList<>(i.inbox);
        i.inbox.clear();
        for (int k = 0; k < events.size() + emits.size(); k++) {
            String ev = k < events.size() ? events.get(k) : emits.get(k - events.size());
            long st = now - i.enteredAt;
            int found = -1;
            for (int t = 0; t < d.tFrom.length; t++) {
                if ((d.tFrom[t] == i.state || d.tFrom[t] == -1) && d.events[d.tOn[t]].equals(ev) && guard(i, t) && st >= d.tMin[t]) { found = t; break; }
            }
            if (found < 0) { log("#" + i.n + " t" + (now - i.born) + " ignored " + ev + " in " + d.states[i.state]); continue; }
            if (n >= MAX_TRANSITIONS_PER_TICK) { log("#" + i.n + " cut: more than " + MAX_TRANSITIONS_PER_TICK + " transitions in one tick"); break; }
            enter(i, d.tTo[found], ev, emits);
            n++;
        }
    }

    private void startClip(Inst i, int clip) {
        i.clip = clip;
        i.clipStart = now;
        i.segIdx = new int[i.parts.length];
        i.cueIdx = 0;
        if (clip < 0) for (int p = 0; p < i.parts.length; p++) apply(i.parts[p], i.d.rest[p], 0, 3);
    }

    private void apply(Display e, float[] v, int o, int dur) {
        e.setInterpolationDelay(0);
        e.setInterpolationDuration(dur);
        e.setTransformation(transform(v, o));
    }

    // ---------------------------------------------------------------------------------------------------- frames
    private Location at(Inst i, float x, float y, float z) {
        double r = Math.toRadians(i.yaw), c = Math.cos(r), s = Math.sin(r);
        return i.origin.clone().add(x * c - z * s, y, x * s + z * c);
    }

    private void frame(Inst i) {
        int c = i.clip;
        if (c < 0) return;
        MotionDef d = i.d;
        long l = now - i.clipStart;
        int len = d.clipLength[c];
        long lt;
        if (d.clipLoop[c] == 2) {
            lt = l % len;
            if (lt == 0 && l > 0) { i.segIdx = new int[i.parts.length]; i.cueIdx = 0; }
        } else {
            if (l >= len) return;
            lt = l;
        }
        for (int p = 0; p < i.parts.length; p++) {
            int[] st = d.segStart[c][p];
            while (i.segIdx[p] < st.length && st[i.segIdx[p]] <= lt) {
                int k = i.segIdx[p]++;
                if (st[k] == lt) apply(i.parts[p], d.segVal[c][p], k * 10, d.segDur[c][p][k]);
            }
        }
        int[] ticks = d.cueTick[c];
        while (i.cueIdx < ticks.length && ticks[i.cueIdx] <= lt) {
            int k = i.cueIdx++;
            if (ticks[k] == lt) cue(i, c, k);
        }
    }

    private void cue(Inst i, int c, int k) {
        MotionDef d = i.d;
        float[] v = d.cueNum[c];
        int o = k * 8;
        int ref = d.cueRef[c][k];
        World w = i.origin.getWorld();
        switch (d.cueKind[c][k]) {
            case 0 -> {
                Location loc = at(i, v[o], v[o + 1], v[o + 2]);
                w.playSound(loc, d.sounds[ref], SoundCategory.BLOCKS, v[o + 3] * volume(d), v[o + 4]);
                log("#" + i.n + " t" + (now - i.born) + " sound " + d.sounds[ref]);
            }
            case 1 -> {
                Location loc = at(i, v[o], v[o + 1], v[o + 2]);
                int count = Math.max(1, Math.min(64, Math.round(v[o + 7])));
                w.spawnParticle(d.particles[ref], loc, count, v[o + 3], v[o + 4], v[o + 5], v[o + 6]);
                log("#" + i.n + " t" + (now - i.born) + " particle " + d.particles[ref].name().toLowerCase(Locale.ROOT) + " x" + count);
            }
            case 2 -> {
                Location loc = at(i, v[o], v[o + 1], v[o + 2]);
                double r = Math.toRadians(i.yaw), cs = Math.cos(r), sn = Math.sin(r);
                double dx = v[o + 3] * cs - v[o + 5] * sn, dz = v[o + 3] * sn + v[o + 5] * cs;
                w.spawnParticle(d.particles[ref], loc, 0, dx, v[o + 4], dz, v[o + 6]);
            }
            case 3 -> {
                int level = Math.round(v[o]);
                Display e = i.parts[ref];
                e.setBrightness(level < 0 ? null : new Display.Brightness(level, level));
                log("#" + i.n + " t" + (now - i.born) + " brightness p" + ref + " " + level);
            }
            default -> log("#" + i.n + " t" + (now - i.born) + " event " + d.events[ref]);
        }
    }

    private void tick() {
        now++;
        for (int k = live.size() - 1; k >= 0; k--) {
            Inst i = live.get(k);
            if (!i.valid()) { i.remove(); live.remove(k); log("#" + i.n + " removed (unloaded or killed)"); continue; }
            stepMachine(i);
            frame(i);
        }
    }

    // ---------------------------------------------------------------------------------------------------- clicks
    private Inst byHit(Entity e) {
        if (!(e instanceof Interaction)) return null;
        for (Inst i : live) if (i.hit != null && i.hit.getUniqueId().equals(e.getUniqueId())) return i;
        return null;
    }

    private boolean click(Player p, Inst i, String ev) {
        if (ev == null || !p.hasPermission(ns + ".motion.use")) return false;
        Long last = lastClick.get(p.getUniqueId());
        if (last != null && now - last < CLICK_COOLDOWN_TICKS) return true;
        lastClick.put(p.getUniqueId(), now);
        i.inbox.add(ev);
        return true;
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onInteract(PlayerInteractEntityEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        Inst i = byHit(e.getRightClicked());
        if (i == null) return;
        String ev = e.getPlayer().isSneaking() && i.d.sneakRightClick != null ? i.d.sneakRightClick : i.d.rightClick;
        if (click(e.getPlayer(), i, ev)) e.setCancelled(true);
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onHit(EntityDamageByEntityEvent e) {
        Inst i = byHit(e.getEntity());
        if (i == null) return;
        e.setCancelled(true);
        if (e.getDamager() instanceof Player p) click(p, i, i.d.leftClick);
    }

    // -------------------------------------------------------------------------------------------------- commands
    private boolean allowed(CommandSender s, String node) {
        if (s.hasPermission(ns + "." + node)) return true;
        say(s, "You don't have permission for that.", NamedTextColor.RED);
        return false;
    }

    private List<Inst> select(String what) {
        List<Inst> out = new ArrayList<>();
        for (Inst i : live) {
            if (what.equalsIgnoreCase("all") || what.equals("#" + i.n) || what.equals(Integer.toString(i.n)) || what.equalsIgnoreCase(i.d.id)) out.add(i);
        }
        return out;
    }

    private String partText(Display e) {
        Transformation t = e.getTransformation();
        Vector3f tr = t.getTranslation(), sc = t.getScale();
        Quaternionf q = t.getLeftRotation();
        return "t " + fmt(tr.x) + "," + fmt(tr.y) + "," + fmt(tr.z) + " q " + fmt(q.x) + "," + fmt(q.y) + "," + fmt(q.z) + "," + fmt(q.w) + " s " + fmt(sc.x) + "," + fmt(sc.y) + "," + fmt(sc.z) + " i" + e.getInterpolationDuration();
    }

    private void command(CommandSender s, String label, String[] a) {
        String sub = a.length > 1 ? a[1].toLowerCase(Locale.ROOT) : "list";
        switch (sub) {
            case "list" -> {
                if (!allowed(s, "command")) return;
                for (MotionDef d : defs.values()) {
                    int mine = 0;
                    for (Inst i : live) if (i.d == d) mine++;
                    say(s, d.id + ": " + d.title + " parts=" + d.parts() + " clips=" + d.clipNames.length + " states=" + d.states.length + " live=" + mine + "/" + maxInstances(d), NamedTextColor.AQUA);
                }
                if (defs.isEmpty()) say(s, "No motions.", NamedTextColor.GRAY);
            }
            case "check" -> {
                if (!allowed(s, "command")) return;
                MotionDef d = a.length > 2 ? defs.get(a[2].toLowerCase(Locale.ROOT)) : null;
                if (d == null) { say(s, "Usage: /" + label + " motion check <id>", NamedTextColor.RED); return; }
                say(s, d.id + " program: parts=" + d.parts() + " clips=" + d.clipNames.length + " segments=" + d.segments() + " cues=" + d.cues() + " states=" + d.states.length + " transitions=" + d.tFrom.length + " events=" + String.join(",", d.events) + " box=" + fmt(d.width) + "x" + fmt(d.height), NamedTextColor.AQUA);
            }
            case "spawn" -> {
                if (!allowed(s, "motion")) return;
                MotionDef d = a.length > 2 ? defs.get(a[2].toLowerCase(Locale.ROOT)) : null;
                if (d == null) { say(s, "Usage: /" + label + " motion spawn <id> [world x y z [yaw]]", NamedTextColor.RED); return; }
                Location at;
                float yaw;
                if (a.length >= 7) {
                    World w = plugin.getServer().getWorld(a[3]);
                    if (w == null) { say(s, "Unknown world " + a[3], NamedTextColor.RED); return; }
                    try {
                        at = new Location(w, Double.parseDouble(a[4]), Double.parseDouble(a[5]), Double.parseDouble(a[6]));
                        yaw = a.length >= 8 ? Float.parseFloat(a[7]) : 0f;
                    } catch (NumberFormatException ex) { say(s, "Coordinates must be numbers", NamedTextColor.RED); return; }
                    if (Math.abs(at.getX()) > 30000000 || Math.abs(at.getZ()) > 30000000 || Math.abs(at.getY()) > 4096) { say(s, "Coordinates out of range", NamedTextColor.RED); return; }
                } else if (s instanceof Player p) {
                    at = p.getLocation();
                    yaw = p.getLocation().getYaw() + 180f;
                } else { say(s, "Usage from the console: /" + label + " motion spawn <id> <world> <x> <y> <z> [yaw]", NamedTextColor.RED); return; }
                Inst i = spawn(d, at, yaw, s);
                if (i != null) say(s, "Spawned " + d.id + " #" + i.n + " at " + i.origin.getWorld().getName() + " " + fmt(i.origin.getX()) + " " + fmt(i.origin.getY()) + " " + fmt(i.origin.getZ()) + " yaw " + fmt(i.yaw) + " (" + i.parts.length + " parts, tag " + tag(i.n) + ")", NamedTextColor.GREEN);
            }
            case "event" -> {
                if (!allowed(s, "motion")) return;
                if (a.length < 4) { say(s, "Usage: /" + label + " motion event <#|id|all> <event>", NamedTextColor.RED); return; }
                List<Inst> sel = select(a[2]);
                String ev = a[3].toLowerCase(Locale.ROOT);
                for (Inst i : sel) i.inbox.add(ev);
                say(s, sel.isEmpty() ? "No live prop matches " + a[2] : "Queued " + ev + " for " + sel.size() + " prop" + (sel.size() == 1 ? "" : "s"), sel.isEmpty() ? NamedTextColor.RED : NamedTextColor.GREEN);
            }
            case "state" -> {
                if (!allowed(s, "command")) return;
                List<Inst> sel = a.length > 2 ? select(a[2]) : live;
                if (sel.isEmpty()) { say(s, "No live props.", NamedTextColor.GRAY); return; }
                for (Inst i : sel) {
                    say(s, "#" + i.n + " " + i.d.id + " state=" + (i.state < 0 ? "-" : i.d.states[i.state]) + " clip=" + (i.clip < 0 ? "-" : i.d.clipNames[i.clip]) + " age=" + (now - i.born) + varsText(i), NamedTextColor.AQUA);
                    for (int p = 0; p < i.parts.length; p++) say(s, "  p" + p + " " + partText(i.parts[p]), NamedTextColor.GRAY);
                }
            }
            case "despawn" -> {
                if (!allowed(s, "motion")) return;
                List<Inst> sel = select(a.length > 2 ? a[2] : "all");
                for (Inst i : sel) { i.remove(); live.remove(i); }
                say(s, "Removed " + sel.size() + " prop" + (sel.size() == 1 ? "" : "s"), NamedTextColor.GREEN);
            }
            case "debug" -> {
                if (!allowed(s, "motion")) return;
                debug = a.length > 2 && a[2].equalsIgnoreCase("on");
                say(s, "Motion debug log " + (debug ? "on" : "off"), NamedTextColor.GREEN);
            }
            default -> say(s, "Usage: /" + label + " motion list|spawn|event|state|despawn|check|debug", NamedTextColor.RED);
        }
    }
}
`;

