// Cyrus motion on Minecraft: the COMPILER. A validated MotionDesign's lowered program (./lower.ts) becomes one
// generated data class (motions/<Id>Motion.java extends designer.MotionDef); the mod gets the two runtime components
// (designer/MotionDef.java, designer/Motions.java), a main-class hook, `motions.<id>.*` settings in config.yml, the
// <ns>.motion / <ns>.motion.use permissions and a README section. attachMotions() adds all of that to a compiled mod
// (the gameplay compiler's result), so the rest of the designer pipeline is untouched. Deterministic (golden tested).
import { MATERIAL, camel, jstr, sha256, type CompiledFile } from "../compile";
import type { DzIssue } from "../spec";
import { renderComponent } from "../components";
import { MOTIONS_JAVA, MOTION_DEF_JAVA } from "./java";
import type { McCue, McProgram } from "./lower";
import type { MotionDesign } from "./spec";
import { createHash } from "node:crypto";

export const MOTION_COMPILER_VERSION = "cyrus-motion-compile-1";
export const MOTION_LIBRARY_VERSION = "cyrus-motion-components-1";
export const MOTION_COMPONENTS = [
  { id: "motion-def", file: "designer/MotionDef.java", purpose: "a lowered motion program (parts, segments, cues, state machine)", source: MOTION_DEF_JAVA },
  { id: "motion-runtime", file: "designer/Motions.java", purpose: "plays motion programs on display entities: machine, segments, cues, clicks, caps, commands", source: MOTIONS_JAVA },
] as const;
export const motionLibraryHash = () => { const h = createHash("sha256"); h.update(MOTION_LIBRARY_VERSION); for (const c of MOTION_COMPONENTS) { h.update(c.id); h.update(c.source); } return h.digest("hex"); };

export type CheckedMotion = { design: MotionDesign; program: McProgram; specSha256: string };

const n4 = (v: number) => { const x = Math.round(v * 10000) / 10000; return String(Object.is(x, -0) ? 0 : x); };
/** Space-separated numbers in chunks (each chunk is its own Java string constant, far below the 65535-byte limit). */
function chunks(nums: number[]): string {
  const out: string[] = [];
  let cur = "";
  for (const v of nums) { const t = n4(v); if (cur.length + t.length + 1 > 20000) { out.push(cur); cur = ""; } cur += (cur ? " " : "") + t; }
  out.push(cur);
  return out.map(jstr).join(", ");
}
const KIND: Record<McCue["kind"], number> = { sound: 0, particle: 1, directed: 2, brightness: 3, event: 4 };
const PARTICLE_CONST = (p: string) => `Particle.${p.toUpperCase()}`;

export const motionClassName = (id: string) => `${camel(id)}Motion`;

/** The generated data class of one motion. */
export function motionClass(pkg: string, ns: string, design: MotionDesign, p: McProgram, specSha: string): string {
  const cls = motionClassName(design.id);
  const sounds: string[] = [], particles: string[] = [];
  const idx = (list: string[], v: string) => { let i = list.indexOf(v); if (i < 0) { list.push(v); i = list.length - 1; } return i; };
  const clipEvents = p.clips.flatMap((c) => c.cues.flatMap((q) => (q.kind === "event" ? [q.name] : [])));
  const events = [...new Set([...p.machine.events, ...clipEvents])].sort();
  const ev = (name: string) => events.indexOf(name);
  const cueNums = (q: McCue): number[] => {
    switch (q.kind) {
      case "sound": return [q.tick, KIND.sound, idx(sounds, q.key), ...q.at, q.gain, q.pitch, 0, 0, 0];
      case "particle": return [q.tick, KIND.particle, idx(particles, q.particle), ...q.at, ...q.spread, q.speed, q.count];
      case "directed": return [q.tick, KIND.directed, idx(particles, q.particle), ...q.at, ...q.dir, q.speed, 0];
      case "brightness": return [q.tick, KIND.brightness, q.part, q.level, 0, 0, 0, 0, 0, 0, 0];
      default: return [q.tick, KIND.event, ev(q.name), 0, 0, 0, 0, 0, 0, 0, 0];
    }
  };
  const body: string[] = [];
  const L = (s: string) => body.push(`        ${s}`);
  L(`super(${jstr(design.id)}, ${jstr(design.title ?? p.id.replace(/_/g, " "))});`);
  L(`blocks = new BlockData[] { ${p.parts.map((x) => (x.display === "block" ? `${MATERIAL(x.material)}.createBlockData()` : "null")).join(", ")} };`);
  L(`items = new ItemStack[] { ${p.parts.map((x) => (x.display === "item" ? `item(new ItemStack(${MATERIAL(x.material)}), ${jstr(ns)}, ${x.model ? jstr(x.model.split(":")[1]) : "null"})` : "null")).join(", ")} };`);
  L(`spawn = rows(floats(${chunks(p.spawn.flat())}), 10);`);
  L(`rest = rows(floats(${chunks(p.rest.flat())}), 10);`);
  L(`width = ${n4(p.interaction.width)}f;`);
  L(`height = ${n4(p.interaction.height)}f;`);
  L(`clipNames = new String[] { ${p.clips.map((c) => jstr(c.name)).join(", ")} };`);
  L(`clipLength = new int[] { ${p.clips.map((c) => c.length).join(", ")} };`);
  L(`clipLoop = new int[] { ${p.clips.map((c) => (c.loop === "once" ? 0 : c.loop === "hold" ? 1 : 2)).join(", ")} };`);
  L(`clips(${p.clips.length});`);
  p.clips.forEach((c, ci) => {
    c.segments.forEach((segs, pi) => L(`segs(${ci}, ${pi}, ${chunks(segs.flatMap((s) => [s.start, s.dur, ...s.v]))});`));
    L(`cueList(${ci}, ${chunks(c.cues.flatMap(cueNums))});`);
  });
  L(`sounds = new String[] { ${sounds.map(jstr).join(", ")} };`);
  L(`particles = new Particle[] { ${particles.map(PARTICLE_CONST).join(", ")} };`);
  const m = p.machine;
  L(`states = new String[] { ${m.states.map((s) => jstr(s.name)).join(", ")} };`);
  L(`stateClip = new int[] { ${m.states.map((s) => s.clip).join(", ")} };`);
  L(`afterTo = new int[] { ${m.states.map((s) => (s.after ? s.after.to : -1)).join(", ")} };`);
  L(`afterTicks = new int[] { ${m.states.map((s) => (s.after ? s.after.ticks : -1)).join(", ")} };`);
  L(`onEnter = new int[][] { ${m.states.map((s) => `triples(${s.onEnter.map(([op, a, b]) => (op === 2 ? [op, ev(m.events[a]), b] : [op, a, b]).join(", ")).join(", ")})`).join(", ")} };`);
  L(`tFrom = new int[] { ${m.transitions.map((t) => t.from).join(", ")} };`);
  L(`tOn = new int[] { ${m.transitions.map((t) => ev(t.on)).join(", ")} };`);
  L(`tTo = new int[] { ${m.transitions.map((t) => t.to).join(", ")} };`);
  L(`tMin = new int[] { ${m.transitions.map((t) => t.minTicks).join(", ")} };`);
  L(`tGuard = new int[][] { ${m.transitions.map((t) => `triples(${t.guard.flat().join(", ")})`).join(", ")} };`);
  L(`vars = new String[] { ${m.vars.map((v) => jstr(v.name)).join(", ")} };`);
  L(`varInit = new int[] { ${m.vars.map((v) => v.init).join(", ")} };`);
  L(`varMin = new int[] { ${m.vars.map((v) => v.min).join(", ")} };`);
  L(`varMax = new int[] { ${m.vars.map((v) => v.max).join(", ")} };`);
  L(`events = new String[] { ${events.map(jstr).join(", ")} };`);
  L(`initial = ${m.initial};`);
  L(`rightClick = ${p.triggers.rightClick ? jstr(p.triggers.rightClick) : "null"};`);
  L(`sneakRightClick = ${p.triggers.sneakRightClick ? jstr(p.triggers.sneakRightClick) : "null"};`);
  L(`leftClick = ${p.triggers.leftClick ? jstr(p.triggers.leftClick) : "null"};`);
  L(`defaultMax = ${design.minecraft?.maxInstances ?? 4};`);
  L(`defaultView = ${n4(design.minecraft?.viewRange ?? 1)}f;`);
  L(`snap = ${design.minecraft?.snap ?? true};`);
  return [
    `package ${pkg}.motions;`, ``,
    `import ${pkg}.designer.MotionDef;`,
    `import org.bukkit.Material;`,
    `import org.bukkit.Particle;`,
    `import org.bukkit.block.data.BlockData;`,
    `import org.bukkit.inventory.ItemStack;`, ``,
    `/** Motion ${design.id}: generated by Cyrus from assets/designs/${design.id}.json (MotionSpec sha256 ${specSha.slice(0, 16)}). Do not edit. */`,
    `public final class ${cls} extends MotionDef {`,
    `    public ${cls}() {`,
    ...body,
    `    }`,
    `}`, ``,
  ].join("\n");
}

/** README section of the motions of a mod. */
export function motionReadme(motions: CheckedMotion[], command: string, ns: string): string[] {
  const out = [`## Motion props`, ``];
  for (const { design, program: p } of motions) {
    const trig = Object.entries(p.triggers).filter(([, v]) => v).map(([k, v]) => `${k === "rightClick" ? "right-click" : k === "sneakRightClick" ? "sneak + right-click" : "left-click"} = ${v}`);
    out.push(`- **${design.title ?? design.id}** (\`${design.id}\`): ${p.parts.length} parts, clips ${p.clips.map((c) => c.name).join(", ")}; states ${p.machine.states.map((s) => s.name).join(", ")}; events ${p.machine.events.join(", ") || "-"}${trig.length ? `; ${trig.join(", ")}` : ""}.`);
  }
  out.push(``,
    `- \`/${command} motion spawn <id>\` (where you stand, facing you) or \`/${command} motion spawn <id> <world> <x> <y> <z> [yaw]\`; \`motion event <#|id|all> <event>\`; \`motion despawn <#|id|all>\`; \`motion debug on|off\` (${ns}.motion, operators)`,
    `- \`/${command} motion list\`, \`motion state [#]\`, \`motion check <id>\` (${ns}.command); clicking a prop needs ${ns}.motion.use (everyone)`,
    ``);
  return out;
}

const MOTION_NOTES = [
  "Motion props are display entities driven by the server: smooth movement depends on the client's interpolation (transformations are sent as short linear segments, 1 tick = 50 ms resolution).",
  "Props are never saved with the world: a restart or an unloaded chunk removes them; spawn them again with the motion command.",
  "Particles are vanilla particles chosen to resemble the effect; colours and sizes are approximate. Custom part looks and custom sounds come from the resource pack.",
];

export type WithMotions<T> = T & { motions: MotionDesign[]; motionCompile: { compiler: string; library: string; libraryHash: string; programs: { id: string; stats: McProgram["stats"] }[] } };

/**
 * Add the motions to a compiled mod: components, data classes, main-class hook, config, permissions, README, hashes.
 * `r` is the gameplay compiler's success result (files sorted by path; its main class is patched at fixed anchors).
 */
export function attachMotions<T extends { files: CompiledFile[]; readme: string; readmeSha256: string; hash: string; pkg: string; mainClass: string; command: string; notes: string[] }>(r: T, motions: CheckedMotion[], ctx: { namespace: string; pluginName: string }): { ok: true; result: WithMotions<T> } | { ok: false; errors: DzIssue[] } {
  if (!motions.length) return { ok: true, result: { ...r, motions: [], motionCompile: { compiler: MOTION_COMPILER_VERSION, library: MOTION_LIBRARY_VERSION, libraryHash: motionLibraryHash(), programs: [] } } };
  const pkg = r.pkg, ns = ctx.namespace;
  const dir = `src/main/java/${pkg.replace(/\./g, "/")}`;
  const files = r.files.map((f) => ({ ...f }));
  const put = (path: string, content: string, role: CompiledFile["role"]) => { const i = files.findIndex((f) => f.path === path); const f = { path, content, sha256: sha256(content), role }; if (i >= 0) files[i] = f; else files.push(f); };
  const get = (path: string) => files.find((f) => f.path === path);
  for (const c of MOTION_COMPONENTS) put(`${dir}/${c.file}`, renderComponent(c.source, pkg), "component");
  const classes: string[] = [];
  for (const m of [...motions].sort((a, b) => (a.design.id < b.design.id ? -1 : 1))) {
    const cls = motionClassName(m.design.id);
    if (classes.includes(cls)) return { ok: false, errors: [{ path: m.design.id, code: "class_clash", message: `two motions map to the Java class ${cls}; rename one` }] };
    classes.push(cls);
    put(`${dir}/motions/${cls}.java`, motionClass(pkg, ns, m.design, m.program, m.specSha256), "generated");
  }
  // main class hook (anchors shared by every designer main class)
  const mainPath = `src/main/java/${r.mainClass.replace(/\./g, "/")}.java`;
  const main = get(mainPath);
  if (!main) return { ok: false, errors: [{ path: "mainClass", code: "internal", message: `no main class ${mainPath}` }] };
  const lines = main.content.split("\n");
  const at = (pred: (l: string) => boolean, what: string) => { const i = lines.findIndex(pred); if (i < 0) throw new Error(`motion hook: no ${what} in the main class`); return i; };
  try {
    lines.splice(at((l) => l === "import org.bukkit.plugin.java.JavaPlugin;", "JavaPlugin import") + 1, 0, `import ${pkg}.designer.Motions;`, `import ${pkg}.motions.*;`);
    lines.splice(at((l) => /^public class \w+ extends JavaPlugin \{$/.test(l), "class line") + 1, 0, `    private Motions motions;`);
    lines.splice(at((l) => l.startsWith("        getLogger().info("), "ready log"), 0, `        motions = new Motions(this, ${jstr(ns)}, List.of(${classes.map((c) => `new ${c}()`).join(", ")}));`, `        motions.enable(getCommand(${jstr(r.command)}));`);
    lines.splice(at((l) => l === "    public void onDisable() {", "onDisable") + 1, 0, `        if (motions != null) motions.disable();`, `        motions = null;`);
  } catch (e) { return { ok: false, errors: [{ path: "mainClass", code: "internal", message: (e as Error).message }] }; }
  if (!lines.some((l) => l === "import java.util.List;")) lines.splice(lines.findIndex((l) => l.startsWith("import ")), 0, "import java.util.List;");
  put(mainPath, lines.join("\n"), "generated");
  // config.yml: motions.<id>.* (read and clamped by Motions at spawn time; not part of the designer values / migration)
  const cfgPath = "src/main/resources/config.yml";
  const cfg = get(cfgPath);
  if (cfg) {
    const block = ["motions:", ...motions.flatMap((m) => [`  ${m.design.id}:`, `    # live props of this motion at once (1-16)`, `    max_instances: ${m.design.minecraft?.maxInstances ?? 4}`, `    # how far away players see it, x the default (0.1-2.0)`, `    view_range: ${(m.design.minecraft?.viewRange ?? 1).toFixed(1)}`, `    # sound volume multiplier (0.0-2.0)`, `    volume: 1.0`])];
    put(cfgPath, cfg.content.replace(/\n*$/, "\n") + block.join("\n") + "\n", "resource");
  }
  // plugin.yml permissions
  const pyPath = "src/main/resources/plugin.yml";
  const py = get(pyPath);
  if (py) {
    const pl = py.content.split("\n");
    const i = pl.findIndex((l) => l === "permissions:");
    const perm = [`  ${ns}.motion:`, `    description: 'Spawn, drive and remove ${ctx.pluginName} motion props (/${r.command} motion)'`, `    default: op`, `  ${ns}.motion.use:`, `    description: 'Click ${ctx.pluginName} motion props'`, `    default: true`];
    if (i >= 0) pl.splice(i + 1, 0, ...perm); else pl.push("permissions:", ...perm);
    put(pyPath, pl.join("\n"), "resource");
  }
  files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  const sec = motionReadme(motions, r.command, ns);
  const rd = r.readme.includes("\n## Settings") ? r.readme.replace("\n## Settings", `\n${sec.join("\n")}\n## Settings`) : r.readme.replace(/\n*$/, "\n\n") + sec.join("\n");
  const notes = [...r.notes, ...MOTION_NOTES];
  const readme = rd.includes("## Good to know") ? rd.replace(/## Good to know\n\n/, `## Good to know\n\n${MOTION_NOTES.map((n) => `- ${n}`).join("\n")}\n`) : rd.replace(/\n*$/, "\n") + `\n## Good to know\n\n${MOTION_NOTES.map((n) => `- ${n}`).join("\n")}\n`;
  const hash = sha256(files.map((f) => `${f.path}\n${f.sha256}`).join("\n") + `\nREADME\n${sha256(readme)}`);
  return {
    ok: true,
    result: {
      ...r, files, readme, readmeSha256: sha256(readme), hash, notes,
      motions: motions.map((m) => m.design),
      motionCompile: { compiler: MOTION_COMPILER_VERSION, library: MOTION_LIBRARY_VERSION, libraryHash: motionLibraryHash(), programs: motions.map((m) => ({ id: m.design.id, stats: m.program.stats })) },
    },
  };
}

