      if (p.kind !== "num") v = Math.round(v);
      if (v < p.min || v > p.max) { errors.push(`${e.path}: ${v} is outside ${p.min}-${p.max}`); continue; }
    }
    const parts = e.path.split(".");
    const target = p.owner === "menu" ? out.menus.find((m) => m.id === parts[1]) : out.quests.find((q) => q.id === parts[1]);
    const err = !target ? `no ${p.owner} ${parts[1]}` : p.owner === "menu" ? setInMenu(target as unknown as Obj, parts.slice(2), v) : setInQuest(target as unknown as Obj, parts.slice(2), v);
    if (err) { errors.push(`${e.path}: ${err}`); continue; }
    applied.push({ path: e.path, label: p.label, from: p.value, to: v });
  }
  if (itemEdits.length) {
    const r = applyParameterEdits(out.items, itemEdits);
    if (!r.ok) errors.push(...r.errors); else { out.items = r.designs; applied.push(...r.applied); }
  }
  if (errors.length) return { ok: false, errors };
  for (const m of out.menus) { const r = MenuDesignSchema.safeParse(m); if (!r.success) return { ok: false, errors: r.error.issues.slice(0, 5).map((i) => `${m.id}: ${i.path.join(".")}: ${i.message}`) }; }
  for (const q of out.quests) { const r = QuestDesignSchema.safeParse(q); if (!r.success) return { ok: false, errors: r.error.issues.slice(0, 5).map((i) => `${q.id}: ${i.path.join(".")}: ${i.message}`) }; }
  return { ok: true, mod: out, applied };
}

/** Edit + recompile against the previous compile (its config.yml drives config_version). Only config.yml + README differ. */
export function recompileModWithEdits(previous: ModCompileOk, edits: ParamEdit[], ctx: Omit<CompileContext, "previousConfig">): { ok: true; result: ModCompileOk; diff: CompiledDiff; applied: AppliedEdit[] } | { ok: false; errors: string[] } {
  const e = applyGameplayEdits({ items: previous.designs, menus: previous.menus, quests: previous.quests }, edits);
  if (!e.ok) return e;
  const prevCfg = previous.files.find((f) => f.path === "src/main/resources/config.yml")?.content;
  const r = compileMod([...e.mod.items, ...e.mod.menus, ...e.mod.quests], { ...ctx, previousConfig: prevCfg });
  if (!r.ok) return { ok: false, errors: r.errors.map((x) => `${x.path}: ${x.message}`) };
  return { ok: true, result: r, diff: diffCompiled(previous, r), applied: e.applied };
}

