// Cyrus motion on Minecraft: the TS REFERENCE RUNTIME of designer/Motions.java. It plays a lowered McProgram exactly the
// way the Java component does (machine step, then the clip frame: segments starting this tick, cues of this tick) and
// writes the SAME debug lines and `motion state` text, so (1) unit tests hold the lowered program to the game-neutral
// core (lib/cyrus/motion/machine.ts) and (2) real flights compare the server's replies with expected text computed
// here. It is a reference model of the server side, not the client: interpolation smoothness is not simulated.
import type { McProgram, McTransform } from "./lower";

export const fmt = (v: number) => { let t = (Math.round(v * 1000) / 1000).toFixed(3); if (t.includes(".")) t = t.replace(/0+$/, "").replace(/\.$/, ""); return t === "-0" ? "0" : t; };

type Applied = { tick: number; part: number; dur: number; v: McTransform };
export type McSimLog = string;

export class McMotionSim {
  readonly log: McSimLog[] = [];
  readonly applied: Applied[] = [];
  now = 0;
  state = -1;
  enteredAt = 0;
  clip = -1;
  clipStart = 0;
  vars: number[];
  parts: { v: McTransform; dur: number }[];
  private segIdx: number[];
  private cueIdx = 0;
  private started = false;
  private inbox: string[] = [];
  private readonly born: number;

  constructor(readonly p: McProgram, readonly n = 1) {
    this.vars = p.machine.vars.map((x) => Math.max(x.min, Math.min(x.max, x.init)));
    this.parts = p.spawn.map((v) => ({ v, dur: 0 }));
    this.segIdx = p.parts.map(() => 0);
    this.born = this.now;
  }

  send(ev: string) { this.inbox.push(ev); }
  private dbg(s: string) { this.log.push(`#${this.n} ${s}`); }
  private varsText() { return this.vars.length ? this.vars.map((v, i) => ` ${this.p.machine.vars[i].name}=${v}`).join("") : ""; }

  private guard(t: number) {
    for (const [vi, op, val] of this.p.machine.transitions[t].guard) {
      const v = this.vars[vi];
      const ok = op === 0 ? v < val : op === 1 ? v <= val : op === 2 ? v === val : op === 3 ? v !== val : op === 4 ? v >= val : v > val;
      if (!ok) return false;
    }
    return true;
  }
  private enter(to: number, via: string, emits: string[]) {
    const m = this.p.machine;
    const from = this.state < 0 ? "-" : m.states[this.state].name;
    this.state = to; this.enteredAt = this.now; this.started = true;
    this.startClip(m.states[to].clip);
    for (const [op, a, b] of m.states[to].onEnter) {
      if (op === 2) { emits.push(m.events[a]); continue; }
      const def = m.vars[a];
      this.vars[a] = Math.max(def.min, Math.min(def.max, op === 0 ? b : this.vars[a] + b));
    }
    this.dbg(`t${this.now - this.born} ${from}->${m.states[to].name} (${via})${this.varsText()}`);
  }
  private startClip(c: number) {
    this.clip = c; this.clipStart = this.now; this.segIdx = this.p.parts.map(() => 0); this.cueIdx = 0;
    if (c < 0) this.p.rest.forEach((v, i) => this.apply(i, v, 3));
  }
  private apply(part: number, v: McTransform, dur: number) { this.parts[part] = { v, dur }; this.applied.push({ tick: this.now - this.born, part, dur, v }); }

  private stepMachine() {
    const m = this.p.machine;
    const emits: string[] = [];
    let n = 0;
    if (!this.started) this.enter(m.initial, "initial", emits);
    for (;;) {
      const s = m.states[this.state];
      const at = s.after ? s.after.ticks : -1;
      if (at < 0 || this.now - this.enteredAt < at) break;
      if (n >= 8) { this.dbg("cut: more than 8 transitions in one tick"); break; }
      this.enter(s.after!.to, "after", emits); n++;
      if (at > 0) break;
    }
    const events = [...this.inbox];
    this.inbox = [];
    for (let k = 0; k < events.length + emits.length; k++) {
      const ev = k < events.length ? events[k] : emits[k - events.length];
      const st = this.now - this.enteredAt;
      const t = m.transitions.findIndex((x, i) => (x.from === this.state || x.from === -1) && x.on === ev && this.guard(i) && st >= x.minTicks);
      if (t < 0) { this.dbg(`t${this.now - this.born} ignored ${ev} in ${m.states[this.state].name}`); continue; }
