      this.enter(m.transitions[t].to, ev, emits); n++;
    }
  }
  private frame() {
    const c = this.clip;
    if (c < 0) return;
    const clip = this.p.clips[c];
    const l = this.now - this.clipStart;
    let lt: number;
    if (clip.loop === "loop") { lt = l % clip.length; if (lt === 0 && l > 0) { this.segIdx = this.p.parts.map(() => 0); this.cueIdx = 0; } }
    else { if (l >= clip.length) return; lt = l; }
    clip.segments.forEach((segs, p) => {
      while (this.segIdx[p] < segs.length && segs[this.segIdx[p]].start <= lt) { const k = this.segIdx[p]++; if (segs[k].start === lt) this.apply(p, segs[k].v, segs[k].dur); }
    });
    while (this.cueIdx < clip.cues.length && clip.cues[this.cueIdx].tick <= lt) {
      const q = clip.cues[this.cueIdx++];
      if (q.tick !== lt) continue;
      const t = `t${this.now - this.born}`;
      if (q.kind === "sound") this.dbg(`${t} sound ${q.key}`);
      else if (q.kind === "particle") this.dbg(`${t} particle ${q.particle} x${Math.max(1, Math.min(64, q.count))}`);
      else if (q.kind === "brightness") this.dbg(`${t} brightness p${q.part} ${q.level}`);
      else if (q.kind === "event") this.dbg(`${t} event ${q.name}`);
      // directed particles are not logged (one line per particle would flood the log)
    }
  }
  /** One server tick (Motions.tick: now++, then machine, then frame). */
  tick() { this.now++; this.stepMachine(); this.frame(); }
  run(ticks: number) { for (let i = 0; i < ticks; i++) this.tick(); }

  /** The `/<mod> motion state` lines of this instance. */
  stateText(id: string): string[] {
    const m = this.p.machine;
    const head = `#${this.n} ${id} state=${this.state < 0 ? "-" : m.states[this.state].name} clip=${this.clip < 0 ? "-" : this.p.clips[this.clip].name} age=${this.now - this.born}${this.varsText()}`;
    return [head, ...this.parts.map((x, i) => `  p${i} ${partText(x.v, x.dur)}`)];
  }
}

export const partText = (v: McTransform, dur: number) => `t ${fmt(v[0])},${fmt(v[1])},${fmt(v[2])} q ${fmt(v[3])},${fmt(v[4])},${fmt(v[5])},${fmt(v[6])} s ${fmt(v[7])},${fmt(v[8])},${fmt(v[9])} i${dur}`;

