    return { plan: plan ? { ...plan, allowed: { texture: false, sound: false, creature: false } } : null, service: null, meta: { ...meta, allowed: [], notices: [...meta.notices, msg], ...(dp.route ? { datapack: { route: false, matched: dp.matched, limits: dp.l
  }
