// neutral machine runner, the compiled mod (components, data classes, main-class hook, config, permissions, README,
// goldens), mod-level validation (broken specs rejected with paths), the route words, the build-service prompt part and
// request flag, and the generated service bundle agreeing with the TypeScript.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { lowerMinecraft, partTargetAt, mcParticleFor, nearestBlock, TOLERANCE, type McProgram } from "../lib/cyrus/designer/motion/lower";
import { validateMotionDesign, MOTION_DESIGN_LIMITS } from "../lib/cyrus/designer/motion/spec";
import { McMotionSim, partText } from "../lib/cyrus/designer/motion/simulate";
import { MOTION_PRESETS_BRIEF } from "../lib/cyrus/designer/motion/brief";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { validateGameplay, designKind } from "../lib/cyrus/designer/gameplay/spec";
import { decideDesignerRoute, matchMotionWords, hasMotionDesigns } from "../lib/cyrus/designer/route";
import { recompileModWithEdits } from "../lib/cyrus/designer/gameplay/params";
import { runMachine, sample, worldMatrices } from "../lib/cyrus/motion";
import { decompose, mul, quatAngle, slerp, lerp, type Quat } from "../lib/cyrus/motion/math";
import { doorSpec, gunReloadSpec, effectSpec } from "../lib/cyrus/motion/presets";

const FX = path.join(__dirname, "fixtures/cyrus-motion-mc");
const fx = (n: string) => JSON.parse(readFileSync(path.join(FX, `${n}.json`), "utf8"));
const NS = "nx_m0710n01";
const V = "1.21.11";
const PLUGIN = "MotionLab";
const GOLDEN = path.join(FX, "golden.json");
const golden: Record<string, string> = existsSync(GOLDEN) ? JSON.parse(readFileSync(GOLDEN, "utf8")) : {};
const fresh: Record<string, string> = {};
function gold(key: string, value: string) {
  fresh[key] = value;
  if (process.env.UPDATE_CYRUS_MOTION_GOLDEN === "1") { writeFileSync(GOLDEN, JSON.stringify({ ...golden, ...fresh }, null, 1) + "\n"); return; }
  assert.equal(value, golden[key], `golden ${key} changed (UPDATE_CYRUS_MOTION_GOLDEN=1 to accept)`);
}
const ok = (n: string, version = V) => { const r = validateMotionDesign(fx(n), { version, namespace: NS }); assert.equal(r.ok, true, JSON.stringify(!r.ok && r.errors)); return r as Extract<typeof r, { ok: true }>; };

/** Replay segments the way the client is assumed to (translation/scale lerp, rotation slerp) and compare every tick. */
function maxError(p: McProgram, clip: number, part: number, truth: (t: number) => number[]): { pos: number; deg: number } {
  const c = p.clips[clip];
  let cur = truth(0), from = cur, to = cur, s0 = 0, dur = 0;
  let pos = 0, deg = 0;
  const segs = [...c.segments[part]];
  for (let t = 0; t <= c.length; t++) {
    const k = segs.findIndex((x) => x.start === t);
    if (k >= 0) { from = cur; to = segs[k].v; s0 = t; dur = segs[k].dur; if (dur === 0) { from = to; } }
    const f = dur === 0 ? 1 : Math.min(1, (t - s0) / dur);
    cur = [...[0, 1, 2].map((i) => lerp(from[i], to[i], f)), ...slerp(from.slice(3, 7) as Quat, to.slice(3, 7) as Quat, f), ...[7, 8, 9].map((i) => lerp(from[i], to[i], f))];
    const x = truth(t);
    if (t === 0) continue; // the clip may start from another clip's end pose
    pos = Math.max(pos, Math.hypot(cur[0] - x[0], cur[1] - x[1], cur[2] - x[2]));
    deg = Math.max(deg, quatAngle(cur.slice(3, 7) as Quat, x.slice(3, 7) as Quat));
  }
  return { pos, deg };
}

describe("motion on Minecraft: lowering", () => {
  const door = ok("lab_door");
  it("door: 3 display parts + an interaction box, the open clip ends on a 90 degree hinge", () => {
    const p = door.program;
    assert.deepEqual(p.parts.map((x) => `${x.node}:${x.display}:${x.material}`), ["frame:block:minecraft:dark_oak_planks", "door:block:minecraft:spruce_planks", "handle:block:minecraft:gold_block"]);
    const open = p.clips.findIndex((c) => c.name === "open");
    const end = partTargetAt(p.clips[open], 1, 99)!;
    // rotation about +y by 90 degrees
    assert.deepEqual(end.slice(3, 7).map((x) => Math.round(x * 1e4) / 1e4), [0, 0.7071, 0, 0.7071]);
    assert.ok(p.interaction.width >= 1 && p.interaction.height >= 2);
    assert.deepEqual(p.triggers, { rightClick: "toggle", sneakRightClick: null, leftClick: null });
  });
  it("segments reproduce the sampled curve within tolerance at every tick (every clip, every part)", () => {
    for (const r of [door, ok("lab_pistol")]) {
      const spec = r.spec;
      r.program.clips.forEach((c, ci) => r.program.parts.forEach((part, pi) => {
        const truth = (t: number) => { const m = mul(worldMatrices(spec, sample(spec, c.name, t))[part.node], part.local); const d = decompose(m); return [...d.t, ...d.q, ...d.s]; };
        const e = maxError(r.program, ci, pi, truth);
        // snaps (step keys) are exact at their tick; linear segments stay inside the fitting tolerance (+ rounding)
        assert.ok(e.pos <= TOLERANCE.pos + 0.002, `${spec.id}.${c.name}.${part.node}: pos error ${e.pos}`);
        assert.ok(e.deg <= TOLERANCE.deg + 0.05, `${spec.id}.${c.name}.${part.node}: angle error ${e.deg}`);
      }));
    }
  });
  it("easing is split into short segments; static spans do not blend; step keys snap with duration 0", () => {
    const p = ok("lab_pistol").program;
    const reload = p.clips.find((c) => c.name === "reload")!;
    const mag = p.parts.findIndex((x) => x.node === "mag");
    assert.ok(reload.segments[mag].length >= 3, "the eased magazine drop needs several linear segments");
    assert.ok(p.stats.snaps >= 1, "the magazine's step key snaps");
    for (const c of p.clips) for (const segs of c.segments) for (let i = 1; i < segs.length; i++) assert.ok(segs[i].start > segs[i - 1].start, "one change per tick");
    const idle = p.clips.find((c) => c.name === "idle")!;
    assert.ok(idle.segments.every((s) => s.length === 1 && s[0].dur === 1), "a held pose arrives in one tick");
  });
  it("cues: muzzle flash = the core's particle births (directed), sounds by key, brightness without a part is dropped", () => {
    const r = ok("lab_pistol");
    const fire = r.program.clips.find((c) => c.name === "fire")!;
    const directed = fire.cues.filter((c) => c.kind === "directed");
    assert.equal(directed.filter((c) => c.tick === 0).length, 4 + 6 + 3, "flash + sparks + smoke of the muzzle flash at tick 0");
    assert.equal(directed.filter((c) => c.tick === 1).length, 1, "the brass casing at tick 1");
    assert.deepEqual(fire.cues.filter((c) => c.kind === "sound").map((c) => c.kind === "sound" && c.key), ["minecraft:entity.firework_rocket.blast"]);
    assert.ok(r.dropped.some((d) => /muzzle has no display part/.test(d.reason)));
    assert.ok(r.warnings.some((w) => w.code === "dropped_on_minecraft"));
    assert.deepEqual([...new Set(directed.map((c) => c.kind === "directed" && c.particle))].sort(), ["crit", "flame", "lava", "smoke"]);
  });
  it("machine-less effect: rest + one state per clip, right-click plays; loop cues per cycle", () => {
    const r = ok("lab_fire");
    assert.deepEqual(r.program.machine.states.map((s) => s.name), ["rest", "play"]);
    assert.equal(r.program.triggers.rightClick, "play");
    assert.equal(r.program.parts.length, 0);
    const play = r.program.clips[0];
    assert.equal(play.loop, "loop");
    assert.ok(play.cues.filter((c) => c.kind === "directed").length > 100);
    assert.ok(play.cues.some((c) => c.kind === "sound" && c.key === "minecraft:block.fire.ambient"));
  });
  it("sound:<catalog id> resolves through the mod's sounds, otherwise it is dropped (never a silent wrong key)", () => {
    const { spec } = gunReloadSpec();
    const a = lowerMinecraft(spec, {}, { namespace: NS });
    assert.equal(a.ok, true);
    assert.ok(a.dropped.some((d) => /sound:gun_pistol_shot is not one of this mod's sounds/.test(d.reason)));
    const b = lowerMinecraft(spec, {}, { namespace: NS, sounds: { gun_pistol_shot: `${NS}:gun.shot` } });
    assert.ok(b.ok && b.program.clips.find((c) => c.name === "fire")!.cues.some((c) => c.kind === "sound" && c.key === `${NS}:gun.shot`));
  });
  it("sprite mapping and proxy colours are deterministic", () => {
    assert.equal(mcParticleFor({ sprite: "flame", colors: ["#5aa8ff"] }), "soul_fire_flame");
    assert.equal(mcParticleFor({ sprite: "smoke", size: [0.4, 1.2] }), "large_smoke");
    assert.equal(mcParticleFor({ sprite: "flash", size: [2.5, 0.5] }), "explosion");
    assert.equal(nearestBlock("#a8784a"), "minecraft:oak_planks");
    assert.equal(nearestBlock("#3a3f47"), "minecraft:gray_concrete");
  });
  it("lowering is deterministic (golden)", () => {
    for (const n of ["lab_door", "lab_pistol", "lab_fire"]) { const a = JSON.stringify(ok(n).program), b = JSON.stringify(ok(n).program); assert.equal(a, b); gold(`${n}.program`, require("node:crypto").createHash("sha256").update(a).digest("hex")); }
  });
});

describe("motion on Minecraft: reference runtime parity with the neutral machine", () => {
  it("pistol: the TS twin of Motions.java follows lib/cyrus/motion/machine.ts tick for tick (offset 1: spawn tick)", () => {
    const r = ok("lab_pistol");
    const inputs = [{ tick: 2, event: "fire" }, { tick: 8, event: "fire" }, { tick: 14, event: "fire" }, { tick: 20, event: "fire" }, { tick: 26, event: "reload" }];
    const core = runMachine(r.spec, undefined, inputs, 80).log.filter((l) => l.kind === "enter").map((l) => l.kind === "enter" && `${l.tick}:${l.state}`);
    const sim = new McMotionSim(r.program);
    for (let t = 0; t < 80; t++) { for (const i of inputs) if (i.tick === t) sim.send(i.event); sim.tick(); }
    const mc = sim.log.filter((l) => /->/.test(l)).map((l) => { const m = /t(\d+) \S+->(\S+)/.exec(l)!; return `${Number(m[1]) - 1}:${m[2]}`; });
    assert.deepEqual(mc, core);
    assert.ok(sim.log.includes("#1 t21 dry->empty (after)") || sim.log.some((l) => /dry->empty \(after\)/.test(l)));
    assert.ok(sim.log.some((l) => / sound minecraft:entity.firework_rocket.blast$/.test(l)));
  });
  it("door: state text after open shows the hinge at 90 degrees (what `motion state` prints on the server)", () => {
    const r = ok("lab_door");
    const sim = new McMotionSim(r.program);
    sim.tick(); sim.send("toggle"); sim.run(30);
    const txt = sim.stateText("lab_door");
    assert.match(txt[0], /^#1 lab_door state=open clip=ajar age=31$/);
    assert.match(txt[2], /q 0,0\.707,0,0\.707 /);
    assert.equal(txt[2], `  p1 ${partText(partTargetAt(r.program.clips.find((c) => c.name === "ajar")!, 1, 0)!, 1)}`);
  });
});

describe("motion on Minecraft: compiled mod", () => {
  const designs = [fx("lab_door"), fx("lab_pistol"), fx("lab_fire")];
  const c = compileMod(designs, { version: V, namespace: NS, pluginName: PLUGIN }) as ModCompileOk;
  it("compiles: runtime components, one data class per motion, main-class hook, config, permissions, README", () => {
    assert.equal(c.ok, true, JSON.stringify((c as unknown as { errors: unknown }).errors));
    const paths = c.files.map((f) => f.path);
    const dir = "src/main/java/dev/nxeon/plugins/motionlab";
    for (const f of ["designer/Motions.java", "designer/MotionDef.java", "motions/LabDoorMotion.java", "motions/LabPistolMotion.java", "motions/LabFireMotion.java"]) assert.ok(paths.includes(`${dir}/${f}`), f);
    const main = c.files.find((f) => f.path === `${dir}/MotionLab.java`)!.content;
    assert.match(main, /motions = new Motions\(this, "nx_m0710n01", List\.of\(new LabDoorMotion\(\), new LabFireMotion\(\), new LabPistolMotion\(\)\)\);\n        motions\.enable\(getCommand\("motionlab"\)\);/);
    assert.match(main, /public void onDisable\(\) \{\n        if \(motions != null\) motions\.disable\(\);/);
    const cfg = c.files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.match(cfg, /\nmotions:\n  lab_door:\n    # live props of this motion at once \(1-16\)\n    max_instances: 4\n/);
    const py = c.files.find((f) => f.path.endsWith("plugin.yml"))!.content;
    assert.match(py, /  nx_m0710n01\.motion:\n    description: .*\n    default: op\n  nx_m0710n01\.motion\.use:/);
    assert.match(c.readme, /## Motion props/);
    assert.equal(c.counts.motions, 3);
    assert.deepEqual(c.motions?.map((m) => m.id), ["lab_door", "lab_fire", "lab_pistol"]);
    const door = c.files.find((f) => f.path.endsWith("LabDoorMotion.java"))!.content;
    assert.match(door, /blocks = new BlockData\[\] \{ Material\.DARK_OAK_PLANKS\.createBlockData\(\), Material\.SPRUCE_PLANKS\.createBlockData\(\), Material\.GOLD_BLOCK\.createBlockData\(\) \};/);
    assert.match(door, /rightClick = "toggle";/);
    assert.ok(!/[^\x20-\x7e\n]/.test(door), "plain ASCII source");
    const pistol = c.files.find((f) => f.path.endsWith("LabPistolMotion.java"))!.content;
    assert.match(pistol, /particles = new Particle\[\] \{ (Particle\.[A-Z_]+(, )?)+ \};/);
  });
  it("deterministic: same designs = same hash (golden); java strings stay below the constant limit", () => {
    const again = compileMod(designs, { version: V, namespace: NS, pluginName: PLUGIN }) as ModCompileOk;
    assert.equal(again.hash, c.hash);
    gold("mod.1.21.11.hash", c.hash);
    gold("mod.26.2.hash", (compileMod(designs, { version: "26.2", namespace: NS, pluginName: PLUGIN }) as ModCompileOk).hash);
    for (const f of c.files) for (const m of f.content.matchAll(/"([^"\\]*)"/g)) assert.ok(m[1].length < 20100, `${f.path}: a ${m[1].length}-char literal`);
  });
  it("a mod with items AND motions keeps its item part; parameter edits keep the motions", () => {
    const item = JSON.parse(readFileSync(path.join(__dirname, "../services/modbuilder/designer-example.json"), "utf8"));
    const mix = compileMod([item, fx("lab_door")], { version: V, namespace: "nx_abcd1234", pluginName: "MixLab" }) as ModCompileOk;
    assert.equal(mix.ok, true, JSON.stringify((mix as unknown as { errors: unknown }).errors));
    assert.equal(mix.counts.items, 1); assert.equal(mix.counts.motions, 1);
    const p = mix.params[0];
    const e = recompileModWithEdits(mix, [{ path: p.path, value: p.kind === "text" || p.kind === "sound" ? p.value : Math.min(p.max, Number(p.value) + (p.kind === "num" ? 0.5 : 1)) }], { version: V, namespace: "nx_abcd1234", pluginName: "MixLab" });
    assert.equal(e.ok, true, JSON.stringify(!e.ok && e.errors));
    if (e.ok) { assert.equal(e.result.counts.motions, 1); assert.equal(e.diff.javaChanged, false); }
  });
  it("mods without motions are byte-identical to before (no motion files, no hook)", () => {
    const item = JSON.parse(readFileSync(path.join(__dirname, "../services/modbuilder/designer-example.json"), "utf8"));
    const r = compileMod([item], { version: V, namespace: "nx_abcd1234", pluginName: "Plain" }) as ModCompileOk;
    assert.ok(!r.files.some((f) => /Motion/.test(f.path)));
    assert.equal(r.motions, undefined);
  });
});

describe("motion on Minecraft: validation rejects broken specs (with paths)", () => {
  it("the broken fixture fails with every problem named", () => {
    const r = validateMotionDesign(fx("broken_hinge"), { version: V, namespace: NS });
    assert.equal(r.ok, false);
    const codes = r.errors.map((e) => e.code);
    for (const c of ["hinge_axis", "hinge_limit", "cap_particles_tick", "unresolved_ref"]) assert.ok(codes.includes(c), `${c} in ${codes}`);
    assert.ok(r.errors.every((e) => e.path.startsWith("motion.") || e.path.startsWith("minecraft.")));
  });
  it("mod level: the broken file is named, the good ones still validate", () => {
    const v = validateGameplay([fx("lab_door"), fx("broken_hinge")], { version: V, namespace: NS });
    assert.equal(v.ok, false);
    assert.deepEqual(v.files.map((f) => `${f.id}:${f.kind}:${f.ok}`), ["lab_door:motion:true", "broken_hinge:motion:false"]);
    assert.deepEqual(v.motions.map((m) => m.design.id), ["lab_door"]);
    const c = compileMod([fx("lab_door"), fx("broken_hinge")], { version: V, namespace: NS, pluginName: PLUGIN });
    assert.equal(c.ok, false);
  });
  it("schema, preset, part and sound errors", () => {
    const bad = (patch: (d: Record<string, unknown>) => void) => { const d = fx("lab_door"); patch(d); return validateMotionDesign(d, { version: V, namespace: NS }); };
    const codes = (r: ReturnType<typeof bad>) => (r.ok ? [] : r.errors.map((e) => e.code));
    assert.ok(codes(bad((d) => { d.motion = { preset: "motion:car_drive" }; })).includes("unknown_preset"));
    assert.ok(codes(bad((d) => { (d.minecraft as { parts: Record<string, unknown> }).parts.door = { block: "minecraft:not_a_block" }; })).includes("unknown_vanilla_id"));
    assert.ok(codes(bad((d) => { (d.minecraft as { parts: Record<string, unknown> }).parts.ghost = { block: "minecraft:stone" }; })).includes("unresolved_ref"));
    assert.ok(codes(bad((d) => { d.motion = { preset: "motion:door_hinge", params: { openSound: "evil:sound" } }; })).includes("sound_namespace"));
    assert.ok(codes(bad((d) => { (d as { kind: string }).kind = "motions"; })).includes("schema"));
    assert.ok(codes(bad((d) => { (d.minecraft as Record<string, unknown>).maxInstances = 99; })).includes("schema"));
    const clamped = bad((d) => { d.motion = { preset: "motion:door_hinge", params: { angle: 500 } }; });
    assert.equal(clamped.ok, true);
    assert.ok(clamped.warnings.some((w) => w.code === "param_clamped"));
  });
  it("too many motion files in one mod", () => {
    const many = Array.from({ length: MOTION_DESIGN_LIMITS.maxMotions + 1 }, (_, i) => ({ ...fx("lab_fire"), id: `fire_${i}` }));
    const v = validateGameplay(many, { version: V, namespace: NS });
    assert.ok(v.errors.some((e) => e.code === "too_many_motions"));
  });
  it("a vehicle spec is expressible in the core but its wheels / attach are dropped on Minecraft with reasons", () => {
    const car = { schemaVersion: 1, id: "kart", rig: { nodes: [
      { name: "chassis", parent: null, kind: "part", pivot: [0, 0.3, 0], proxy: { size: [1, 0.3, 1.6], color: "#8e2121" } },
      { name: "wheel_fl", parent: "chassis", kind: "wheel", pivot: [-0.5, 0.2, -0.6], wheel: { axle: "x", radius: 0.2 }, proxy: { size: [0.1, 0.4, 0.4], color: "#080a0f" } },
      { name: "seat", parent: "chassis", kind: "seat", pivot: [0, 0.5, 0] },
    ] }, clips: [{ name: "enter", length: 20, loop: "once", tracks: [{ kind: "transform", node: "wheel_fl", channel: "rot", keys: [{ t: 0, v: [0, 0, 0] }, { t: 20, v: [90, 0, 0] }] }, { kind: "event", at: 10, name: "seated", attach: { child: "$actor", socket: "seat" } }] }] };
    const r = validateMotionDesign({ schemaVersion: 1, kind: "motion", id: "kart", motion: car }, { version: V, namespace: NS });
    assert.equal(r.ok, true, JSON.stringify(!r.ok && r.errors));
    assert.ok(r.dropped.some((d) => /vehicles are not a Minecraft target/.test(d.reason)));
    assert.ok(r.dropped.some((d) => /attaching or detaching an actor/.test(d.reason)));
  });
});

describe("motion on Minecraft: route, prompt, request, service bundle", () => {
  it("motion words route to the designer with the motion part; vehicles do not", () => {
    assert.deepEqual(matchMotionWords("a door that swings open when clicked"), ["motion:door"]);
    assert.deepEqual(matchMotionWords("a drivable car with doors"), []);
    const d = decideDesignerRoute({ text: "an animated drawbridge gate for my castle", mcVersion: V, on: true });
    assert.equal(d.route, true); assert.equal(d.motion, true);
    assert.ok(d.limits.some((l) => /Animated props/.test(l)));
    assert.equal(decideDesignerRoute({ text: "an animated drawbridge", mcVersion: V, on: false }).route, false);
    assert.equal(decideDesignerRoute({ text: "a shop menu", mcVersion: V, on: true }).motion, undefined);
    assert.equal(hasMotionDesigns({ assets: { designs: [{ kind: "motion" }] } }), true);
    assert.equal(designKind({ kind: "motion" }), "motion");
  });
  it("the MOTION PROPS prompt part lists every preset and is only added with design + motion", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const P = require("../services/modbuilder/prompts.js");
    assert.equal(P.MOTION_MAX, MOTION_DESIGN_LIMITS.maxMotions);
    for (const id of ["motion:door_hinge", "motion:gun_reload", "effect:fire", "gen:gait"]) assert.ok(P.MOTION_SECTION.includes(id), id);
    assert.ok(P.MOTION_SECTION.includes(MOTION_PRESETS_BRIEF.split("\n")[0]));
    assert.ok(P.systemPrompt(V, { design: true, motion: true }).includes("MOTION PROPS (this build uses them)"));
    assert.ok(!P.systemPrompt(V, { design: true }).includes("MOTION PROPS"));
    assert.ok(!P.systemPrompt(V, { motion: true }).includes("MOTION PROPS"));
  });
  it("the service accepts assets.motion only with assets.design", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const TX = require("../services/modbuilder/textures.js");
    const ok1 = TX.parseAssetsRequest({ texture: false, sound: false, namespace: NS, design: true, motion: true }, V, new Set(), () => false, () => true);
    assert.equal(ok1.motion, true);
    assert.match(TX.parseAssetsRequest({ texture: false, sound: false, namespace: NS, motion: true }, V, new Set()).error, /needs assets.design/);
  });
  it("the generated service bundle validates and compiles motions exactly like the TypeScript", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const DZ = require("../services/modbuilder/designer-spec.js");
    const designs = [fx("lab_door"), fx("lab_pistol"), fx("lab_fire")];
    const a = DZ.compileMod(designs, { version: V, namespace: NS, pluginName: PLUGIN });
    const b = compileMod(designs, { version: V, namespace: NS, pluginName: PLUGIN }) as ModCompileOk;
    assert.equal(a.ok, true); assert.equal(a.hash, b.hash);
    assert.equal(DZ.validateMotionDesign(fx("broken_hinge"), { version: V, namespace: NS }).ok, false);
    assert.ok(typeof DZ.MOTION_PRESETS_BRIEF === "string" && DZ.MOTION_PRESETS_BRIEF.includes("motion:door_hinge"));
  });
  it("core presets used here fit (door, gun, fire build at defaults)", () => {
    for (const s of [doorSpec().spec, gunReloadSpec().spec, effectSpec("effect:fire").spec]) assert.equal(lowerMinecraft(s, {}, { namespace: NS }).ok, true, s.id);
  });
});

