// REAL motion-prop runs ON node-2 (not part of the unit suite: real javac, real strict scan, real Paper boots).
//   scripts/devhost run --lock -- npx tsx test/cyrus-motion-real.ts --out /tank/nxeon-build/tmp/cyrus-r21-motion/results.json [--javac-only] [--lane 26.2]
// No real Minecraft client, no bot, no AI model: what runs is the compile lane (TS lowering + compiler -> javac with
// -Xlint), the strict safety scan, and a Test Flight per lane whose RCON checks drive the props from the console
// (spawn, events, state machine, transformation values read back from the entities, caps, despawn) plus the debug log
// (state changes, after-durations, sound / particle cues). Clicking props, interpolation smoothness, particle looks and
// sounds in a client are NOT exercised (they need a real client; reported as such). A deliberately broken motion design
// is run through the TS validator, the generated service bundle and the service's workspace check and must be refused.
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { validateMotionDesign } from "../lib/cyrus/designer/motion/spec";
import { McMotionSim, partText } from "../lib/cyrus/designer/motion/simulate";
import { partTargetAt } from "../lib/cyrus/designer/motion/lower";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck } from "../lib/cyrus/testflight/types";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r21-motion/run-${Date.now().toString(36)}`;
const ALL_LANES = [
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const LANES = ALL_LANES.filter((l) => !arg("--lane") || l.version === arg("--lane"));
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const NS = "nx_m0710n01";
const PLUGIN = "MotionLab";
const CMD = PLUGIN.toLowerCase();
const FX = path.join(ROOT, "test/fixtures/cyrus-motion-mc");
const fx = (n: string) => JSON.parse(readFileSync(path.join(FX, `${n}.json`), "utf8"));
const DESIGNS = () => [fx("lab_door"), fx("lab_pistol"), fx("lab_fire")];

const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}
function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}

function build(r: ModCompileOk, lane: (typeof ALL_LANES)[number]) {
  const dir = path.join(RUN, lane.version);
  rmSync(dir, { recursive: true, force: true });
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  const t0 = Date.now();
  let javacOut = "";
  try { javacOut = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; throw new Error(`javac failed on ${lane.version}:\n${(x.stderr ?? "") + (x.stdout ?? "")}`.slice(0, 12000)); }
  const javacMs = Date.now() - t0;
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jar = (out: string) => { execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", out, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]); return sha(readFileSync(out)); };
  const jarPath = path.join(dir, `${PLUGIN}-${lane.version}.jar`);
  const h1 = jar(jarPath), h2 = jar(path.join(dir, "again.jar"));
  return { dir, classes, sources: sources.length, classFiles: entries.filter((e) => e.endsWith(".class")).length, javacMs, javacWarnings: (javacOut.match(/warning:/g) ?? []).length, javacOut: javacOut.slice(0, 3000), jarPath, jarSha256: h1, reproducible: h1 === h2, jarBytes: readFileSync(jarPath).length };
}

function scan(b: ReturnType<typeof build>, lane: (typeof ALL_LANES)[number]) {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
  const oldPath = process.env.PATH;
  process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
  try {
    const bytecode = S.scanBytecode(b.classes, { profile: "strict" });
    const src = walk(path.join(b.dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(path.join(b.dir, "ws"), abs) }));
    const source = S.scanSource(src, { profile: "strict" });
    const all = [...bytecode, ...source] as { severity: string; rule: string; where: string; message: string }[];
    return { profile: "strict", blocks: all.filter((f) => f.severity === "block").length, warnings: all.filter((f) => f.severity === "warn").length, findings: all.map((f) => `${f.severity} ${f.rule} ${f.where}: ${f.message}`).slice(0, 20) };
  } finally { process.env.PATH = oldPath; }
}

function harvest(runId: string | null) {
  const out: Record<string, unknown> = {};
  if (!runId || !/^[A-Za-z0-9_-]+$/.test(runId)) return out;
  const dir = path.join(TF, "runs", runId);
  const log = path.join(dir, "logs/latest.log");
  const lines = existsSync(log) ? readFileSync(log, "utf8").split("\n") : [];
  const motion = lines.filter((l) => /\[motion\]/.test(l)).map((l) => l.replace(/^.*\[motion\] /, "").slice(0, 200));
  out.motionLog = motion.slice(0, 120);
  out.pluginLog = lines.filter((l) => new RegExp(PLUGIN, "i").test(l) && !/Preparing|\[motion\]/.test(l)).map((l) => l.slice(0, 300)).slice(0, 30);
  out.pluginErrorLines = lines.filter((l) => /\/(ERROR|FATAL)\]|Exception/.test(l) && new RegExp(PLUGIN, "i").test(l)).map((l) => l.slice(0, 300)).slice(0, 20);
  out.sandboxNoiseLines = lines.filter((l) => /\/(ERROR|FATAL)\]/.test(l) && !new RegExp(PLUGIN, "i").test(l)).length;
  rmSync(dir, { recursive: true, force: true });
  return out;
}

/** Log checks: the server's own debug lines must show the transitions and after-durations the TS lowering predicts. */
function logChecks(log: string[], c: ModCompileOk): { id: string; status: "pass" | "fail"; evidence: string[] }[] {
  const out: { id: string; status: "pass" | "fail"; evidence: string[] }[] = [];
  const tick = (re: RegExp) => { const l = log.find((x) => re.test(x)); const m = l ? /t(\d+) /.exec(l) : null; return { line: l ?? null, t: m ? Number(m[1]) : null }; };
  const door = validateMotionDesign(fx("lab_door"), { version: "1.21.11", namespace: NS });
  const openLen = door.ok ? door.program.clips.find((x) => x.name === "open")!.length : -1;
  const a = tick(/^#1 t\d+ closed->opening \(toggle\)/), b = tick(/^#1 t\d+ opening->open \(after\)/);
  out.push({ id: "log-door-after-duration", status: a.t !== null && b.t !== null && b.t - a.t === openLen ? "pass" : "fail", evidence: [`expected ${openLen} ticks (TS lowering)`, a.line ?? "no toggle line", b.line ?? "no after line"] });
  const s = log.find((x) => /^#1 t\d+ sound minecraft:block\.wooden_door\.open$/.test(x));
  out.push({ id: "log-door-open-sound-cue", status: s ? "pass" : "fail", evidence: [s ?? "no door sound cue line"] });
  const fires = log.filter((x) => /^#2 t\d+ (idle->fire|idle->fire_last) \(fire\)/.test(x));
  out.push({ id: "log-pistol-three-shots", status: fires.length === 3 ? "pass" : "fail", evidence: fires.slice(0, 4) });
  const shots = log.filter((x) => /^#2 t\d+ sound minecraft:entity\.firework_rocket\.blast$/.test(x));
  out.push({ id: "log-pistol-shot-cues", status: shots.length === 3 ? "pass" : "fail", evidence: shots.slice(0, 4) });
  const rl = tick(/^#2 t\d+ empty->reload_empty \(reload\)/), ck = tick(/^#2 t\d+ idle->cock \(auto_cock\)/);
  const pistol = validateMotionDesign(fx("lab_pistol"), { version: "1.21.11", namespace: NS });
  const relLen = pistol.ok ? pistol.program.clips.find((x) => x.name === "reload_empty")!.length : -1;
  out.push({ id: "log-pistol-reload-then-auto-cock", status: rl.t !== null && ck.t !== null && ck.t - rl.t === relLen ? "pass" : "fail", evidence: [`expected ${relLen} ticks`, rl.line ?? "no reload line", ck.line ?? "no cock line"] });
  const dry = log.find((x) => /^#2 t\d+ empty->dry \(fire\)/.test(x));
  out.push({ id: "log-pistol-dry-fire-when-empty", status: dry ? "pass" : "fail", evidence: [dry ?? "no dry line"] });
  const fire = log.find((x) => /^#3 t\d+ particle (flame|smoke|crit) x\d+$/.test(x)) ?? log.find((x) => /^#3 t\d+ sound minecraft:block\.fire\.ambient$/.test(x));
  out.push({ id: "log-fire-effect-cues", status: fire ? "pass" : "fail", evidence: [fire ?? "no fire cue line"] });
