// REAL motion-prop runs ON node-2 (not part of the unit suite: real javac, real strict scan, real Paper boots).
//   scripts/devhost run --lock -- npx tsx test/cyrus-motion-real.ts --out /tank/nxeon-build/tmp/cyrus-r21-motion/results.json [--javac-only] [--lane 26.2]
// No real Minecraft client, no bot, no AI model: what runs is the compile lane (TS lowering + compiler -> javac with
// -Xlint), the strict safety scan, and a Test Flight per lane whose RCON checks drive the props from the console
// (spawn, events, state machine, transformation values read back from the entities, caps, despawn) plus the debug log
// (state changes, after-durations, sound / particle cues). Clicking props, interpolation smoothness, particle looks and
// sounds in a client are NOT exercised (they need a real client; reported as such). A deliberately broken motion design
// is run through the TS validator, the generated service bundle and the service's workspace check and must be refused.
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { compileMod, type ModCompileOk } from "../lib/cyrus/designer/gameplay/compile";
import { validateMotionDesign } from "../lib/cyrus/designer/motion/spec";
import { McMotionSim, partText } from "../lib/cyrus/designer/motion/simulate";
import { partTargetAt } from "../lib/cyrus/designer/motion/lower";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck } from "../lib/cyrus/testflight/types";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r21-motion/run-${Date.now().toString(36)}`;
const ALL_LANES = [
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const LANES = ALL_LANES.filter((l) => !arg("--lane") || l.version === arg("--lane"));
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const NS = "nx_m0710n01";
const PLUGIN = "MotionLab";
const CMD = PLUGIN.toLowerCase();
const FX = path.join(ROOT, "test/fixtures/cyrus-motion-mc");
const fx = (n: string) => JSON.parse(readFileSync(path.join(FX, `${n}.json`), "utf8"));
const DESIGNS = () => [fx("lab_door"), fx("lab_pistol"), fx("lab_fire")];

const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}
function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}

function build(r: ModCompileOk, lane: (typeof ALL_LANES)[number]) {
  const dir = path.join(RUN, lane.version);
  rmSync(dir, { recursive: true, force: true });
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  const t0 = Date.now();
  let javacOut = "";
  try { javacOut = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; throw new Error(`javac failed on ${lane.version}:\n${(x.stderr ?? "") + (x.stdout ?? "")}`.slice(0, 12000)); }
  const javacMs = Date.now() - t0;
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jar = (out: string) => { execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", out, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]); return sha(readFileSync(out)); };
  const jarPath = path.join(dir, `${PLUGIN}-${lane.version}.jar`);
  const h1 = jar(jarPath), h2 = jar(path.join(dir, "again.jar"));
  return { dir, classes, sources: sources.length, classFiles: entries.filter((e) => e.endsWith(".class")).length, javacMs, javacWarnings: (javacOut.match(/warning:/g) ?? []).length, javacOut: javacOut.slice(0, 3000), jarPath, jarSha256: h1, reproducible: h1 === h2, jarBytes: readFileSync(jarPath).length };
}

function scan(b: ReturnType<typeof build>, lane: (typeof ALL_LANES)[number]) {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
  const oldPath = process.env.PATH;
  process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
  try {
    const bytecode = S.scanBytecode(b.classes, { profile: "strict" });
    const src = walk(path.join(b.dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(path.join(b.dir, "ws"), abs) }));
    const source = S.scanSource(src, { profile: "strict" });
    const all = [...bytecode, ...source] as { severity: string; rule: string; where: string; message: string }[];
    return { profile: "strict", blocks: all.filter((f) => f.severity === "block").length, warnings: all.filter((f) => f.severity === "warn").length, findings: all.map((f) => `${f.severity} ${f.rule} ${f.where}: ${f.message}`).slice(0, 20) };
  } finally { process.env.PATH = oldPath; }
}

function harvest(runId: string | null) {
  const out: Record<string, unknown> = {};
  if (!runId || !/^[A-Za-z0-9_-]+$/.test(runId)) return out;
  const dir = path.join(TF, "runs", runId);
  const log = path.join(dir, "logs/latest.log");
  const lines = existsSync(log) ? readFileSync(log, "utf8").split("\n") : [];
  const motion = lines.filter((l) => /\[motion\]/.test(l)).map((l) => l.replace(/^.*\[motion\] /, "").slice(0, 200));
  out.motionLog = motion.slice(0, 120);
  out.pluginLog = lines.filter((l) => new RegExp(PLUGIN, "i").test(l) && !/Preparing|\[motion\]/.test(l)).map((l) => l.slice(0, 300)).slice(0, 30);
  out.pluginErrorLines = lines.filter((l) => /\/(ERROR|FATAL)\]|Exception/.test(l) && new RegExp(PLUGIN, "i").test(l)).map((l) => l.slice(0, 300)).slice(0, 20);
  out.sandboxNoiseLines = lines.filter((l) => /\/(ERROR|FATAL)\]/.test(l) && !new RegExp(PLUGIN, "i").test(l)).length;
  rmSync(dir, { recursive: true, force: true });
  return out;
}

/** Log checks: the server's own debug lines must show the transitions and after-durations the TS lowering predicts. */
function logChecks(log: string[], c: ModCompileOk): { id: string; status: "pass" | "fail"; evidence: string[] }[] {
  const out: { id: string; status: "pass" | "fail"; evidence: string[] }[] = [];
  const tick = (re: RegExp) => { const l = log.find((x) => re.test(x)); const m = l ? /t(\d+) /.exec(l) : null; return { line: l ?? null, t: m ? Number(m[1]) : null }; };
  const door = validateMotionDesign(fx("lab_door"), { version: "1.21.11", namespace: NS });
  const openLen = door.ok ? door.program.clips.find((x) => x.name === "open")!.length : -1;
  const a = tick(/^#1 t\d+ closed->opening \(toggle\)/), b = tick(/^#1 t\d+ opening->open \(after\)/);
  out.push({ id: "log-door-after-duration", status: a.t !== null && b.t !== null && b.t - a.t === openLen ? "pass" : "fail", evidence: [`expected ${openLen} ticks (TS lowering)`, a.line ?? "no toggle line", b.line ?? "no after line"] });
  const s = log.find((x) => /^#1 t\d+ sound minecraft:block\.wooden_door\.open$/.test(x));
  out.push({ id: "log-door-open-sound-cue", status: s ? "pass" : "fail", evidence: [s ?? "no door sound cue line"] });
  const fires = log.filter((x) => /^#2 t\d+ (idle->fire|idle->fire_last) \(fire\)/.test(x));
  out.push({ id: "log-pistol-three-shots", status: fires.length === 3 ? "pass" : "fail", evidence: fires.slice(0, 4) });
  const shots = log.filter((x) => /^#2 t\d+ sound minecraft:entity\.firework_rocket\.blast$/.test(x));
  out.push({ id: "log-pistol-shot-cues", status: shots.length === 3 ? "pass" : "fail", evidence: shots.slice(0, 4) });
  const rl = tick(/^#2 t\d+ empty->reload_empty \(reload\)/), ck = tick(/^#2 t\d+ idle->cock \(auto_cock\)/);
  const pistol = validateMotionDesign(fx("lab_pistol"), { version: "1.21.11", namespace: NS });
  const relLen = pistol.ok ? pistol.program.clips.find((x) => x.name === "reload_empty")!.length : -1;
  out.push({ id: "log-pistol-reload-then-auto-cock", status: rl.t !== null && ck.t !== null && ck.t - rl.t === relLen ? "pass" : "fail", evidence: [`expected ${relLen} ticks`, rl.line ?? "no reload line", ck.line ?? "no cock line"] });
  const dry = log.find((x) => /^#2 t\d+ empty->dry \(fire\)/.test(x));
  out.push({ id: "log-pistol-dry-fire-when-empty", status: dry ? "pass" : "fail", evidence: [dry ?? "no dry line"] });
  const fire = log.find((x) => /^#3 t\d+ particle (flame|smoke|crit) x\d+$/.test(x)) ?? log.find((x) => /^#3 t\d+ sound minecraft:block\.fire\.ambient$/.test(x));
  out.push({ id: "log-fire-effect-cues", status: fire ? "pass" : "fail", evidence: [fire ?? "no fire cue line"] });
  void c;
  return out;
}

function expectedTexts() {
  const door = validateMotionDesign(fx("lab_door"), { version: "1.21.11", namespace: NS });
  const pistol = validateMotionDesign(fx("lab_pistol"), { version: "1.21.11", namespace: NS });
  if (!door.ok || !pistol.ok) throw new Error("fixtures do not validate");
  const ajar = door.program.clips.find((c) => c.name === "ajar")!, shut = door.program.clips.find((c) => c.name === "shut")!;
  const sim = new McMotionSim(pistol.program, 2);
  sim.run(2); for (const e of ["fire", "fire", "fire"]) { sim.send(e); sim.run(8); }
  return {
    doorShutP1: `p1 ${partText(partTargetAt(shut, 1, 0)!, 1)}`,
    doorOpenP1: `p1 ${partText(partTargetAt(ajar, 1, 0)!, 1)}`,
    pistolEmpty: sim.stateText("lab_pistol")[0].replace(/ age=\d+/, ""),
    check: (id: string, p: typeof door.program) => `${id} program: parts=${p.stats.parts} clips=${p.clips.length} segments=${p.stats.segments} cues=${p.stats.cues} states=${p.machine.states.length} transitions=${p.machine.transitions.length}`,
    door: door.program, pistol: pistol.program,
  };
}

function brokenRejected(lane: string) {
  const ts = validateMotionDesign(fx("broken_hinge"), { version: lane, namespace: NS });
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const DZ = require(path.join(ROOT, "services/modbuilder/designer-spec.js"));
  const svc = DZ.validateMotionDesign(fx("broken_hinge"), { version: lane, namespace: NS });
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const DS = require(path.join(ROOT, "services/modbuilder/designs.js"));
  const ws = mkdtempSync(path.join(os.tmpdir(), "motion-ws-"));
  mkdirSync(path.join(ws, "assets/designs"), { recursive: true });
  writeFileSync(path.join(ws, "assets/designs/broken_hinge.json"), JSON.stringify(fx("broken_hinge")));
  writeFileSync(path.join(ws, "assets/designs/lab_door.json"), JSON.stringify(fx("lab_door")));
  const chk = DS.checkWorkspaceDesigns(ws, { namespace: NS, mcVersion: lane });
  rmSync(ws, { recursive: true, force: true });
  const comp = compileMod([fx("lab_door"), fx("broken_hinge")], { version: lane, namespace: NS, pluginName: PLUGIN });
  const codes = ts.ok ? [] : ts.errors.map((e) => e.code);
  return {
    ok: !ts.ok && !svc.ok && !comp.ok && chk.problems.some((p: string) => /broken_hinge/.test(p)) && chk.results.find((r: { name: string; ok: boolean }) => r.name === "lab_door")?.ok === true,
    tsErrors: ts.ok ? [] : ts.errors.map((e) => `${e.path}: ${e.code}: ${e.message}`).slice(0, 8),
    serviceBundleRejected: !svc.ok, compileRejected: !comp.ok, workspaceProblems: chk.problems.slice(0, 6), goodFileStillOk: chk.results.find((r: { name: string; ok: boolean }) => r.name === "lab_door")?.ok === true,
    codes,
  };
}

async function main() {
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", realClient: false, bot: false, aiModel: "none (motion designs are hand-written fixtures; no model call)", fixtures: ["lab_door (motion:door_hinge)", "lab_pistol (motion:gun_reload, mag 3)", "lab_fire (effect:fire)", "broken_hinge (must be refused)"], lanes: [] as unknown[] };
  mkdirSync(RUN, { recursive: true });
  const ex = expectedTexts();
  for (const lane of LANES) {
    const L: Record<string, unknown> = { version: lane.version, jdk: lane.release };
    (res.lanes as unknown[]).push(L);
    L.brokenSpec = brokenRejected(lane.version);
    const c = compileMod(DESIGNS(), { version: lane.version, namespace: NS, pluginName: PLUGIN });
    if (!c.ok) { L.compile = { ok: false, errors: c.errors }; console.log(JSON.stringify(c.errors, null, 1)); continue; }
    L.compile = { ok: true, hash: c.hash, files: c.files.length, counts: c.counts, motionPrograms: c.motionCompile?.programs, warnings: c.warnings.map((w) => w.code) };
    const b = build(c, lane);
    L.javac = { ok: true, sources: b.sources, classFiles: b.classFiles, ms: b.javacMs, warnings: b.javacWarnings, output: b.javacOut };
    L.jar = { sha256: b.jarSha256, bytes: b.jarBytes, reproducible: b.reproducible };
    L.scan = scan(b, lane);
    console.log(`${lane.version}: javac ok (${b.sources} sources, ${b.javacWarnings} warnings), jar reproducible=${b.reproducible}, scan blocks=${(L.scan as { blocks: number }).blocks} warnings=${(L.scan as { warnings: number }).warnings}`);
    if (b.javacWarnings) console.log(b.javacOut);
    if (process.argv.includes("--javac-only")) continue;
    const tag = (n: number, p?: number) => `${NS}.mi${n}${p !== undefined ? `p${p}` : ""}`;
    const rcon: RconCheck[] = [
      { id: "plugins", command: "plugins", expect: [PLUGIN] },
      { id: "motion-list", command: `${CMD} motion list`, expect: ["lab_door: Lab door parts=3 clips=4 states=4 live=0/4", "lab_pistol: Pistol on a stand parts=6 clips=9 states=9 live=0/2", "lab_fire: Campfire flames parts=0 clips=1 states=2 live=0/2"] },
      { id: "motion-check-door", command: `${CMD} motion check lab_door`, expect: [ex.check("lab_door", ex.door), "events=close,closed,open,opened,toggle"] },
      { id: "motion-check-pistol", command: `${CMD} motion check lab_pistol`, expect: [ex.check("lab_pistol", ex.pistol)] },
      { id: "forceload", command: "forceload add -16 -16 16 16", required: false },
      { id: "debug-on", command: `${CMD} motion debug on`, expect: ["Motion debug log on"] },
      { id: "spawn-door", command: `${CMD} motion spawn lab_door world 0 -60 0 0`, expect: [`Spawned lab_door #1 at world 0.5 -60 0.5 yaw 0 (3 parts, tag ${tag(1)})`] },
      { id: "door-entities", waitMs: 300, command: `execute if entity @e[type=block_display,tag=${tag(1)}]`, expect: ["Test passed, count: 3"] },
      { id: "door-interaction", command: `execute if entity @e[type=interaction,tag=${tag(1)}]`, expect: ["Test passed, count: 1"] },
      { id: "door-nbt-transformation", command: `data get entity @e[tag=${tag(1, 1)},limit=1] transformation`, expect: ["left_rotation", "translation", "scale"] },
      { id: "door-state-closed", command: `${CMD} motion state 1`, expect: ["#1 lab_door state=closed clip=shut", ex.doorShutP1] },
      { id: "door-toggle", command: `${CMD} motion event 1 toggle`, expect: ["Queued toggle for 1 prop"] },
      { id: "door-state-open", waitMs: 2000, command: `${CMD} motion state 1`, expect: ["#1 lab_door state=open clip=ajar", ex.doorOpenP1] },
      { id: "door-nbt-interpolation", command: `data get entity @e[tag=${tag(1, 1)},limit=1] interpolation_duration`, expect: ["has the following entity data: 1"] },
      { id: "door-toggle-close", command: `${CMD} motion event lab_door toggle`, expect: ["Queued toggle for 1 prop"] },
      { id: "door-state-closed-again", waitMs: 1500, command: `${CMD} motion state 1`, expect: ["#1 lab_door state=closed clip=shut", ex.doorShutP1] },
      { id: "spawn-pistol", command: `${CMD} motion spawn lab_pistol world 3 -60 0 90`, expect: [`Spawned lab_pistol #2 at world 3.5 -60 0.5 yaw 90 (6 parts, tag ${tag(2)})`] },
      { id: "pistol-fire-1", waitMs: 300, command: `${CMD} motion event 2 fire`, expect: ["Queued fire"] },
      { id: "pistol-fire-2", waitMs: 500, command: `${CMD} motion event 2 fire`, expect: ["Queued fire"] },
      { id: "pistol-fire-3", waitMs: 500, command: `${CMD} motion event 2 fire`, expect: ["Queued fire"] },
      { id: "pistol-state-empty", waitMs: 600, command: `${CMD} motion state 2`, expect: [ex.pistolEmpty] },
      { id: "pistol-dry-fire", command: `${CMD} motion event 2 fire`, expect: ["Queued fire"] },
      { id: "pistol-reload", waitMs: 500, command: `${CMD} motion event 2 reload`, expect: ["Queued reload"] },
      { id: "pistol-state-reloaded", waitMs: 3000, command: `${CMD} motion state 2`, expect: ["#2 lab_pistol state=idle clip=idle", "ammo=3 chambered=1"] },
      { id: "spawn-fire", command: `${CMD} motion spawn lab_fire world -3 -60 0 0`, expect: [`Spawned lab_fire #3 at world -2.5 -60 0.5 yaw 0 (0 parts, tag ${tag(3)})`] },
      { id: "fire-play", waitMs: 200, command: `${CMD} motion event 3 play`, expect: ["Queued play for 1 prop"] },
      { id: "fire-state-play", waitMs: 1000, command: `${CMD} motion state 3`, expect: ["#3 lab_fire state=play clip=play"] },
      { id: "cap-per-motion", command: `${CMD} motion spawn lab_pistol world 6 -60 0 0`, expect: ["Spawned lab_pistol #4"] },
      { id: "cap-per-motion-refused", command: `${CMD} motion spawn lab_pistol world 9 -60 0 0`, expect: ["lab_pistol already has 2 live props (motions.lab_pistol.max_instances)"] },
      { id: "event-unknown-prop", command: `${CMD} motion event 99 toggle`, expect: ["No live prop matches 99"] },
      { id: "spawn-unknown-motion", command: `${CMD} motion spawn car_kart world 0 -60 0`, expect: ["Usage: /motionlab motion spawn <id>"] },
      { id: "spawn-console-usage", command: `${CMD} motion spawn lab_door`, expect: ["Usage from the console"] },
      { id: "ignored-event-logged", command: `${CMD} motion event 1 explode`, expect: ["Queued explode for 1 prop"] },
      { id: "item-command-still-works", waitMs: 200, command: `${CMD} list`, expect: [] },
      { id: "despawn-all", command: `${CMD} motion despawn all`, expect: ["Removed 4 props"] },
      { id: "no-entities-left", waitMs: 300, command: `execute if entity @e[tag=${NS}.motion]`, expect: ["Test failed"] },
      { id: "forceload-off", command: "forceload remove -16 -16 16 16", required: false },
    ];
    const f = await fly({ version: lane.version, plugins: [{ localPath: b.jarPath, sha256: b.jarSha256 }], rcon, keepDir: true }, `flight ${lane.version}`);
    const h = harvest(f.report.runId ?? null);
    const lc = logChecks((h.motionLog as string[]) ?? [], c);
    L.flight = {
      status: f.report.status, overall: f.summary.overall, success: f.summary.success, line: describeSummary(f.summary), bootMs: f.report.bootMs, peakRssMb: f.report.peakRssKb ? Math.round(f.report.peakRssKb / 1024) : null, paper: f.report.engine?.paper, jdkVersion: f.report.engine?.jdkVersion,
      checks: f.report.checks.map((x) => ({ id: x.id, status: x.status, evidence: x.evidence.slice(0, 8) })),
      logChecks: lc, ...h,
    };
    const rconChecks = f.report.checks.filter((x) => x.id.startsWith("rcon"));
    console.log(`flight ${lane.version}: ${describeSummary(f.summary)}; log checks ${lc.filter((x) => x.status === "pass").length}/${lc.length}; rcon ${rconChecks.length}`);
    for (const x of f.report.checks) if (x.status !== "pass") console.log(`  ${x.id}: ${x.status}\n    ${x.evidence.slice(0, 20).join("\n    ")}`);
    for (const x of lc) if (x.status !== "pass") console.log(`  ${x.id}: ${x.status}\n    ${x.evidence.join("\n    ")}`);
  }
  res.leftovers = { runsDir: existsSync(path.join(TF, "runs")) ? readdirSync(path.join(TF, "runs")).length : 0 };
  const out = arg("--out");
  if (out) { mkdirSync(path.dirname(out), { recursive: true }); writeFileSync(out, JSON.stringify(res, null, 1)); }
  console.log(JSON.stringify(res, null, 1).slice(0, 2500));
  rmSync(RUN, { recursive: true, force: true });
}

main().catch((e) => { console.error(e); process.exit(1); });

