// Cyrus motion core: a HEADLESS, DETERMINISTIC preview renderer (software rasteriser, no GPU, no browser). It draws a
// simulated frame (lib/cyrus/motion/simulate.ts) of any MotionSpec: rig proxy boxes with flat lighting and a z-buffer,
// the analytic particles, a glow where a brightness track is lit, a ground grid; and lays frames out as CONTACT SHEETS
// with tick / state labels and a cue timeline, so the owner and reviewers can SEE a motion without a game client.
// Same input = same pixels (golden tested). It approximates what a game shows (lighting, particle looks and the
// client's interpolation differ); it is not a substitute for a real-client check. Pure (PNG encoding: ./preview-png.ts).
import { apply, mul, Sc, T, hexToRgb, type M4, type Vec3 } from "./math";
import type { SimFrame } from "./simulate";
import { worldMatrices, nodePositions, type LiveParticle, type Pose } from "./sample";
import type { MotionSpec } from "./spec";

export type Raster = { w: number; h: number; px: Uint8ClampedArray };
type ZRaster = Raster & { z: Float32Array };

const newRaster = (w: number, h: number): ZRaster => ({ w, h, px: new Uint8ClampedArray(w * h * 4), z: new Float32Array(w * h).fill(Infinity) });

// ------------------------------------------------------------------------------------------------------ colours
export const THEME = {
  dark: { bg0: "#0b1020", bg1: "#141a30", grid0: "#1b2340", grid1: "#202a4c", text: "#e6e9f5", dim: "#8d96b8", accent: "#8b5cf6", now: "#22d3ee", sound: "#22d3ee", particle: "#f59e0b", event: "#a78bfa", state: "#e6e9f5", panel: "#0f1528", line: "#2a3358" },
  light: { bg0: "#f4f5fb", bg1: "#e8eaf5", grid0: "#dcdff0", grid1: "#d2d6ea", text: "#151a2e", dim: "#5d6585", accent: "#6d28d9", now: "#0891b2", sound: "#0891b2", particle: "#d97706", event: "#7c3aed", state: "#151a2e", panel: "#ffffff", line: "#c9cee6" },
} as const;
export type ThemeName = keyof typeof THEME;

function put(r: Raster, x: number, y: number, c: Vec3, a = 1) {
  if (x < 0 || y < 0 || x >= r.w || y >= r.h) return;
  const i = (y * r.w + x) * 4;
  r.px[i] = r.px[i] + (c[0] - r.px[i]) * a; r.px[i + 1] = r.px[i + 1] + (c[1] - r.px[i + 1]) * a; r.px[i + 2] = r.px[i + 2] + (c[2] - r.px[i + 2]) * a; r.px[i + 3] = 255;
}
function add(r: Raster, x: number, y: number, c: Vec3, a: number) {
  if (x < 0 || y < 0 || x >= r.w || y >= r.h) return;
  const i = (y * r.w + x) * 4;
  r.px[i] = Math.min(255, r.px[i] + c[0] * a); r.px[i + 1] = Math.min(255, r.px[i + 1] + c[1] * a); r.px[i + 2] = Math.min(255, r.px[i + 2] + c[2] * a); r.px[i + 3] = 255;
}
export function fillRect(r: Raster, x0: number, y0: number, w: number, h: number, hex: string, a = 1) {
  const c = hexToRgb(hex);
  for (let y = Math.max(0, y0); y < Math.min(r.h, y0 + h); y++) for (let x = Math.max(0, x0); x < Math.min(r.w, x0 + w); x++) put(r, x, y, c, a);
}

// ------------------------------------------------------------------------------------------------- tiny font
// 3x5 glyphs (rows top->bottom, 3 bits each). Uppercase letters, digits and a few symbols; enough for labels.
const G: Record<string, number[]> = {
  "0": [7, 5, 5, 5, 7], "1": [2, 6, 2, 2, 7], "2": [7, 1, 7, 4, 7], "3": [7, 1, 7, 1, 7], "4": [5, 5, 7, 1, 1], "5": [7, 4, 7, 1, 7], "6": [7, 4, 7, 5, 7], "7": [7, 1, 1, 2, 2], "8": [7, 5, 7, 5, 7], "9": [7, 5, 7, 1, 7],
  A: [2, 5, 7, 5, 5], B: [6, 5, 6, 5, 6], C: [3, 4, 4, 4, 3], D: [6, 5, 5, 5, 6], E: [7, 4, 6, 4, 7], F: [7, 4, 6, 4, 4], G: [3, 4, 5, 5, 3], H: [5, 5, 7, 5, 5], I: [7, 2, 2, 2, 7], J: [1, 1, 1, 5, 2], K: [5, 5, 6, 5, 5], L: [4, 4, 4, 4, 7], M: [5, 7, 7, 5, 5],
  N: [6, 5, 5, 5, 5], O: [2, 5, 5, 5, 2], P: [6, 5, 6, 4, 4], Q: [2, 5, 5, 6, 3], R: [6, 5, 6, 5, 5], S: [3, 4, 2, 1, 6], T: [7, 2, 2, 2, 2], U: [5, 5, 5, 5, 7], V: [5, 5, 5, 5, 2], W: [5, 5, 7, 7, 5], X: [5, 5, 2, 5, 5], Y: [5, 5, 2, 2, 2], Z: [7, 1, 2, 4, 7],
  "-": [0, 0, 7, 0, 0], ":": [0, 2, 0, 2, 0], ".": [0, 0, 0, 0, 2], "/": [1, 1, 2, 4, 4], "#": [5, 7, 5, 7, 5], "=": [0, 7, 0, 7, 0], ">": [4, 2, 1, 2, 4], "_": [0, 0, 0, 0, 7], "(": [1, 2, 2, 2, 1], ")": [4, 2, 2, 2, 4], "+": [0, 2, 7, 2, 0], ",": [0, 0, 0, 2, 4], " ": [0, 0, 0, 0, 0],
};
export function text(r: Raster, x: number, y: number, s: string, hex: string, scale = 2): number {
  const c = hexToRgb(hex);
  let cx = x;
  for (const ch of s.toUpperCase()) {
    const g = G[ch] ?? G[" "];
    for (let row = 0; row < 5; row++) for (let col = 0; col < 3; col++) if (g[row] & (4 >> col)) for (let dy = 0; dy < scale; dy++) for (let dx = 0; dx < scale; dx++) put(r, cx + col * scale + dx, y + row * scale + dy, c);
    cx += 4 * scale;
  }
  return cx - x;
}

// ---------------------------------------------------------------------------------------------------- camera
export type Camera = { eye: Vec3; target: Vec3; fov: number };
type View = { project: (p: Vec3) => { x: number; y: number; z: number } | null; light: Vec3 };
function view(cam: Camera, w: number, h: number): View {
  const f = [cam.target[0] - cam.eye[0], cam.target[1] - cam.eye[1], cam.target[2] - cam.eye[2]];
  const fl = Math.hypot(f[0], f[1], f[2]); const fw: Vec3 = [f[0] / fl, f[1] / fl, f[2] / fl];
  const up: Vec3 = [0, 1, 0];
  const rx: Vec3 = [fw[1] * up[2] - fw[2] * up[1], fw[2] * up[0] - fw[0] * up[2], fw[0] * up[1] - fw[1] * up[0]];
  const rl = Math.hypot(...rx); rx[0] /= rl; rx[1] /= rl; rx[2] /= rl;
  const uy: Vec3 = [rx[1] * fw[2] - rx[2] * fw[1], rx[2] * fw[0] - rx[0] * fw[2], rx[0] * fw[1] - rx[1] * fw[0]];
  const focal = (h / 2) / Math.tan((cam.fov * Math.PI) / 360);
  return {
    project: (p) => {
      const d = [p[0] - cam.eye[0], p[1] - cam.eye[1], p[2] - cam.eye[2]];
      const z = d[0] * fw[0] + d[1] * fw[1] + d[2] * fw[2];
      if (z < 0.05) return null;
      const x = d[0] * rx[0] + d[1] * rx[1] + d[2] * rx[2], y = d[0] * uy[0] + d[1] * uy[1] + d[2] * uy[2];
      return { x: w / 2 + (x * focal) / z, y: h / 2 - (y * focal) / z, z };
    },
    light: (() => { const l = [-0.45, 0.85, 0.35]; const n = Math.hypot(...l); return [l[0] / n, l[1] / n, l[2] / n] as Vec3; })(),
  };
}

/** A 3/4 view camera that frames the rig's rest boxes (and room for particles above / in front). */
export function autoCamera(spec: MotionSpec, o: { yaw?: number; pitch?: number; pad?: number; extra?: Vec3[] } = {}): Camera {
  const pts: Vec3[] = [...(o.extra ?? [])];
  const w = worldMatrices(spec, { nodes: {}, material: {} });
  for (const n of spec.rig.nodes) {
    const m = w[n.name];
    if (n.proxy) { const s = n.proxy.size, of = n.proxy.offset ?? [0, 0, 0]; for (const x of [-0.5, 0.5]) for (const y of [-0.5, 0.5]) for (const z of [-0.5, 0.5]) pts.push(apply(m, [n.pivot[0] + of[0] + x * s[0], n.pivot[1] + of[1] + y * s[1], n.pivot[2] + of[2] + z * s[2]])); }
    else pts.push(apply(m, n.pivot));
  }
  if (!pts.length) pts.push([0, 0, 0]);
  const lo = [0, 1, 2].map((k) => Math.min(...pts.map((p) => p[k]))), hi = [0, 1, 2].map((k) => Math.max(...pts.map((p) => p[k])));
  const c: Vec3 = [(lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2, (lo[2] + hi[2]) / 2];
  const rad = Math.max(0.35, Math.hypot(hi[0] - lo[0], hi[1] - lo[1], hi[2] - lo[2]) / 2) * (o.pad ?? 1.25);
  const yaw = ((o.yaw ?? 35) * Math.PI) / 180, pitch = ((o.pitch ?? 22) * Math.PI) / 180, fov = 34;
  const dist = rad / Math.sin((fov * Math.PI) / 360);
  return { eye: [c[0] + dist * Math.cos(pitch) * Math.sin(yaw), c[1] + dist * Math.sin(pitch), c[2] + dist * Math.cos(pitch) * Math.cos(yaw)], target: c, fov };
}

// ----------------------------------------------------------------------------------------------- rasterising
function tri(r: ZRaster, a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }, c: { x: number; y: number; z: number }, col: Vec3) {
  const minX = Math.max(0, Math.floor(Math.min(a.x, b.x, c.x))), maxX = Math.min(r.w - 1, Math.ceil(Math.max(a.x, b.x, c.x)));
  const minY = Math.max(0, Math.floor(Math.min(a.y, b.y, c.y))), maxY = Math.min(r.h - 1, Math.ceil(Math.max(a.y, b.y, c.y)));
  const area = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
  if (Math.abs(area) < 1e-9) return;
  for (let y = minY; y <= maxY; y++) for (let x = minX; x <= maxX; x++) {
    const px = x + 0.5, py = y + 0.5;
    const w0 = ((b.x - px) * (c.y - py) - (b.y - py) * (c.x - px)) / area;
    const w1 = ((c.x - px) * (a.y - py) - (c.y - py) * (a.x - px)) / area;
    const w2 = 1 - w0 - w1;
    if (w0 < 0 || w1 < 0 || w2 < 0) continue;
    const z = w0 * a.z + w1 * b.z + w2 * c.z;
    const i = y * r.w + x;
    if (z >= r.z[i]) continue;
    r.z[i] = z;
    put(r, x, y, col);
  }
}
const FACES = [[0, 1, 3, 2, [-1, 0, 0]], [4, 6, 7, 5, [1, 0, 0]], [0, 4, 5, 1, [0, -1, 0]], [2, 3, 7, 6, [0, 1, 0]], [0, 2, 6, 4, [0, 0, -1]], [1, 5, 7, 3, [0, 0, 1]]] as const;

function drawBox(r: ZRaster, v: View, m: M4, color: string, glow: number) {
  const corners: Vec3[] = [];
  for (const x of [0, 1]) for (const y of [0, 1]) for (const z of [0, 1]) corners.push(apply(m, [x, y, z]));
  const P = corners.map(v.project);
  if (P.some((p) => !p)) return;
  const base = hexToRgb(color);
  for (const [i0, i1, i2, i3, nl] of FACES) {
    const n = [0, 1, 2].map((k) => m[k] * nl[0] + m[4 + k] * nl[1] + m[8 + k] * nl[2]);
    const nn = Math.hypot(n[0], n[1], n[2]) || 1;
    const lit = Math.max(0, (n[0] * v.light[0] + n[1] * v.light[1] + n[2] * v.light[2]) / nn);
    const k = Math.min(1.25, 0.42 + 0.6 * lit + glow * 0.5);
    const col: Vec3 = [Math.min(255, base[0] * k + glow * 60), Math.min(255, base[1] * k + glow * 50), Math.min(255, base[2] * k + glow * 30)];
    tri(r, P[i0]!, P[i1]!, P[i2]!, col);
    tri(r, P[i0]!, P[i2]!, P[i3]!, col);
  }
}

function drawGround(r: ZRaster, v: View, th: (typeof THEME)[ThemeName], center: Vec3, size = 3) {
  const step = 0.5;
  for (let gx = -size; gx < size; gx += step) for (let gz = -size; gz < size; gz += step) {
    const x0 = Math.round(center[0] / step) * step + gx, z0 = Math.round(center[2] / step) * step + gz;
    const q = [[x0, 0, z0], [x0 + step, 0, z0], [x0 + step, 0, z0 + step], [x0, 0, z0 + step]].map((p) => v.project(p as Vec3));
    if (q.some((p) => !p)) continue;
    const odd = (Math.round(x0 / step) + Math.round(z0 / step)) & 1;
    const fade = Math.max(0, 1 - Math.hypot(gx + step / 2, gz + step / 2) / size);
    const g0 = hexToRgb(odd ? th.grid0 : th.grid1), b0 = hexToRgb(th.bg1);
    const col: Vec3 = [b0[0] + (g0[0] - b0[0]) * fade, b0[1] + (g0[1] - b0[1]) * fade, b0[2] + (g0[2] - b0[2]) * fade];
    // the ground sits behind everything above it: push its depth slightly back
    const qq = q.map((p) => ({ ...p!, z: p!.z + 0.002 }));
    tri(r, qq[0], qq[1], qq[2], col); tri(r, qq[0], qq[2], qq[3], col);
  }
}

const ADDITIVE = new Set(["flame", "flash", "spark", "glow"]);
function drawParticles(r: ZRaster, v: View, list: LiveParticle[], cam: Camera) {
  const focal = (r.h / 2) / Math.tan((cam.fov * Math.PI) / 360);
  // far to near, so normal-blended smoke layers correctly; ties broken by input order (stable)
  const proj = list.map((p, i) => ({ p, i, s: v.project(p.pos) })).filter((x) => x.s).sort((a, b) => b.s!.z - a.s!.z || a.i - b.i);
  for (const { p, s } of proj) {
    const rad = Math.max(0.8, (p.size * focal) / s!.z / 2);
    const fade = 1 - p.age / p.life;
    const c = hexToRgb(p.color);
    const addMode = ADDITIVE.has(p.sprite);
    for (let y = Math.floor(s!.y - rad); y <= Math.ceil(s!.y + rad); y++) for (let x = Math.floor(s!.x - rad); x <= Math.ceil(s!.x + rad); x++) {
      if (x < 0 || y < 0 || x >= r.w || y >= r.h) continue;
      const d = Math.hypot(x + 0.5 - s!.x, y + 0.5 - s!.y) / rad;
      if (d > 1) continue;
      if (s!.z > r.z[y * r.w + x]) continue;
      const a = (1 - d * d) * fade * (addMode ? 0.9 : p.sprite === "smoke" ? 0.35 : 0.8);
      if (addMode) add(r, x, y, c, a); else put(r, x, y, c, a);
    }
  }
}

/** Render one frame of a spec (pose + particles) into a w x h raster. */
export function renderFrame(spec: MotionSpec, pose: Pose, particles: LiveParticle[], o: { w: number; h: number; camera: Camera; theme?: ThemeName }): Raster {
  const th = THEME[o.theme ?? "dark"];
  const r = newRaster(o.w, o.h);
  const b0 = hexToRgb(th.bg0), b1 = hexToRgb(th.bg1);
  for (let y = 0; y < o.h; y++) { const f = y / o.h; const c: Vec3 = [b0[0] + (b1[0] - b0[0]) * f, b0[1] + (b1[1] - b0[1]) * f, b0[2] + (b1[2] - b0[2]) * f]; for (let x = 0; x < o.w; x++) put(r, x, y, c); }
  const v = view(o.camera, o.w, o.h);
  drawGround(r, v, th, o.camera.target);
  const w = worldMatrices(spec, pose);
  for (const n of spec.rig.nodes) {
    if (!n.proxy) continue;
    const s = n.proxy.size, of = n.proxy.offset ?? [0, 0, 0];
    const box = mul(T(n.pivot[0] + of[0] - s[0] / 2, n.pivot[1] + of[1] - s[1] / 2, n.pivot[2] + of[2] - s[2] / 2), Sc(Math.max(1e-3, s[0]), Math.max(1e-3, s[1]), Math.max(1e-3, s[2])));
    const glow = Math.max(0, Math.min(1, ((pose.material[n.name]?.brightness ?? 0) / 15) + (pose.material[n.name]?.emissive ?? 0)));
    drawBox(r, v, mul(w[n.name], box), n.proxy.color, glow);
  }
  // lit emitters (brightness on a node with no box): a glow halo at the node
  const pos = nodePositions(spec, pose);
  const halos: LiveParticle[] = [];
