// Cyrus motion core: a HEADLESS, DETERMINISTIC preview renderer (software rasteriser, no GPU, no browser). It draws a
// simulated frame (lib/cyrus/motion/simulate.ts) of any MotionSpec: rig proxy boxes with flat lighting and a z-buffer,
// the analytic particles, a glow where a brightness track is lit, a ground grid; and lays frames out as CONTACT SHEETS
// with tick / state labels and a cue timeline, so the owner and reviewers can SEE a motion without a game client.
// Same input = same pixels (golden tested). It approximates what a game shows (lighting, particle looks and the
// client's interpolation differ); it is not a substitute for a real-client check. Pure (PNG encoding: ./preview-png.ts).
import { apply, mul, Sc, T, hexToRgb, type M4, type Vec3 } from "./math";
import type { SimFrame } from "./simulate";
import { worldMatrices, nodePositions, type LiveParticle, type Pose } from "./sample";
import type { MotionSpec } from "./spec";

export type Raster = { w: number; h: number; px: Uint8ClampedArray };
type ZRaster = Raster & { z: Float32Array };

const newRaster = (w: number, h: number): ZRaster => ({ w, h, px: new Uint8ClampedArray(w * h * 4), z: new Float32Array(w * h).fill(Infinity) });

// ------------------------------------------------------------------------------------------------------ colours
export const THEME = {
  dark: { bg0: "#0b1020", bg1: "#141a30", grid0: "#1b2340", grid1: "#202a4c", text: "#e6e9f5", dim: "#8d96b8", accent: "#8b5cf6", now: "#22d3ee", sound: "#22d3ee", particle: "#f59e0b", event: "#a78bfa", state: "#e6e9f5", panel: "#0f1528", line: "#2a3358" },
  light: { bg0: "#f4f5fb", bg1: "#e8eaf5", grid0: "#dcdff0", grid1: "#d2d6ea", text: "#151a2e", dim: "#5d6585", accent: "#6d28d9", now: "#0891b2", sound: "#0891b2", particle: "#d97706", event: "#7c3aed", state: "#151a2e", panel: "#ffffff", line: "#c9cee6" },
} as const;
export type ThemeName = keyof typeof THEME;

function put(r: Raster, x: number, y: number, c: Vec3, a = 1) {
  if (x < 0 || y < 0 || x >= r.w || y >= r.h) return;
