  r.px[i] = r.px[i] + (c[0] - r.px[i]) * a; r.px[i + 1] = r.px[i + 1] + (c[1] - r.px[i + 1]) * a; r.px[i + 2] = r.px[i + 2] + (c[2] - r.px[i + 2]) * a; r.px[i + 3] = 255;
}
function add(r: Raster, x: number, y: number, c: Vec3, a: number) {
  if (x < 0 || y < 0 || x >= r.w || y >= r.h) return;
  const i = (y * r.w + x) * 4;
  r.px[i] = Math.min(255, r.px[i] + c[0] * a); r.px[i + 1] = Math.min(255, r.px[i + 1] + c[1] * a); r.px[i + 2] = Math.min(255, r.px[i + 2] + c[2] * a); r.px[i + 3] = 255;
}
export function fillRect(r: Raster, x0: number, y0: number, w: number, h: number, hex: string, a = 1) {
  const c = hexToRgb(hex);
  for (let y = Math.max(0, y0); y < Math.min(r.h, y0 + h); y++) for (let x = Math.max(0, x0); x < Math.min(r.w, x0 + w); x++) put(r, x, y, c, a);
}

// ------------------------------------------------------------------------------------------------- tiny font
// 3x5 glyphs (rows top->bottom, 3 bits each). Uppercase letters, digits and a few symbols; enough for labels.
const G: Record<string, number[]> = {
  "0": [7, 5, 5, 5, 7], "1": [2, 6, 2, 2, 7], "2": [7, 1, 7, 4, 7], "3": [7, 1, 7, 1, 7], "4": [5, 5, 7, 1, 1], "5": [7, 4, 7, 1, 7], "6": [7, 4, 7, 5, 7], "7": [7, 1, 1, 2, 2], "8": [7, 5, 7, 5, 7], "9": [7, 5, 7, 1, 7],
  A: [2, 5, 7, 5, 5], B: [6, 5, 6, 5, 6], C: [3, 4, 4, 4, 3], D: [6, 5, 5, 5, 6], E: [7, 4, 6, 4, 7], F: [7, 4, 6, 4, 4], G: [3, 4, 5, 5, 3], H: [5, 5, 7, 5, 5], I: [7, 2, 2, 2, 7], J: [1, 1, 1, 5, 2], K: [5, 5, 6, 5, 5], L: [4, 4, 4, 4, 7], M: [5, 7, 7, 5, 5],
  N: [6, 5, 5, 5, 5], O: [2, 5, 5, 5, 2], P: [6, 5, 6, 4, 4], Q: [2, 5, 5, 6, 3], R: [6, 5, 6, 5, 5], S: [3, 4, 2, 1, 6], T: [7, 2, 2, 2, 2], U: [5, 5, 5, 5, 7], V: [5, 5, 5, 5, 2], W: [5, 5, 7, 7, 5], X: [5, 5, 2, 5, 5], Y: [5, 5, 2, 2, 2], Z: [7, 1, 2, 4, 7],
  "-": [0, 0, 7, 0, 0], ":": [0, 2, 0, 2, 0], ".": [0, 0, 0, 0, 2], "/": [1, 1, 2, 4, 4], "#": [5, 7, 5, 7, 5], "=": [0, 7, 0, 7, 0], ">": [4, 2, 1, 2, 4], "_": [0, 0, 0, 0, 7], "(": [1, 2, 2, 2, 1], ")": [4, 2, 2, 2, 4], "+": [0, 2, 7, 2, 0], ",": [0, 0, 0, 2, 4], " ": [0, 0, 0, 0, 0],
};
export function text(r: Raster, x: number, y: number, s: string, hex: string, scale = 2): number {
  const c = hexToRgb(hex);
  let cx = x;
  for (const ch of s.toUpperCase()) {
