}

/** Render one frame of a spec (pose + particles) into a w x h raster. */
export function renderFrame(spec: MotionSpec, pose: Pose, particles: LiveParticle[], o: { w: number; h: number; camera: Camera; theme?: ThemeName }): Raster {
