  const w = worldMatrices(spec, pose);
  for (const n of spec.rig.nodes) {
    if (!n.proxy) continue;
    const s = n.proxy.size, of = n.proxy.offset ?? [0, 0, 0];
    const box = mul(T(n.pivot[0] + of[0] - s[0] / 2, n.pivot[1] + of[1] - s[1] / 2, n.pivot[2] + of[2] - s[2] / 2), Sc(Math.max(1e-3, s[0]), Math.max(1e-3, s[1]), Math.max(1e-3, s[2])));
    const glow = Math.max(0, Math.min(1, ((pose.material[n.name]?.brightness ?? 0) / 15) + (pose.material[n.name]?.emissive ?? 0)));
    drawBox(r, v, mul(w[n.name], box), n.proxy.color, glow);
  }
  // lit emitters (brightness on a node with no box): a glow halo at the node
  const pos = nodePositions(spec, pose);
  const halos: LiveParticle[] = [];
  for (const n of spec.rig.nodes) { const b = pose.material[n.name]?.brightness ?? 0; if (!n.proxy && b > 0) halos.push({ pos: pos[n.name], size: 0.5 * (b / 15), color: "#fff1c0", age: 0, life: 1, sprite: "glow", track: -1 }); }
  drawParticles(r, v, [...particles, ...halos], o.camera);
  return { w: r.w, h: r.h, px: r.px };
}

export function blit(dst: Raster, src: Raster, x0: number, y0: number) {
  for (let y = 0; y < src.h; y++) for (let x = 0; x < src.w; x++) {
    const dx = x0 + x, dy = y0 + y;
    if (dx < 0 || dy < 0 || dx >= dst.w || dy >= dst.h) continue;
    const i = (y * src.w + x) * 4, j = (dy * dst.w + dx) * 4;
    dst.px[j] = src.px[i]; dst.px[j + 1] = src.px[i + 1]; dst.px[j + 2] = src.px[i + 2]; dst.px[j + 3] = 255;
  }
}

export type SheetOptions = { title: string; subtitle?: string; frames: SimFrame[]; pick: number[]; cols?: number; cell?: [number, number]; camera?: Camera; theme?: ThemeName };

/**
 * A contact sheet: title, a grid of the picked ticks (each labelled with tick, state and the cues of that tick) and a
 * timeline of every simulated tick (state bands, cue markers: sound cyan, particle amber, event violet).
 */
export function contactSheet(spec: MotionSpec, o: SheetOptions): Raster {
  const th = THEME[o.theme ?? "dark"];
  const [cw, ch] = o.cell ?? [256, 192];
  const cols = o.cols ?? Math.min(6, o.pick.length);
  const rows = Math.ceil(o.pick.length / cols);
  const pad = 12, head = 56, label = 34, tl = 70;
  const W = pad + cols * (cw + pad), H = head + rows * (ch + label + pad) + tl + pad;
  const out: Raster = { w: W, h: H, px: new Uint8ClampedArray(W * H * 4) };
  fillRect(out, 0, 0, W, H, th.panel);
  text(out, pad, 14, o.title, th.text, 3);
  if (o.subtitle) text(out, pad, 38, o.subtitle, th.dim, 2);
  const extra: Vec3[] = [];
  for (const t of o.pick) for (const p of o.frames[t]?.particles ?? []) extra.push(p.pos);
  const cam = o.camera ?? autoCamera(spec, { extra: extra.filter((_, i) => i % 7 === 0).slice(0, 200) });
  o.pick.forEach((t, k) => {
    const f = o.frames[t];
    if (!f) return;
    const x = pad + (k % cols) * (cw + pad), y = head + Math.floor(k / cols) * (ch + label + pad);
    const img = renderFrame(spec, f.pose ?? { nodes: {}, material: {} }, f.particles ?? [], { w: cw, h: ch, camera: cam, theme: o.theme });
    blit(out, img, x, y);
    fillRect(out, x, y + ch, cw, label, th.bg1);
    text(out, x + 6, y + ch + 5, `T${f.tick}${f.state ? ` ${f.state}` : ""}`, th.text, 2);
    const cueTxt = f.cues.map((c) => (c.kind === "sound" ? "SND" : c.kind === "particle" ? "FX" : `EV ${c.name}`)).slice(0, 3).join(" ");
    if (cueTxt) text(out, x + 6, y + ch + 20, cueTxt, th.particle, 2);
    else if (f.clip) text(out, x + 6, y + ch + 20, `${f.clip} ${f.clipTick}`, th.dim, 2);
  });
  // timeline
  const ty = H - tl - pad + 8, tx = pad, tw = W - 2 * pad, n = o.frames.length;
  fillRect(out, tx, ty, tw, 36, th.bg1);
  const xs = (t: number) => tx + Math.round((t / Math.max(1, n - 1)) * (tw - 1));
  let prev: string | null = null, startT = 0;
  const bands = ["#3b4a7a", "#4b3b7a", "#2f5a6a", "#5a4b2f", "#3b6a4b", "#6a3b4b"];
  const stateCol = new Map<string, string>();
  const flush = (end: number) => { if (prev === null) return; if (!stateCol.has(prev)) stateCol.set(prev, bands[stateCol.size % bands.length]); fillRect(out, xs(startT), ty, Math.max(1, xs(end) - xs(startT)), 14, stateCol.get(prev)!, o.theme === "light" ? 0.45 : 1); text(out, xs(startT) + 3, ty + 2, prev, th.text, 1); };
  o.frames.forEach((f, i) => { const s = f.state ?? f.clip ?? ""; if (s !== prev) { flush(i); prev = s; startT = i; } });
  flush(n - 1);
  for (const f of o.frames) for (const c of f.cues) fillRect(out, xs(f.tick), ty + (c.kind === "sound" ? 16 : c.kind === "particle" ? 22 : 28), 2, 6, c.kind === "sound" ? th.sound : c.kind === "particle" ? th.particle : th.event);
  for (const t of o.pick) fillRect(out, xs(t), ty - 4, 1, 44, th.now, 0.6);
  text(out, tx, ty + 42, `0`, th.dim, 1); const endLabel = `${n - 1} TICKS`; text(out, tx + tw - endLabel.length * 4, ty + 42, endLabel, th.dim, 1);
  text(out, tx + 40, ty + 42, "SOUND", th.sound, 1); text(out, tx + 70, ty + 42, "PARTICLES", th.particle, 1); text(out, tx + 114, ty + 42, "EVENT", th.event, 1);
  return out;
}

