// Cyrus motion core: the headless preview renderer (lib/cyrus/motion/preview.ts) and the contact-sheet scenarios
// (scripts/cyrus/motion-sheets.ts): deterministic pixels (render twice = same bytes; golden hashes), real content
// (the gun's muzzle flash lights pixels, the door's swing changes the frame, the dark and light themes differ).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { simulate } from "../lib/cyrus/motion";
import { autoCamera, contactSheet, renderFrame, text, type Raster } from "../lib/cyrus/motion/preview";
import { encodeRasterPng } from "../lib/cyrus/motion/preview-png";
import { doorSpec, gunReloadSpec } from "../lib/cyrus/motion/presets";
import { renderSheet, scenarios } from "../scripts/cyrus/motion-sheets";

const GOLDEN = path.join(__dirname, "fixtures/cyrus-motion/preview-golden.json");
const golden: Record<string, string> = existsSync(GOLDEN) ? JSON.parse(readFileSync(GOLDEN, "utf8")) : {};
const fresh: Record<string, string> = {};
const sha = (b: Buffer | Uint8ClampedArray) => createHash("sha256").update(b).digest("hex");
function gold(key: string, value: string) {
  fresh[key] = value;
  if (process.env.UPDATE_CYRUS_MOTION_GOLDEN === "1") { writeFileSync(GOLDEN, JSON.stringify({ ...golden, ...fresh }, null, 1) + "\n"); return; }
  assert.equal(value, golden[key], `golden ${key} changed (UPDATE_CYRUS_MOTION_GOLDEN=1 to accept)`);
}
const bright = (r: Raster) => { let n = 0; for (let i = 0; i < r.px.length; i += 4) if (r.px[i] > 230 && r.px[i + 1] > 210) n++; return n; };
const diff = (a: Raster, b: Raster) => { let n = 0; for (let i = 0; i < a.px.length; i += 4) if (Math.abs(a.px[i] - b.px[i]) + Math.abs(a.px[i + 1] - b.px[i + 1]) + Math.abs(a.px[i + 2] - b.px[i + 2]) > 30) n++; return n; };

describe("motion preview: headless renderer", () => {
  const gun = gunReloadSpec({ magSize: 3 }).spec;
  const sim = simulate(gun, { inputs: [{ tick: 2, event: "fire" }], ticks: 8, withPose: true, withParticles: true });
  const cam = autoCamera(gun, { yaw: 62, pitch: 16, center: [0, 0.18, -0.3], radius: 0.62, pad: 1 });
  it("is deterministic (same frame twice = same pixels)", () => {
    const a = renderFrame(gun, sim.frames[3].pose!, sim.frames[3].particles!, { w: 160, h: 120, camera: cam });
    const b = renderFrame(gun, sim.frames[3].pose!, sim.frames[3].particles!, { w: 160, h: 120, camera: cam });
    assert.equal(sha(a.px), sha(b.px));
    gold("gun.fire.t3.160x120", sha(a.px));
  });
  it("the muzzle flash lights the frame; idle does not", () => {
    const idle = renderFrame(gun, sim.frames[1].pose!, sim.frames[1].particles!, { w: 160, h: 120, camera: cam });
    const shot = renderFrame(gun, sim.frames[2].pose!, sim.frames[2].particles!, { w: 160, h: 120, camera: cam });
    assert.ok(bright(shot) > bright(idle) + 20, `${bright(shot)} vs ${bright(idle)}`);
  });
  it("the door swing changes the picture; dark and light themes differ", () => {
    const door = doorSpec().spec;
    const ds = simulate(door, { inputs: [{ tick: 1, event: "toggle" }], ticks: 16, withPose: true });
    const c = autoCamera(door, { yaw: 32, pitch: 34, center: [0, 1, -0.3], radius: 1.45, pad: 1 });
    const a = renderFrame(door, ds.frames[0].pose!, [], { w: 120, h: 120, camera: c });
    const b = renderFrame(door, ds.frames[15].pose!, [], { w: 120, h: 120, camera: c });
    assert.ok(diff(a, b) > 500, `door frames differ by ${diff(a, b)} px`);
    const l = renderFrame(door, ds.frames[0].pose!, [], { w: 120, h: 120, camera: c, theme: "light" });
    assert.ok(diff(a, l) > 5000);
  });
  it("labels draw with the built-in font", () => {
    const r: Raster = { w: 64, h: 16, px: new Uint8ClampedArray(64 * 16 * 4) };
    assert.equal(text(r, 0, 0, "T12 FIRE", "#ffffff", 1), 32);
    assert.ok(r.px.some((x) => x === 255));
  });
});

describe("motion preview: contact sheets", () => {
  it("every scenario renders a PNG deterministically (golden), gun + door + effects + gait are all there", () => {
    const ids = scenarios().map((s) => s.file);
    for (const f of ["gun-fire", "gun-last-shot-reload-cock", "door-open-close", "effects-explosion", "gait-humanoid-walk"]) assert.ok(ids.includes(f), f);
    for (const s of scenarios().filter((x) => ["gun-fire", "door-open-close"].includes(x.file))) {
      const a = renderSheet(s), b = renderSheet(s);
      assert.equal(sha(a), sha(b));
      assert.deepEqual([...a.subarray(1, 4)], [0x50, 0x4e, 0x47]);
      gold(`sheet.${s.file}`, sha(a));
    }
  });
  it("a sheet has a timeline with cue markers", () => {
    const gun = gunReloadSpec({ magSize: 3 }).spec;
    const sim = simulate(gun, { inputs: [{ tick: 2, event: "fire" }], ticks: 10, withPose: true, withParticles: true });
    const r = contactSheet(gun, { title: "T", frames: sim.frames, pick: [1, 2], cols: 2, cell: [96, 72] });
    assert.ok(r.w > 200 && r.h > 150);
    assert.ok(encodeRasterPng(r).length > 1000);
  });
});
