(async () => {
  const [src, out, jobsF] = process.argv.slice(2);
  const jobs = JSON.parse(fs.readFileSync(jobsF, "utf8"));
  const b = await chromium.launch({ args: ["--disable-gpu"] });
  for (const j of jobs) {
    const p = await b.newPage({ viewport: { width: j.w, height: j.h }, deviceScaleFactor: j.dpr || 1 });
    const errs = []; p.on("pageerror", (e) => errs.push(e.message)); p.on("console", (m) => { if (m.type() === "error") errs.push(m.text()); });
    await p.goto("file://" + path.join(src, j.file) + (j.q ? "?" + j.q : ""));
    await p.waitForTimeout(j.wait || 900);
    if (j.eval) { await p.evaluate(j.eval); await p.waitForTimeout(300); }
    if (j.click) for (const c of j.click) { await p.click(c); await p.waitForTimeout(400); }
    await p.screenshot({ path: path.join(out, j.out), fullPage: !!j.full });
    console.log(j.out, errs.length ? "ERRORS: " + errs.join(" | ") : "ok");
    await p.close();
  }
  await b.close();
})();

