// Data + frames for the v4 motion mockups (/root/agent-notes/cyrus-designs/v4-motion): everything the mockups show comes
// from the real motion core (simulation, eventLog, validation against Minecraft's capability, the Minecraft lowering's
// dropped list, the preview renderer), so the mockups are not drawings of a hoped-for engine.
//   npx tsx scripts/cyrus/motion-mock-data.ts OUT_DIR       (run on node-2 via devhost; writes data.json + PNG frames)
import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { eventLog, simulate, validateMotion, type MotionSpec } from "../../lib/cyrus/motion";
import { MOTION_PRESETS } from "../../lib/cyrus/motion/presets";
import { autoCamera, renderFrame, type ThemeName } from "../../lib/cyrus/motion/preview";
import { encodeRasterPng } from "../../lib/cyrus/motion/preview-png";
import { minecraftMotionCapability } from "../../lib/adapters-shim";
import { lowerMinecraft } from "../../lib/cyrus/designer/motion/lower";

const out = process.argv[2] ?? "tmp-motion-mock";
mkdirSync(path.join(out, "frames"), { recursive: true });

// --- (a) the gun timeline scenario: every tick rendered (dark + light) + the simulation data
const gun = MOTION_PRESETS.find((p) => p.id === "motion:gun_reload")!.build({ magSize: 3, shot: "sound:gun_pistol_shot" }).spec;
const inputs = [{ tick: 4, event: "fire" }, { tick: 10, event: "fire" }, { tick: 16, event: "fire" }, { tick: 22, event: "fire" }, { tick: 28, event: "reload" }];
const TICKS = 80;
const sim = simulate(gun, { inputs, ticks: TICKS, withPose: true, withParticles: true });
const cam = autoCamera(gun, { yaw: 58, pitch: 16, center: [0, 0.08, -0.25], radius: 0.7, pad: 1 });
for (const theme of ["dark", "light"] as ThemeName[]) for (const f of sim.frames) {
  const r = renderFrame(gun, f.pose!, f.particles!, { w: 720, h: 420, camera: cam, theme });
  writeFileSync(path.join(out, "frames", `gun-${theme}-${String(f.tick).padStart(3, "0")}.png`), encodeRasterPng(r));
}
const tracks = (s: MotionSpec) => s.clips.map((c) => ({ name: c.name, length: c.length, loop: c.loop, tracks: c.tracks.map((t) => t.kind === "transform" ? { kind: t.kind, node: t.node, channel: t.channel, keys: (t.keys ?? []).map((k) => ({ t: k.t, ease: k.ease ?? "linear", v: k.v })) , wave: !!t.wave } : t.kind === "material" ? { kind: t.kind, node: t.node, channel: t.channel, keys: t.keys.map((k) => ({ t: k.t, v: k.v })) } : t.kind === "particle" ? { kind: t.kind, node: t.node, at: t.at, duration: t.duration ?? 0, effect: t.effect ?? null, emitters: t.emitters.length } : t.kind === "sound" ? { kind: t.kind, at: t.at, sound: t.sound, gain: t.gain ?? 1, pitch: t.pitch ?? 1 } : { kind: t.kind, at: t.at, name: t.name }) }));
const mcLower = lowerMinecraft(gun, { parts: { body: { block: "minecraft:gray_concrete" } } }, { namespace: "nx_abcd1234", sounds: { gun_pistol_shot: "nx_abcd1234:gun.pistol_shot" } });
const vNeutral = validateMotion(gun), vMc = validateMotion(gun, minecraftMotionCapability);
const timeline = {
  spec: { id: gun.id, title: gun.title, nodes: gun.rig.nodes.map((n) => ({ name: n.name, parent: n.parent, kind: n.kind, hinge: n.hinge ?? null })), machine: gun.machines![0], clips: tracks(gun), params: gun.meta?.params },
  inputs, ticks: TICKS,
  frames: sim.frames.map((f) => ({ tick: f.tick, state: f.state, clip: f.clip, clipTick: f.clipTick, vars: f.vars, cues: f.cues.map((c) => ({ kind: c.kind, ...(c.kind === "sound" ? { sound: c.sound } : c.kind === "particle" ? { effect: c.effect ?? null, node: c.node } : { name: c.name }) })), particles: f.particles?.length ?? 0 })),
  log: eventLog(sim.frames),
  stats: vNeutral.stats, mcCaps: minecraftMotionCapability.caps, mcIssues: vMc.issues,
  mc: mcLower.ok ? { stats: mcLower.program.stats, dropped: mcLower.dropped, warnings: mcLower.warnings.map((w) => w.message) } : { errors: mcLower.errors },
};

// --- (b) the preset browser: one poster frame per preset (dark + light), knobs, Minecraft fit
const poster: Record<string, { tick: number; inputs: { tick: number; event: string }[]; view: Parameters<typeof autoCamera>[1]; clip?: string }> = {
  "motion:gun_fire": { tick: 1, inputs: [], view: { yaw: 58, pitch: 16, center: [0, 0.15, -0.3], radius: 0.62, pad: 1 }, clip: "fire" },
  "motion:gun_reload": { tick: 12, inputs: [{ tick: 1, event: "fire" }, { tick: 3, event: "reload" }], view: { yaw: 58, pitch: 16, center: [0, 0.05, -0.25], radius: 0.72, pad: 1 } },
  "motion:door_hinge": { tick: 9, inputs: [{ tick: 3, event: "toggle" }], view: { yaw: 32, pitch: 30, center: [0, 1, -0.3], radius: 1.45, pad: 1 } },
  "gen:gait": { tick: 14, inputs: [{ tick: 1, event: "move" }], view: { yaw: 215, pitch: 14 } },
  "effect:muzzle_flash": { tick: 1, inputs: [], view: { yaw: 70, pitch: 10, center: [0, 0, -0.5], radius: 0.8, pad: 1 }, clip: "play" },
  "effect:explosion": { tick: 3, inputs: [], view: { yaw: 35, pitch: 14, center: [0, 1.2, 0], radius: 2.6, pad: 1 }, clip: "play" },
  "effect:fire": { tick: 50, inputs: [], view: { yaw: 35, pitch: 14, center: [0, 0.7, 0], radius: 1.1, pad: 1 }, clip: "play" },
  "effect:smoke": { tick: 70, inputs: [], view: { yaw: 35, pitch: 12, center: [0, 1.4, 0], radius: 1.8, pad: 1 }, clip: "play" },
  "effect:water_splash": { tick: 5, inputs: [], view: { yaw: 35, pitch: 16, center: [0, 0.6, 0], radius: 1.3, pad: 1 }, clip: "play" },
};
const presets = MOTION_PRESETS.map((p) => {
  const { spec } = p.build();
  const pc = poster[p.id];
  const s = simulate(spec, { ...(pc.clip ? { clip: pc.clip } : {}), inputs: pc.inputs, ticks: pc.tick + 1, withPose: true, withParticles: true });
  const f = s.frames[pc.tick];
  for (const theme of ["dark", "light"] as ThemeName[]) writeFileSync(path.join(out, "frames", `preset-${p.id.replace(":", "-")}-${theme}.png`), encodeRasterPng(renderFrame(spec, f.pose!, f.particles!, { w: 360, h: 240, camera: autoCamera(spec, pc.view), theme })));
  const mc = validateMotion(spec, minecraftMotionCapability);
  const lo = lowerMinecraft(spec, {}, { namespace: "nx_abcd1234" });
  return {
    id: p.id, kind: p.kind, title: p.title, summary: p.summary, tags: p.tags, generator: p.generator, provenance: p.provenance, licence: p.licence, params: p.params,
    stats: validateMotion(spec).stats, clips: spec.clips.map((c) => ({ name: c.name, length: c.length, loop: c.loop })), states: spec.machines?.[0]?.states.map((x) => x.name) ?? [],
    events: spec.machines?.[0] ? [...new Set(spec.machines[0].transitions.map((t) => t.on))] : spec.clips.map((c) => c.name),
    minecraft: { ok: mc.ok, warnings: mc.warnings.map((w) => w.message), dropped: lo.dropped.map((d) => d.reason), errors: mc.errors.map((e) => e.message) },
  };
});
writeFileSync(path.join(out, "data.json"), JSON.stringify({ timeline, presets }, null, 1));
console.log(`frames ${sim.frames.length * 2 + presets.length * 2}, presets ${presets.length}`);

