/* Cyrus v4 Motion Studio mockups (on top of the v3 kit: kit.css, v2.css, ms.css). One accent (violet) for selection and
   primary actions; cyan ONLY for "now" (the playhead and the live state); ok/warn/bad for checks. */
.ws.mo { grid-template-columns: 248px minmax(0, 1fr) 320px; }
.mo .vp { min-height: 300px; }
.mo .vp img.frame { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; image-rendering: auto; }
.mo .tlp { flex: none; height: 286px; }
.statechip { display: inline-flex; align-items: center; gap: 7px; }
.statechip b { color: var(--cyan); font-weight: 500; }
.varchips { display: flex; gap: 6px; flex-wrap: wrap; padding: 0 14px 12px; }
.varchip { font: 500 11px/1 var(--mono); padding: 6px 8px; border-radius: 8px; border: 1px solid var(--line-2); color: var(--ink-2); background: var(--well); }
.varchip b { color: var(--ink); font-weight: 600; }
.nodes { list-style: none; margin: 0; padding: 0 8px 10px; }
.nodes li { display: flex; align-items: center; gap: 7px; height: 26px; padding: 0 8px; border-radius: 7px; font: 500 11.5px/1 var(--mono); color: var(--ink-2); }
.nodes li .k { margin-left: auto; font-size: 9.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--faint); }
.nodes li.on { background: rgb(var(--glow) / .12); color: var(--ink); box-shadow: inset 2px 0 0 var(--accent); }
.nodes li .ind { width: calc(var(--d) * 12px); flex: none; }
.nodes li .i { color: var(--muted); font-size: 13px; }
.fsm { padding: 4px 10px 6px; }
