.pcard { border-radius: 14px; overflow: hidden; cursor: pointer; display: flex; flex-direction: column; transition: transform .2s var(--ease), border-color .2s; }
.pcard:hover { border-color: var(--line-3); transform: translateY(-1px); }
.pcard.on { border-color: var(--accent-line); box-shadow: 0 0 0 1px var(--accent-line), var(--panel-shadow); }
.pcard .poster { position: relative; aspect-ratio: 3 / 2; background: var(--well); }
.pcard .poster img { width: 100%; height: 100%; object-fit: cover; display: block; }
.pcard .poster .tag { position: absolute; left: 8px; top: 8px; background: var(--surface-2); }
.pcard .body { padding: 10px 12px 12px; display: flex; flex-direction: column; gap: 6px; }
.pcard h3 { margin: 0; font: 600 14px/1.2 var(--display); color: var(--ink); }
.pcard p { margin: 0; font-size: 11.5px; line-height: 1.4; color: var(--muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.pcard .meta { display: flex; gap: 6px; flex-wrap: wrap; }
.det .poster { margin: 0 14px 12px; border-radius: 12px; overflow: hidden; border: 1px solid var(--line); aspect-ratio: 3 / 2; }
.det .poster img { width: 100%; height: 100%; object-fit: cover; display: block; }
.det h2 { margin: 0 14px 4px; font: 600 18px/1.2 var(--display); color: var(--ink); }
.det .sum { margin: 0 14px 12px; font-size: 12.5px; line-height: 1.5; color: var(--ink-2); }
.knob { display: grid; grid-template-columns: 1fr auto; gap: 6px 10px; padding: 7px 14px; align-items: center; font-size: 12px; color: var(--ink-2); }
.knob input[type=range] { grid-column: 1 / -1; width: 100%; accent-color: var(--accent-solid); }
.knob b { font: 500 11px/1 var(--mono); color: var(--ink); }
.knob .seg { grid-column: 1 / -1; }
.knob .snd { grid-column: 1 / -1; display: flex; align-items: center; gap: 6px; font: 500 11px/1 var(--mono); color: var(--ink-2); padding: 6px 8px; border-radius: 8px; border: 1px solid var(--line-2); background: var(--well); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.code { margin: 0 14px 12px; padding: 10px 12px; border-radius: 10px; background: var(--well); border: 1px solid var(--line); font: 500 11px/1.55 var(--mono); color: var(--ink-2); white-space: pre-wrap; word-break: break-word; }
