.ws.mo { grid-template-columns: 248px minmax(0, 1fr) 320px; }
.mo .vp { min-height: 300px; }
.mo .vp img.frame { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; image-rendering: auto; }
.mo .tlp { flex: none; height: 286px; }
.statechip { display: inline-flex; align-items: center; gap: 7px; }
.statechip b { color: var(--cyan); font-weight: 500; }
.varchips { display: flex; gap: 6px; flex-wrap: wrap; padding: 0 14px 12px; }
.varchip { font: 500 11px/1 var(--mono); padding: 6px 8px; border-radius: 8px; border: 1px solid var(--line-2); color: var(--ink-2); background: var(--well); }
.varchip b { color: var(--ink); font-weight: 600; }
.nodes { list-style: none; margin: 0; padding: 0 8px 10px; }
.nodes li { display: flex; align-items: center; gap: 7px; height: 26px; padding: 0 8px; border-radius: 7px; font: 500 11.5px/1 var(--mono); color: var(--ink-2); }
.nodes li .k { margin-left: auto; font-size: 9.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--faint); }
.nodes li.on { background: rgb(var(--glow) / .12); color: var(--ink); box-shadow: inset 2px 0 0 var(--accent); }
.nodes li .ind { width: calc(var(--d) * 12px); flex: none; }
.nodes li .i { color: var(--muted); font-size: 13px; }
.fsm { padding: 4px 10px 6px; }
.fsm svg { width: 100%; height: auto; display: block; }
.fsm .st rect { fill: var(--well); stroke: var(--line-2); }
.fsm .st text { fill: var(--ink-2); font: 500 9.5px var(--mono); }
.fsm .st.now rect { stroke: var(--cyan); fill: rgb(103 232 249 / .08); }
.fsm .st.now text { fill: var(--ink); }
.fsm .ed { stroke: var(--line-3); fill: none; stroke-width: 1.1; }
.fsm .ed.hot { stroke: var(--accent); stroke-width: 1.6; }
.fsm .lb { fill: var(--muted); font: 500 8.5px var(--mono); }
.evbtns { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; padding: 0 14px 10px; }
.evbtns .btn { justify-content: flex-start; }
.evbtns kbd { margin-left: auto; font: 500 10px/1 var(--mono); color: var(--faint); }
.log { font: 500 10.5px/1.55 var(--mono); color: var(--muted); padding: 0 14px 12px; max-height: 158px; overflow: auto; }
.log div { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.log div.now { color: var(--ink); }
.log div b { color: var(--ink-2); font-weight: 500; }
.tl4 .tl3-names div.grp { color: var(--faint); font-size: 9.5px; letter-spacing: .12em; text-transform: uppercase; height: 22px; }
.tl4 .tl3-names div .i { font-size: 12px; color: var(--muted); }
.tl4 .tl3-names div.sel { background: rgb(var(--glow) / .1); color: var(--ink); box-shadow: inset 2px 0 0 var(--accent); }
.tl3-h .modes { margin-left: 6px; }
.speed button { min-width: 38px; justify-content: center; }
.kv { display: grid; grid-template-columns: 92px 1fr; gap: 8px 10px; padding: 4px 14px 14px; font-size: 12px; align-items: center; }
.kv > span:nth-child(odd) { color: var(--muted); font: 500 10.5px/1 var(--mono); }
.vec3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.vec3 label { display: flex; align-items: center; gap: 5px; height: 28px; padding: 0 8px; border-radius: 8px; border: 1px solid var(--line-2); background: var(--well); font: 500 11px/1 var(--mono); color: var(--ink); }
.vec3 label i { font-style: normal; color: var(--faint); }
.easeg { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; }
.easeg button { height: 40px; border-radius: 8px; border: 1px solid var(--line-2); background: var(--well); font: 500 10px/1 var(--mono); color: var(--muted); display: grid; place-items: center; gap: 2px; }
.easeg button svg { width: 34px; height: 16px; }
.easeg button svg path { stroke: currentColor; fill: none; stroke-width: 1.4; }
.easeg button.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.note { display: flex; gap: 8px; align-items: flex-start; margin: 0 14px 14px; padding: 10px; border-radius: 10px; border: 1px dashed var(--line-2); color: var(--muted); font-size: 11.5px; line-height: 1.45; }
.note .i { flex: none; margin-top: 1px; }
