.drops { margin: 0 14px 12px; padding: 0; list-style: none; font-size: 11.5px; color: var(--ink-2); }
.drops li { display: flex; gap: 8px; padding: 6px 0; border-bottom: 1px solid var(--line); }
.drops li .i { color: var(--warn); flex: none; margin-top: 2px; }
.meters { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 12px; padding: 0 14px 14px; }
/* presets */
.ws.pr { grid-template-columns: 220px minmax(0, 1fr) 360px; }
