.filters button.on { background: rgb(var(--glow) / .12); color: var(--ink); box-shadow: inset 2px 0 0 var(--accent); }
.search { display: flex; align-items: center; gap: 8px; height: 38px; margin: 0 0 12px; padding: 0 12px; border-radius: 12px; }
.search input { flex: 1; background: none; border: 0; outline: 0; color: var(--ink); font-size: 13px; }
