// Cyrus v4 Motion Studio mockups: shared bits. Everything drawn here comes from window.DATA / window.FRAMES, produced by
// the real motion core (scripts/cyrus/motion-mock-data.ts): the simulation frames, event log, lowering report and the
// software-rendered frames.
(function () {
  Object.assign(window.ICONS, {
    motion: '<path d="M4 17c3-9 6-9 8-4s5 5 8-4" /><circle cx="4" cy="17" r="1.6" fill="currentColor"/><circle cx="20" cy="9" r="1.6" fill="currentColor"/>',
    hinge: '<rect x="5" y="3.5" width="9" height="17" rx="1.5" fill="currentColor" fill-opacity="0.2"/><path d="M14 6v12M17 8.5c1.6 1 2.5 2.2 2.5 3.5s-.9 2.5-2.5 3.5"/>',
    emitter: '<circle cx="12" cy="12" r="2.6" fill="currentColor" fill-opacity="0.35"/><path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M5.6 18.4l2.1-2.1M16.3 7.7l2.1-2.1"/>',
    part: '<path d="M12 3.2 19.6 7.6v8.8L12 20.8l-7.6-4.4V7.6Z" fill="currentColor" fill-opacity="0.2"/><path d="M4.4 7.6 12 12l7.6-4.4M12 12v8.8"/>',
    socket: '<circle cx="12" cy="12" r="6.5"/><circle cx="12" cy="12" r="2" fill="currentColor"/>',
    stepb: '<path d="M7 5v14M18 6l-8 6 8 6Z" fill="currentColor" fill-opacity="0.2"/>',
    stepf: '<path d="M17 5v14M6 6l8 6-8 6Z" fill="currentColor" fill-opacity="0.2"/>',
    gun: '<path d="M3 8h15l2 2.5H13l-1 3h-3l-1.5 5H4l1.5-5.5L3 11Z" fill="currentColor" fill-opacity="0.2"/><path d="M18 8V6.5"/>',
    bolt: '<path d="M13 3 5 14h6l-1 7 8-11h-6Z" fill="currentColor" fill-opacity="0.2"/>',
    door: '<path d="M6 21V4.5A1.5 1.5 0 0 1 7.5 3h9A1.5 1.5 0 0 1 18 4.5V21" fill="currentColor" fill-opacity="0.15"/><path d="M3.5 21h17M14.5 12.5h.01"/>',
    paw: '<circle cx="7" cy="9" r="1.8"/><circle cx="12" cy="7" r="1.8"/><circle cx="17" cy="9" r="1.8"/><path d="M8 16c0-2.5 1.8-4.5 4-4.5s4 2 4 4.5c0 1.8-1.6 2.5-4 2.5s-4-.7-4-2.5Z" fill="currentColor" fill-opacity="0.2"/>',
    flame: '<path d="M12 3c1 3.5 5 5 5 10a5 5 0 0 1-10 0c0-2.5 1.5-3.5 2-5.5 1 1 1.5 2 1.5 3.5C12.5 9 12 6 12 3Z" fill="currentColor" fill-opacity="0.2"/>',
    drop: '<path d="M12 3.5c3 4 5.5 7 5.5 10a5.5 5.5 0 0 1-11 0c0-3 2.5-6 5.5-10Z" fill="currentColor" fill-opacity="0.2"/>',
    cloud2: '<path d="M7 18a4 4 0 0 1-.6-8 5.5 5.5 0 0 1 10.6-1.2A4.2 4.2 0 0 1 17 18Z" fill="currentColor" fill-opacity="0.2"/>',
    boom: '<path d="m12 2 2 5 5-2-2 5 5 2-5 2 2 5-5-2-2 5-2-5-5 2 2-5-5-2 5-2-2-5 5 2Z" fill="currentColor" fill-opacity="0.2"/>',
  });
  // Cyrus top bar with the studio switch (Texture / Sound / Model / Motion)
  window.moTop = (crumbs) => cyTop(crumbs,
    `<div class="seg glass-soft hide-n" aria-label="Studio"><button>${I("image")}Texture</button><button>${I("wave")}Sound</button><button>${I("cube")}Model</button><button class="on">${I("motion")}Motion</button></div>
     <a class="chip glass-soft hide-n">${I("package")}Mod assets</a>`);
  window.pad3 = (n) => String(n).padStart(3, "0");
  window.frameUri = (name) => (window.FRAMES || {})[name] || "";
  window.themeName = () => (document.documentElement.dataset.theme === "light" ? "light" : "dark");
  window.kindIcon = (k) => ({ part: "part", bone: "bone", hinge: "hinge", emitter: "emitter", socket: "socket", seat: "socket", wheel: "rotate" }[k] || "part");
  window.presetIcon = (id) => ({ "motion:gun_fire": "gun", "motion:gun_reload": "gun", "motion:door_hinge": "door", "gen:gait": "paw", "effect:muzzle_flash": "bolt", "effect:explosion": "boom", "effect:fire": "flame", "effect:smoke": "cloud2", "effect:water_splash": "drop" }[id] || "motion");
  window.easeSvg = (e) => {
    const f = { linear: (x) => x, step: (x) => (x >= 1 ? 1 : 0), in: (x) => x * x * x, out: (x) => 1 - (1 - x) ** 3, inout: (x) => (x < 0.5 ? 4 * x * x * x : 1 - (-2 * x + 2) ** 3 / 2), smooth: (x) => x * x * (3 - 2 * x) }[e];
    let d = "";
    for (let i = 0; i <= 20; i++) { const x = i / 20, y = e === "step" ? (i < 20 ? 0 : 1) : f(x); d += `${i ? "L" : "M"}${(2 + x * 30).toFixed(1)} ${(14 - y * 12).toFixed(1)}`; }
    if (e === "step") d = "M2 14 L31 14 L31 2 L32 2";
    return `<svg viewBox="0 0 34 16"><path d="${d}"/></svg>`;
  };
})();

