export function sampleTransform(t: Pick<TransformTrack, "channel" | "wave"> & { keys?: readonly { t: number; v: readonly number[]; ease: "linear" | "smooth" }[] }, clip: { length: number }, time: number): Vec3 {
  const base = t.channel === "scale" ? 1 : 0;
  if (t.wave) {
