      { kind: "light" as const, target: "muzzle", property: "intensity" as const, keys: [{ id: "l1", t: 0, v: 0, ease: "linear" as const }, { id: "l2", t: 0.1, v: 1, ease: "linear" as const }] },
      { kind: "state" as const, machine: "gun", changes: [{ id: "x1", t: 0, state: "firing" }] },
