    assert.deepEqual(r.clip.tracks.map((t) => t.kind), ["transform", "sound", "particle", "material", "event", "event"]);
    const p = r.clip.tracks[2] as { effect?: string; emitters: unknown[]; at: number };
    assert.equal(p.effect, "effect:muzzle_flash"); assert.equal(p.at, 4); assert.equal(p.emitters.length, 3);
